import lombok.Data;

@Data
public class CardDefinition
{
	private String name;
	@JsonAdapter(CategoryListTypeAdapter.class)
	private List<String> category;
	private String imageUrl;
	private Integer level;
	private Long value;
	/** When set, {@code RarityMath.score} uses this instead of the level-derived contribution. */
	private Long overrideScore;
	private String examine;
	private Boolean questItem;
	/** Defence level needed to equip the item; absent means none (wearable at 1 Defence). */
	private Integer defenceRequirement;
	/** Food and potions, which are only in play while the consumable lock is switched on. */
	private Boolean consumable;

	public boolean isConsumableCard()
	{
		return Boolean.TRUE.equals(consumable);
	}
	/**
	 * Other in-game item names this one card covers — untradeable or cosmetic variants, and the
	 * members of a family bundled onto a single card. Owning the card unlocks every alias.
	 */
	private List<String> aliases;

	public List<String> getAliasNames()
	{
		return aliases == null ? Collections.emptyList() : aliases;
	}

	/** Defence requirement as a plain level, treating an absent value as no requirement. */
	public int defenceRequirementLevel()
	{
		return defenceRequirement == null ? 0 : defenceRequirement;
	}

	public List<String> getCategoryTags()
	{
		return category == null ? Collections.emptyList() : category;
	}

	/** First category tag (normalized display), for grouping and logging. */
	public String getPrimaryCategory()
	{
		List<String> tags = getCategoryTags();
		if (tags.isEmpty())
		{
			return "Unknown";
		}
		List<String> parts = CategoryTagUtil.expandCompoundParts(tags.get(0));
		if (parts.isEmpty())
		{
			return "Unknown";
		}
		String canon = CategoryTagUtil.canonicalKey(parts.get(0));
		return CategoryTagUtil.toDisplayLabel(canon);
	}
}

package com.bronzemanpvptcg.data;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Deserializes {@code "category"} from either a JSON string or array of strings into a {@link List}.
 */
public final class CategoryListTypeAdapter extends TypeAdapter<List<String>>
{
	@Override
	public void write(JsonWriter out, List<String> value) throws IOException
	{
		if (value == null)
		{
			out.nullValue();
			return;
		}
		out.beginArray();
		for (String s : value)
		{
			out.value(s);
		}
		out.endArray();
	}

	@Override
	public List<String> read(JsonReader in) throws IOException
	{
		JsonToken peek = in.peek();
		if (peek == JsonToken.NULL)
		{
			in.nextNull();
			return Collections.emptyList();
		}
		if (peek == JsonToken.STRING)
		{
			return Collections.singletonList(in.nextString());
		}
		if (peek == JsonToken.BEGIN_ARRAY)
		{
			List<String> out = new ArrayList<>();
			in.beginArray();
			while (in.hasNext())
			{
				if (in.peek() == JsonToken.STRING)
				{
					out.add(in.nextString());
				}
				else
				{
					in.skipValue();
				}
			}
			in.endArray();
			return out;
		}
		in.skipValue();
		return Collections.emptyList();
	}
}

package com.bronzemanpvptcg.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * Normalizes category strings for matching and UI: splits {@code &} compounds, case-fold keys, title-cased labels.
 */
public final class CategoryTagUtil
{
	private CategoryTagUtil()
	{
	}

	/**
	 * Splits a raw tag on {@code '&'} into trimmed non-empty pieces (e.g. {@code "A&B"} → {@code A}, {@code B}).
	 */
	public static List<String> expandCompoundParts(String raw)
	{
		if (raw == null)
		{
			return Collections.emptyList();
		}
		String s = raw.trim();
		if (s.isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>(4);
		for (String piece : s.split("&"))
		{
			String t = piece.trim();
			if (!t.isEmpty())
			{
				out.add(t);
			}
		}
		return out;
	}

	public static String canonicalKey(String singleTagPart)
	{
		if (singleTagPart == null)
		{
			return "";
		}
		return singleTagPart.trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * Each whitespace-separated word: first character upper case, remainder lower case ({@link Locale#ROOT}).
	 */
	public static String toDisplayLabel(String canonicalKey)
	{
		if (canonicalKey == null || canonicalKey.isEmpty())
		{
			return "";
		}
		String[] words = canonicalKey.split("\\s+");
		StringBuilder sb = new StringBuilder();
		for (String w : words)
		{
			if (w.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(Character.toUpperCase(w.charAt(0)));
			if (w.length() > 1)
			{
				sb.append(w.substring(1).toLowerCase(Locale.ROOT));
			}
		}
		return sb.length() == 0 ? canonicalKey : sb.toString();
	}
}

package com.bronzemanpvptcg.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class PackCatalog
{
	private static final Type PACK_LIST_TYPE = new TypeToken<List<BoosterPackDefinition>>() { }.getType();

	private final Gson gson;
	private List<BoosterPackDefinition> boosters = Collections.emptyList();
	private boolean loaded;

	@Inject
	public PackCatalog(Gson gson)
	{
		this.gson = gson;
	}

	public synchronized void load()
	{
		if (loaded)
		{
			return;
		}

		List<BoosterPackDefinition> merged = new ArrayList<>();
		int fromMain = appendPackResource(merged, "/Packs.json", false);
		int fromDebug = appendPackResource(merged, "/PacksDebug.json", true);
		boosters = Collections.unmodifiableList(merged);
		loaded = true;
		log.info("Loaded {} booster pack definitions ({} from Packs.json, {} from PacksDebug.json)",
			boosters.size(), fromMain, fromDebug);
	}

	public synchronized List<BoosterPackDefinition> getBoosters()
	{
		return boosters;
	}

	/** Production packs plus {@code debugOnly} entries when {@code debugLogging} is enabled. */
	public synchronized List<BoosterPackDefinition> getVisibleBoosters(boolean debugLogging)
	{
		if (boosters.isEmpty())
		{
			return boosters;
		}
		List<BoosterPackDefinition> visible = new ArrayList<>();
		for (BoosterPackDefinition booster : boosters)
		{
			if (booster == null)
			{
				continue;
			}
			if (!booster.isDebugOnly() || debugLogging)
			{
				visible.add(booster);
			}
		}
		return Collections.unmodifiableList(visible);
	}

	public synchronized void setBoostersForTesting(List<BoosterPackDefinition> testBoosters)
	{
		boosters = testBoosters == null ? Collections.emptyList() : Collections.unmodifiableList(testBoosters);
		loaded = true;
	}

	private int appendPackResource(List<BoosterPackDefinition> target, String resourcePath, boolean markDebugOnly)
	{
		try (Reader reader = openClasspathReader(resourcePath))
		{
			if (reader == null)
			{
				return 0;
			}
			List<BoosterPackDefinition> parsed = gson.fromJson(reader, PACK_LIST_TYPE);
			if (parsed == null || parsed.isEmpty())
			{
				return 0;
			}
			int count = 0;
			for (BoosterPackDefinition booster : parsed)
			{
				if (booster == null)
				{
					continue;
				}
				if (markDebugOnly)
				{
					booster.setDebugOnly(true);
				}
				target.add(booster);
				count++;
			}
			return count;
		}
		catch (IOException | JsonSyntaxException ex)
		{
			log.warn("Failed reading {} from classpath", resourcePath, ex);
			return 0;
		}
	}

	private Reader openClasspathReader(String resourcePath)
	{
		InputStream stream = getClass().getResourceAsStream(resourcePath);
		if (stream == null)
		{
			if ("/Packs.json".equals(resourcePath))
			{
				log.warn("Packs.json resource missing from plugin classpath");
			}
			return null;
		}
		return new InputStreamReader(stream, StandardCharsets.UTF_8);
	}
}

package com.bronzemanpvptcg.model;

import java.util.Objects;

public final class CardCollectionKey
{
	private final String cardName;
	private final boolean foil;

	public CardCollectionKey(String cardName, boolean foil)
	{
		this.cardName = cardName == null ? "" : cardName;
		this.foil = foil;
	}

	public String getCardName()
	{
		return cardName;
	}

	public boolean isFoil()
	{
		return foil;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof CardCollectionKey))
		{
			return false;
		}
		CardCollectionKey that = (CardCollectionKey) o;
		return foil == that.foil && Objects.equals(cardName, that.cardName);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(cardName, foil);
	}
}

