package com.bronzemanpvptcg.model;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Builds and expands {@link CardEntry} rows for profile persistence. */
public final class CardEntrySerializer
{
	private CardEntrySerializer()
	{
	}

	public static List<CardEntry> buildProfileEntries(List<OwnedCardInstance> instances)
	{
		return buildEntries(instances);
	}

	public static List<OwnedCardInstance> expandToInstances(List<CardEntry> entries)
	{
		List<OwnedCardInstance> rows = new ArrayList<>();
		if (entries == null)
		{
			return rows;
		}
		for (CardEntry entry : entries)
		{
			if (entry == null || entry.cardName == null || entry.cardName.trim().isEmpty() || entry.variants == null)
			{
				continue;
			}
			String cardName = entry.cardName.trim();
			for (CardVariant variant : entry.variants)
			{
				if (variant == null)
				{
					continue;
				}
				String by = variant.pulledBy == null ? "" : variant.pulledBy;
				long at = variant.pulledAt == null || variant.pulledAt <= 0L ? 0L : variant.pulledAt;
				int quantity = variant.quantity == null ? 1 : Math.max(0, variant.quantity);
				if (quantity <= 0)
				{
					continue;
				}
				boolean legacyLockedQty = variant.lockedQuantity != null;
				int lockedQty = legacyLockedQty
					? Math.min(quantity, Math.max(0, variant.lockedQuantity))
					: (Boolean.TRUE.equals(variant.locked) ? 1 : 0);
				for (int i = 0; i < quantity; i++)
				{
					boolean locked = legacyLockedQty ? i < lockedQty : Boolean.TRUE.equals(variant.locked);
					rows.add(OwnedCardInstance.createNew(cardName, isFoil(variant), by, at).withLocked(locked));
				}
			}
		}
		return rows;
	}

	private static List<CardEntry> buildEntries(List<OwnedCardInstance> instances)
	{
		if (instances == null || instances.isEmpty())
		{
			return List.of();
		}

		List<OwnedCardInstance> sorted = new ArrayList<>();
		for (OwnedCardInstance inst : instances)
		{
			if (inst == null || inst.getCardName() == null || inst.getCardName().trim().isEmpty())
			{
				continue;
			}
			sorted.add(inst);
		}
		if (sorted.isEmpty())
		{
			return List.of();
		}

		sorted.sort(Comparator
			.comparing(OwnedCardInstance::getCardName, String.CASE_INSENSITIVE_ORDER)
			.thenComparing(OwnedCardInstance::isFoil)
			.thenComparingLong(OwnedCardInstance::getPulledAtEpochMs)
			.thenComparing(OwnedCardInstance::getPulledByUsername, Comparator.nullsFirst(String::compareToIgnoreCase)));

		Map<String, CardEntry> byName = new LinkedHashMap<>();
		for (OwnedCardInstance inst : sorted)
		{
			String cardName = inst.getCardName().trim();
			CardEntry entry = byName.computeIfAbsent(cardName, n ->
			{
				CardEntry e = new CardEntry();
				e.cardName = n;
				e.variants = new ArrayList<>();
				return e;
			});

			CardVariant variant = new CardVariant();
			variant.foil = inst.isFoil() ? Boolean.TRUE : null;
			String by = inst.getPulledByUsername() == null ? "" : inst.getPulledByUsername();
			variant.pulledBy = by.isEmpty() ? null : by;
			long at = inst.getPulledAtEpochMs();
			variant.pulledAt = at <= 0L ? null : at;
			if (inst.isLocked())
			{
				variant.locked = Boolean.TRUE;
			}
			entry.variants.add(variant);
		}

		for (CardEntry entry : byName.values())
		{
			entry.variants.sort(Comparator
				.comparing(CardEntrySerializer::isFoil)
				.thenComparing(v -> v.pulledAt == null ? 0L : v.pulledAt)
				.thenComparing(v -> v.pulledBy == null ? "" : v.pulledBy, String.CASE_INSENSITIVE_ORDER));
		}

		return new ArrayList<>(byName.values());
	}

	private static boolean isFoil(CardVariant variant)
	{
		return variant != null && Boolean.TRUE.equals(variant.foil);
	}
}

package com.bronzemanpvptcg.model;

/**
 * One owned copy of a card within a {@link CardEntry} group (profile save schema).
 */
public final class CardVariant
{
	/** Omitted when false; absent or null means normal. */
	public Boolean foil;
	public String pulledBy;
	public Long pulledAt;
	/** Omitted when false. */
	public Boolean locked;
	/** Legacy profile save: expanded on load when present. */
	public Integer quantity;
	/** Legacy profile save: expanded on load when present. */
	public Integer lockedQuantity;
}

package com.bronzemanpvptcg.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Collection backed by individual {@link OwnedCardInstance} rows (quantities are aggregated for overview / album counts).
 */
public final class CollectionState
{
	private final List<OwnedCardInstance> instances;
	private final Map<CardCollectionKey, Integer> ownedCards;
	private final Map<CardCollectionKey, Long> lastObtainedAt;

	private CollectionState(List<OwnedCardInstance> instances)
	{
		List<OwnedCardInstance> copy = new ArrayList<>();
		if (instances != null)
		{
			for (OwnedCardInstance i : instances)
			{
				if (i != null && i.getCardName() != null && !i.getCardName().trim().isEmpty())
				{
					copy.add(i);
				}
			}
		}
		this.instances = Collections.unmodifiableList(copy);
		this.ownedCards = Collections.unmodifiableMap(aggregateQuantities(copy));
		this.lastObtainedAt = Collections.unmodifiableMap(maxPulledAt(copy));
	}

	public static CollectionState empty()
	{
		return new CollectionState(List.of());
	}

	public static CollectionState copyOf(List<OwnedCardInstance> instances)
	{
		return new CollectionState(instances);
	}

	public List<OwnedCardInstance> getOwnedInstances()
	{
		return instances;
	}

	public List<OwnedCardInstance> instancesForCardName(String cardName)
	{
		if (cardName == null || cardName.trim().isEmpty())
		{
			return List.of();
		}
		String n = cardName.trim();
		List<OwnedCardInstance> out = new ArrayList<>();
		for (OwnedCardInstance i : instances)
		{
			if (n.equals(i.getCardName()))
			{
				out.add(i);
			}
		}
		return Collections.unmodifiableList(out);
	}

	public java.util.Optional<OwnedCardInstance> findInstanceById(String instanceId)
	{
		if (instanceId == null || instanceId.isEmpty())
		{
			return java.util.Optional.empty();
		}
		for (OwnedCardInstance i : instances)
		{
			if (instanceId.equals(i.getInstanceId()))
			{
				return java.util.Optional.of(i);
			}
		}
		return java.util.Optional.empty();
	}

	public Map<CardCollectionKey, Integer> getOwnedCards()
	{
		return ownedCards;
	}

	public long getLastObtainedAt(CardCollectionKey key)
	{
		if (key == null)
		{
			return 0L;
		}
		return lastObtainedAt.getOrDefault(key, 0L);
	}

	public Map<CardCollectionKey, Long> getLastObtainedMap()
	{
		return lastObtainedAt;
	}

	public CollectionState withInstanceAdded(OwnedCardInstance instance)
	{
		if (instance == null)
		{
			return this;
		}
		List<OwnedCardInstance> next = new ArrayList<>(instances);
		next.add(instance);
		return new CollectionState(next);
	}

	public CollectionState withInstancesAdded(List<OwnedCardInstance> toAdd)
	{
		if (toAdd == null || toAdd.isEmpty())
		{
			return this;
		}
		List<OwnedCardInstance> next = new ArrayList<>(instances);
		next.addAll(toAdd);
		return new CollectionState(next);
	}

	public CollectionState withInstanceRemoved(String instanceId)
	{
		if (instanceId == null || instanceId.isEmpty())
		{
			return this;
		}
		List<OwnedCardInstance> next = new ArrayList<>(instances);
		next.removeIf(i -> instanceId.equals(i.getInstanceId()));
		return new CollectionState(next);
	}

	public CollectionState withInstanceLockToggled(String instanceId)
	{
		if (instanceId == null || instanceId.isEmpty())
		{
			return this;
		}
		List<OwnedCardInstance> next = new ArrayList<>(instances.size());
		boolean changed = false;
		for (OwnedCardInstance i : instances)
		{
			if (instanceId.equals(i.getInstanceId()))
			{
				next.add(i.withLocked(!i.isLocked()));
				changed = true;
			}
			else
			{
				next.add(i);
			}
		}
		return changed ? new CollectionState(next) : this;
	}

	/**
	 * Returns a collection with instances removed whose provenance is debug-marked ({@link OwnedCardInstance#hasDebugPullMetadata}).
	 */
	public CollectionState withoutDebugProvenanceRows()
	{
		List<OwnedCardInstance> next = new ArrayList<>();
		for (OwnedCardInstance i : instances)
		{
			if (!OwnedCardInstance.hasDebugPullMetadata(i.getPulledByUsername()))
			{
				next.add(i);
			}
		}
		if (next.size() == instances.size())
		{
			return this;
		}
		return new CollectionState(next);
	}

	public CollectionState withInstances(List<OwnedCardInstance> replacement)
	{
		return new CollectionState(replacement);
	}

	private static Map<CardCollectionKey, Integer> aggregateQuantities(List<OwnedCardInstance> list)
	{
		Map<CardCollectionKey, Integer> map = new HashMap<>();
		for (OwnedCardInstance i : list)
		{
			CardCollectionKey key = new CardCollectionKey(i.getCardName(), i.isFoil());
			map.merge(key, 1, Integer::sum);
		}
		return map;
	}

	private static Map<CardCollectionKey, Long> maxPulledAt(List<OwnedCardInstance> list)
	{
		Map<CardCollectionKey, Long> map = new HashMap<>();
		for (OwnedCardInstance i : list)
		{
			CardCollectionKey key = new CardCollectionKey(i.getCardName(), i.isFoil());
			map.merge(key, i.getPulledAtEpochMs(), Math::max);
		}
		return map;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof CollectionState))
		{
			return false;
		}
		CollectionState that = (CollectionState) o;
		return instances.equals(that.instances);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(instances);
	}
}

package com.bronzemanpvptcg.model;

/**
 * Self-imposed Defence cap for the card pool. Cards whose item needs more Defence than this to
 * equip are removed from the roll pool, so they can never be pulled from a pack.
 */
public enum DefenceLevel
{
	LEVEL_1("1 Defence", 1),
	LEVEL_20("20 Defence", 20),
	LEVEL_30("30 Defence", 30),
	LEVEL_40("40 Defence", 40),
	LEVEL_50("50 Defence", 50),
	LEVEL_60_PLUS("60+ Defence", Integer.MAX_VALUE);

	private final String label;
	private final int maxRequirement;

	DefenceLevel(String label, int maxRequirement)
	{
		this.label = label;
		this.maxRequirement = maxRequirement;
	}

	/** Highest {@code defenceRequirement} a card may carry and still be pullable. */
	public int getMaxRequirement()
	{
		return maxRequirement;
	}

	/** True when every card qualifies, so the pool needs no filtering pass. */
	public boolean isUnrestricted()
	{
		return maxRequirement == Integer.MAX_VALUE;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

