import javax.inject.Singleton;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.ImageUtil;

/**
 * Movable plain-text overlay for current credits and a short-window credits/h rate.
 * Shift+right-click lists visible booster packs to buy and open.
 */
@Singleton
public class CreditsInfoboxOverlay extends OverlayPanel
{
	public static final String MENU_OPTION_OPEN = "Open";

	/** Wilderness overhead skull; square so the 25x25 source is not squashed. */
	private static final BufferedImage CREDIT_ICON = ImageUtil.resizeImage(
		ImageUtil.loadImageResource(CreditsInfoboxOverlay.class, "/credits.png"),
		16,
		16);

	private final OsrsTcgConfig config;
	private final TcgStateService stateService;
	private final CreditsRateTracker creditsRateTracker;
	private final PackCatalog packCatalog;

	@Inject
	CreditsInfoboxOverlay(
		OsrsTcgConfig config,
		TcgStateService stateService,
		CreditsRateTracker creditsRateTracker,
		PackCatalog packCatalog)
	{
		this.config = config;
		this.stateService = stateService;
		this.creditsRateTracker = creditsRateTracker;
		this.packCatalog = packCatalog;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.creditsInfobox())
		{
			getMenuEntries().clear();
			return null;
		}

		refreshPackMenuEntries();

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(SplitComponent.builder()
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(4, 0))
			.first(new ImageComponent(CREDIT_ICON))
			.second(LineComponent.builder()
				.right(NumberFormatting.format(stateService.getCredits()))
				.build())
			.build());

		if (config.creditsPerHour())
		{
			Long creditsPerHour = creditsRateTracker.creditsPerHourOrNull();
			if (creditsPerHour != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.right(NumberFormatting.format(creditsPerHour) + "/h")
					.build());
			}
		}

		return super.render(graphics);
	}

	/** Display name used as the overlay menu target for a pack. */
	public static String packMenuTarget(BoosterPackDefinition booster)
	{
		if (booster == null)
		{
			return "";
		}
		if (booster.getName() != null && !booster.getName().isBlank())
		{
			return booster.getName();
		}
		if (booster.getId() != null && !booster.getId().isBlank())
		{
			return booster.getId();
		}
		return "Pack";
	}

	private void refreshPackMenuEntries()
	{
		getMenuEntries().clear();
		for (BoosterPackDefinition booster : packCatalog.getVisibleBoosters(stateService.isDebugLogging()))
		{
			addMenuEntry(MenuAction.RUNELITE_OVERLAY, MENU_OPTION_OPEN, packMenuTarget(booster));
		}
	}
}

package com.bronzemanpvptcg.overlay;

import com.bronzemanpvptcg.service.PackRevealService;
import com.bronzemanpvptcg.ui.TcgPanel;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;

@Singleton
public class PackRevealInputListener implements MouseListener, KeyListener, MouseWheelListener
{
	private final PackRevealService revealService;
	private final PackRevealOverlay overlay;
	private final TcgPanel tcgPanel;

	@Inject
	public PackRevealInputListener(PackRevealService revealService, PackRevealOverlay overlay, TcgPanel tcgPanel)
	{
		this.revealService = revealService;
		this.overlay = overlay;
		this.tcgPanel = tcgPanel;
	}

	private boolean revealBlocksGameInput()
	{
		return revealService.isActive();
	}

	private void syncRevealHoverCanvasFromEvent(java.awt.event.MouseEvent e)
	{
		if (e == null)
		{
			return;
		}
		if (!revealBlocksGameInput())
		{
			overlay.setRevealHoverCanvasPoint(null);
			return;
		}
		overlay.setRevealHoverCanvasPoint(e.getPoint());
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}

		if (mouseEvent.getButton() == MouseEvent.BUTTON3)
		{
			if (revealService.revealAllCards())
			{
				tcgPanel.refreshAfterPackRevealClose();
			}
			mouseEvent.consume();
			return mouseEvent;
		}

		if (mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			revealService.handleClick(mouseEvent.getPoint(), overlay.currentPackBounds(), overlay.currentCardBounds());
			tcgPanel.refreshAfterPackRevealClose();
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent mouseEvent)
	{
		if (!revealBlocksGameInput() || mouseEvent == null)
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent mouseEvent)
	{
		if (mouseEvent == null)
		{
			return mouseEvent;
		}
		syncRevealHoverCanvasFromEvent(mouseEvent);
		if (!revealBlocksGameInput())
		{
			return mouseEvent;
		}
		mouseEvent.consume();
		return mouseEvent;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		if (event == null)
		{
			return event;
		}
		syncRevealHoverCanvasFromEvent(event);
		if (!revealBlocksGameInput())
		{
			return event;
		}
		overlay.nudgeSessionPackZoom(event.getWheelRotation());
		event.consume();
		return event;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		e.consume();
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE || e.getKeyCode() == KeyEvent.VK_SPACE)
		{
			revealService.advanceFromKeyboard();
			tcgPanel.refreshAfterPackRevealClose();
		}
		e.consume();
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (!revealBlocksGameInput() || e == null)
		{
			return;
		}
		e.consume();
	}
}

