/**
 * Adds an icon button to the bank that opens an in-bank grid of every item you have unlocked,
 * drawn with the real item sprites. Item ids come from a one-off scan of the client's item
 * definitions, matched against card names and their aliases.
 */
@Slf4j
@Singleton
public final class BankUnlocksButtonService
{
	private static final int BUTTON_SIZE = 24;
	/** Offsets from the bank window's top-right, clear of the existing tab row. */
	private static final int BUTTON_MARGIN_X = 68;
	private static final int BUTTON_MARGIN_Y = 4;
	/** Custom sprite slot for the plugin icon; negative ids never collide with cache sprites. */
	private static final int ICON_SPRITE_ID = -1401;


	private final Client client;
	private final ClientThread clientThread;
	private final CardDatabase cardDatabase;
	private final TcgStateService stateService;
	private final BronzemanEquipLockService equipLockService;
	private final ChatMessageManager chatMessageManager;

	/** Lower-case item name -> lowest matching item id; built once, then reused. */
	private final Map<String, Integer> itemIdByName = new ConcurrentHashMap<>();
	private boolean itemIndexBuilt;
	private boolean filterActive;
	/** Guards against re-entering the filter from a script we ourselves triggered. */
	private boolean applyingFilter;
	/** Slot layout before filtering, so toggling off restores the client's own arrangement. */
	private final Map<Integer, int[]> originalSlotPositions = new java.util.HashMap<>();

	/** Bank grid geometry, matching the client's own layout. */
	private static final int ITEMS_PER_ROW = 8;
	private static final int ITEM_X_SPACING = 48;
	private static final int ITEM_Y_SPACING = 36;
	private static final int ITEM_ROW_START = 51;
	private static final int ITEM_Y_START = 0;

	@Inject
	public BankUnlocksButtonService(
		Client client,
		ClientThread clientThread,
		CardDatabase cardDatabase,
		TcgStateService stateService,
		BronzemanEquipLockService equipLockService,
		ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.cardDatabase = cardDatabase;
		this.stateService = stateService;
		this.equipLockService = equipLockService;
		this.chatMessageManager = chatMessageManager;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			filterActive = false;
			clientThread.invokeLater(this::addButton);
		}
	}

	private void addButton()
	{
		Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (parent == null)
		{
			return;
		}

		registerIconSprite();

		Widget button = parent.createChild(-1, WidgetType.GRAPHIC);
		button.setSpriteId(ICON_SPRITE_ID);
		button.setOriginalWidth(BUTTON_SIZE);
		button.setOriginalHeight(BUTTON_SIZE);
		button.setOriginalX(parent.getWidth() - BUTTON_MARGIN_X);
		button.setOriginalY(BUTTON_MARGIN_Y);
		button.setHasListener(true);
		button.setNoClickThrough(true);
		button.setAction(0, "Show only unlocked items");
		button.setOnOpListener((JavaScriptCallback) e -> togglePanel());
		button.setOnMouseOverListener((JavaScriptCallback) e -> button.setOpacity(40));
		button.setOnMouseLeaveListener((JavaScriptCallback) e -> button.setOpacity(0));
		button.revalidate();
	}

	private void togglePanel()
	{
		filterActive = !filterActive;
		if (filterActive)
		{
			applyBankFilter();
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Bank filtered to your unlocked items. Click the icon again to show everything.");
		}
		else
		{
			restoreBank();
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, "Bank filter off.");
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// The bank redraws on search, tab change and deposits; re-apply so the filter sticks.
		if (filterActive && event.getScriptId() == ScriptID.BANKMAIN_BUILD)
		{
			clientThread.invokeLater(this::applyBankFilter);
		}
	}

	/**
	 * Hides every bank slot whose item is not unlocked and repacks the survivors into a gapless
	 * grid, the way the bank-tag plugins filter. Scroll height is recomputed so the bar matches.
	 */
	private void applyBankFilter()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.getDynamicChildren() == null || applyingFilter)
		{
			return;
		}

		// revalidate() can make the client re-run the bank build script, which lands us back in
		// onScriptPostFired; without this guard that recurses until the client locks up.
		applyingFilter = true;
		try
		{
			filterSlots(container);
		}
		catch (RuntimeException ex)
		{
			log.warn("Bank filter failed; showing the full bank", ex);
			filterActive = false;
			restoreBank();
		}
		finally
		{
			applyingFilter = false;
		}
	}

	/** Puts every slot back where the client had it and unhides it. */
	private void restoreBank()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.getDynamicChildren() == null)
		{
			return;
		}
		applyingFilter = true;
		try
		{
			for (Widget child : container.getDynamicChildren())
			{
				if (child == null)
				{
					continue;
				}
				int[] xy = originalSlotPositions.get(child.getIndex());
				if (xy != null)
				{
					child.setOriginalX(xy[0]);
					child.setOriginalY(xy[1]);
				}
				child.setHidden(false);
				child.revalidate();
			}
			container.revalidate();
		}
		finally
		{
			applyingFilter = false;
		}
	}

	private void filterSlots(Widget container)
	{
		int shown = 0;
		for (Widget child : container.getDynamicChildren())
		{
			if (child == null || child.getItemId() <= 0)
			{
				continue;
			}
			originalSlotPositions.putIfAbsent(child.getIndex(),
				new int[]{child.getOriginalX(), child.getOriginalY()});
			if (!isUnlockedItem(child.getItemId()))
			{
				child.setHidden(true);
				child.setOriginalX(0);
				child.setOriginalY(0);
				child.revalidate();
				continue;
			}
			child.setHidden(false);
			child.setOriginalX(ITEM_ROW_START + (shown % ITEMS_PER_ROW) * ITEM_X_SPACING);
			child.setOriginalY(ITEM_Y_START + (shown / ITEMS_PER_ROW) * ITEM_Y_SPACING);
			child.revalidate();
			shown++;
		}

		int rows = (shown + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW;
		container.setScrollHeight(Math.max(0, rows * ITEM_Y_SPACING + ITEM_Y_START));
		container.revalidate();
		Widget scrollbar = client.getWidget(InterfaceID.Bankmain.SCROLLBAR);
		if (scrollbar != null)
		{
			client.runScript(ScriptID.UPDATE_SCROLLBAR, scrollbar.getId(), container.getId(),
				container.getScrollY());
		}
	}

	/** True when the item, or the base item behind a variant, has an owned card. */
	private boolean isUnlockedItem(int itemId)
	{
		ItemComposition comp = client.getItemDefinition(itemId);
		if (comp == null || comp.getName() == null || !BronzemanEquipLockService.isEquipable(comp))
		{
			return false;
		}
		Optional<CardDefinition> card = equipLockService.findCardForItemName(comp.getName());
		return card.isPresent() && !stateService.getState().getCollectionState()
			.instancesForCardName(card.get().getName()).isEmpty();
	}

	/** Item ids for every card the player owns, including the extra items a bundled card covers. */
	private List<Integer> unlockedItemIds()
	{
		Set<String> ownedCards = new LinkedHashSet<>();
		for (OwnedCardInstance instance : stateService.getState().getCollectionState().getOwnedInstances())
		{
			if (instance != null && instance.getCardName() != null)
			{
				ownedCards.add(instance.getCardName());
			}
		}

		List<Integer> ids = new ArrayList<>();
		Set<Integer> seen = new LinkedHashSet<>();
		for (String cardName : ownedCards)
		{
			List<String> lookups = new ArrayList<>();
			lookups.add(cardName);
			Optional<CardDefinition> card = cardDatabase.findByNameOrAlias(cardName);
			card.ifPresent(c -> lookups.addAll(c.getAliasNames()));

			for (String name : lookups)
			{
				Integer id = itemIdByName.get(name.trim().toLowerCase(Locale.ROOT));
				if (id != null && seen.add(id))
				{
					ids.add(id);
				}
			}
		}
		return ids;
	}

	/**
	 * One pass over the client's item definitions, keeping only names the catalog cares about.
	 * The lowest id wins so placeholders and noted copies do not shadow the real item.
	 */
	private void buildItemIndex()
	{
		if (itemIndexBuilt)
		{
			return;
		}

		Set<String> wanted = new LinkedHashSet<>();
		for (CardDefinition card : cardDatabase.getCards())
		{
			if (card == null || card.getName() == null)
			{
				continue;
			}
			wanted.add(card.getName().trim().toLowerCase(Locale.ROOT));
			for (String alias : card.getAliasNames())
			{
				wanted.add(alias.trim().toLowerCase(Locale.ROOT));
			}
		}

		int count = client.getItemCount();
		for (int id = 0; id < count; id++)
		{
			ItemComposition comp;
			try
			{
				comp = client.getItemDefinition(id);
			}
			catch (RuntimeException ex)
			{
				continue;
			}
			if (comp == null || comp.getName() == null || comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			String key = comp.getName().trim().toLowerCase(Locale.ROOT);
			if (wanted.contains(key))
			{
				itemIdByName.putIfAbsent(key, id);
			}
		}
		itemIndexBuilt = true;
	}

	/** Publishes the plugin's card icon as a client sprite so a widget can draw it. */
	private void registerIconSprite()
	{
		if (client.getSpriteOverrides().containsKey(ICON_SPRITE_ID))
		{
			return;
		}
		BufferedImage icon = ImageUtil.loadImageResource(BankUnlocksButtonService.class, "/icon.png");
		if (icon != null)
		{
			client.getSpriteOverrides().put(ICON_SPRITE_ID,
				ImageUtil.getImageSpritePixels(ImageUtil.resizeImage(icon, BUTTON_SIZE, BUTTON_SIZE), client));
		}
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.CollectionState;
import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

/**
 * Bronzeman mode (ported from the bronzeman-tcg companion plugin, reading the collection
 * in-process instead of through its cross-plugin snapshot): equipping an item is blocked until
 * the matching TCG card is owned. Items with no card in the catalog are never restricted —
 * they could never be unlocked. Tutorial Island (it supplies required gear) and live LMS
 * matches (temporary loadouts the player doesn't own) bypass enforcement.
 */
@Singleton
public final class BronzemanEquipLockService
{
	private static final Set<String> EQUIP_VERBS = Set.of("wear", "wield", "equip");
	/** Consuming verbs, blocked only while the consumable lock is on. */
	private static final Set<String> CONSUME_VERBS = Set.of("eat", "drink");

	/**
	 * Trailing variant marker: charges ("Amulet of glory(4)"), locked and imbued items
	 * ("Fire cape (l)", "Ring of suffering (ri)"), ornament kits ("Amulet of fury (or)"),
	 * autocast forms ("Accursed sceptre (au)") and poison grades ("Dragon dagger (p++)").
	 * No card name contains brackets, so stripping these is unambiguous.
	 */
	private static final Pattern BRACKET_SUFFIX = Pattern.compile("\\s*\\([^()]*\\)$");
	/** "Dharok's helm 100" -> Barrows degradation states share the undegraded card. */
	private static final Pattern DEGRADATION_SUFFIX = Pattern.compile("\\s+\\d+$");
	/** Upgraded forms that keep the base item's name ("Imbued saradomin cape"). */
	private static final Pattern UPGRADE_PREFIX =
		Pattern.compile("^(imbued|superior|corrupted)\\s+", Pattern.CASE_INSENSITIVE);
	private static final int MAX_NORMALISE_STEPS = 4;

	/** Fade level for locked item sprites (Alch Blocker's widget-opacity technique). */
	private static final int LOCKED_ITEM_OPACITY = 140;
	private static final int[] LOCKED_MARK_CONTAINERS = {
		InterfaceID.Inventory.ITEMS, InterfaceID.Bankmain.ITEMS, InterfaceID.Bankside.ITEMS,
		InterfaceID.Shopmain.ITEMS, InterfaceID.Shopside.ITEMS};
	private static final int MARK_SWEEP_TICKS = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final CardDatabase cardDatabase;
	private final TcgStateService stateService;
	private final ChatMessageManager chatMessageManager;
	private final OsrsTcgConfig config;

	private final Map<Integer, Boolean> lockedItemCache = new HashMap<>();
	private CollectionState lockedItemCacheCollection;
	/** Settings that change what counts as locked; the cache must drop when they move. */
	private boolean lockedItemCacheConsumables;
	private String lockedItemCacheWhitelist = "";
	private boolean markRefreshQueued;
	private int markTickCounter;

	@Inject
	public BronzemanEquipLockService(
		Client client,
		ClientThread clientThread,
		ItemManager itemManager,
		CardDatabase cardDatabase,
		TcgStateService stateService,
		ChatMessageManager chatMessageManager,
		OsrsTcgConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.cardDatabase = cardDatabase;
		this.stateService = stateService;
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (isEnforcementBypassed())
		{
			return;
		}

		MenuAction action = event.getMenuAction();
		if (action != MenuAction.CC_OP && action != MenuAction.CC_OP_LOW_PRIORITY)
		{
			return;
		}

		if (blockLockedGrandExchangeChoice(event))
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (entry == null || !entry.isItemOp() || entry.getItemId() <= 0)
		{
			return;
		}

		String option = Text.removeTags(event.getMenuOption()).trim().toLowerCase(Locale.ROOT);
		boolean equipping = EQUIP_VERBS.contains(option);
		boolean consuming = config.consumableCards() && CONSUME_VERBS.contains(option);
		// Withdrawing is blocked too, so a locked item cannot leave the bank in the first place.
		boolean withdrawing = option.startsWith("withdraw")
			&& WidgetUtil.componentToInterface(entry.getParam1()) == InterfaceID.BANKMAIN;
		if (!equipping && !consuming && !withdrawing)
		{
			return;
		}

		if (!isItemLocked(entry.getItemId()))
		{
			return;
		}

		String itemName = itemManager.getItemComposition(entry.getItemId()).getName();
		Optional<CardDefinition> card = findCardForItemName(itemName);
		if (card.isEmpty())
		{
			return;
		}

		event.consume();
		String verb = withdrawing ? "withdraw" : consuming ? "use" : "equip";
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
			"%s is locked — pull its card from a pack to %s it.", card.get().getName(), verb));
	}

	/**
	 * Grand Exchange search results are drawn in the chatbox, so consuming the selection is the
	 * available hook for stopping a locked item being bought. Best effort: a keyboard-driven
	 * flow can still reach the offer screen.
	 *
	 * @return true when the click was for a locked item and has been consumed
	 */
	private boolean blockLockedGrandExchangeChoice(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (entry == null
			|| WidgetUtil.componentToInterface(entry.getParam1()) != InterfaceID.CHATBOX
			|| client.getWidget(InterfaceID.GE_OFFERS, 0) == null)
		{
			return false;
		}

		String itemName = Text.removeTags(event.getMenuTarget()).trim();
		Optional<CardDefinition> card = findCardForItemName(itemName);
		if (card.isEmpty() || isWhitelisted(itemName) || isCardOwned(card.get()))
		{
			return false;
		}

		event.consume();
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
			"%s is locked — pull its card before buying it.", card.get().getName()));
		return true;
	}

	/**
	 * Resolves an in-game item to its card. Tries the exact name first, then peels one variant
	 * marker at a time, so every untradeable, imbued, ornamented, degraded or bundled variant
	 * lands on the card that unlocks it. Shared with the bank unlocks panel.
	 */
	public Optional<CardDefinition> findCardForItemName(String itemName)
	{
		if (itemName == null || itemName.trim().isEmpty())
		{
			return Optional.empty();
		}

		String candidate = itemName.trim();
		for (int step = 0; step <= MAX_NORMALISE_STEPS; step++)
		{
			Optional<CardDefinition> hit = cardDatabase.findByNameOrAlias(candidate);
			if (hit.isPresent())
			{
				return hit;
			}

			String next = stripOneVariantMarker(candidate);
			if (next.equals(candidate))
			{
				return Optional.empty();
			}
			candidate = next;
		}
		return Optional.empty();
	}

	/** @return the name with one trailing/leading variant marker removed, or unchanged if none. */
	private static String stripOneVariantMarker(String name)
	{
		String stripped = BRACKET_SUFFIX.matcher(name).replaceFirst("").trim();
		if (!stripped.equals(name))
		{
			return stripped;
		}
		stripped = DEGRADATION_SUFFIX.matcher(name).replaceFirst("").trim();
		if (!stripped.equals(name))
		{
			return stripped;
		}
		return UPGRADE_PREFIX.matcher(name).replaceFirst("").trim();
	}

	/**
	 * User-managed escape hatch: a comma-separated list of item names that stay equipable
	 * regardless of the collection. Matched on the raw in-game name, case-insensitively.
	 */
	private boolean isWhitelisted(String itemName)
	{
		String list = config.itemWhitelist();
		if (list == null || list.trim().isEmpty() || itemName == null)
		{
			return false;
		}
		String needle = itemName.trim().toLowerCase(Locale.ROOT);
		for (String entry : list.split(","))
		{
			String candidate = entry.trim().toLowerCase(Locale.ROOT);
			if (!candidate.isEmpty() && candidate.equals(needle))
			{
				return true;
			}
		}
		return false;
	}

	/** Owning any instance of the card (normal or foil) unlocks the item. */
	private boolean isCardOwned(CardDefinition card)
	{
		return !stateService.getState().getCollectionState()
			.instancesForCardName(card.getName()).isEmpty();
	}

	/**
	 * Walks every item definition the client knows and reports equipable ones that resolve to no
	 * card — i.e. items currently wearable without unlocking anything. Name rules are unavoidable
	 * (card data is name-keyed), so this makes the gaps visible instead of silent.
	 *
	 * @return item names with no card, in id order
	 */
	public List<String> findUnmatchedEquipableItems()
	{
		List<String> escapes = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		int count = client.getItemCount();
		for (int id = 0; id < count; id++)
		{
			ItemComposition comp;
			try
			{
				comp = client.getItemDefinition(id);
			}
			catch (RuntimeException ex)
			{
				continue;
			}
			if (comp == null || comp.getName() == null || comp.getPlaceholderTemplateId() != -1
				|| comp.getNote() != -1)
			{
				continue;
			}
			String name = comp.getName().trim();
			if (name.isEmpty() || "null".equalsIgnoreCase(name) || !seen.add(name.toLowerCase(Locale.ROOT)))
			{
				continue;
			}
			// Only equipable items matter; the client exposes this through the Wear/Wield op.
			boolean equipable = false;
			for (String action : comp.getInventoryActions())
			{
				if (action != null && EQUIP_VERBS.contains(action.trim().toLowerCase(Locale.ROOT)))
				{
					equipable = true;
					break;
				}
			}
			if (equipable && findCardForItemName(name).isEmpty())
			{
				escapes.add(name);
			}
		}
		return escapes;
	}

	private boolean isEnforcementBypassed()
	{
		int tutorialProgress = client.getVarpValue(VarPlayerID.TUTORIAL);
		if (tutorialProgress > 0 && tutorialProgress < 1000)
		{
			return true;
		}
		return client.getVarbitValue(VarbitID.BR_INGAME) == 1;
	}

	// ------------------------------------------------------------------ locked item fade

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Redraw scripts reset widget opacity, so re-fade as soon as they finish.
		if (event.getScriptId() == ScriptID.INVENTORY_DRAWITEM
			|| event.getScriptId() == ScriptID.BANKMAIN_BUILD)
		{
			scheduleLockedItemMarks();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Shops build their stock on open; fade it immediately rather than waiting for
		// the periodic sweep.
		if (event.getGroupId() == InterfaceID.SHOPMAIN || event.getGroupId() == InterfaceID.SHOPSIDE)
		{
			scheduleLockedItemMarks();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Every ~3s: catches unlocks (new pulls) and bypass changes that happen
		// without an inventory redraw.
		if (++markTickCounter % MARK_SWEEP_TICKS == 0)
		{
			scheduleLockedItemMarks();
		}
	}

	/** Restore every fade on plugin shutdown. */
	public void shutdown()
	{
		clientThread.invoke(() -> setLockedItemMarks(false));
	}

	/** Coalesces the many per-slot INVENTORY_DRAWITEM firings into one pass per tick. */
	private void scheduleLockedItemMarks()
	{
		if (markRefreshQueued)
		{
			return;
		}
		markRefreshQueued = true;
		clientThread.invokeAtTickEnd(() ->
		{
			markRefreshQueued = false;
			setLockedItemMarks(!isEnforcementBypassed());
		});
	}

	/** Fade locked items in the inventory, bank and shops via widget opacity. Client thread only. */
	private void setLockedItemMarks(boolean marking)
	{
		for (int componentId : LOCKED_MARK_CONTAINERS)
		{
			Widget container = client.getWidget(componentId);
			Widget[] children = container == null ? null : container.getChildren();
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child == null || child.getItemId() <= 0)
				{
					continue;
				}
				if (marking && isItemLocked(child.getItemId()))
				{
					child.setOpacity(LOCKED_ITEM_OPACITY);
				}
				else if (child.getOpacity() == LOCKED_ITEM_OPACITY)
				{
					child.setOpacity(0);
				}
			}
		}
	}

	/** Same rule the click block uses; cached per item id until the collection changes. */
	/** True when the item needs a card the player does not own. Cheap enough for a render loop. */
	public boolean isItemLocked(int itemId)
	{
		CollectionState collection = stateService.getState().getCollectionState();
		boolean consumables = config.consumableCards();
		String whitelist = config.itemWhitelist() == null ? "" : config.itemWhitelist();
		// Toggling the consumable lock or editing the whitelist changes the answer without the
		// collection moving, so both take part in invalidation.
		if (collection != lockedItemCacheCollection
			|| consumables != lockedItemCacheConsumables
			|| !whitelist.equals(lockedItemCacheWhitelist))
		{
			lockedItemCache.clear();
			lockedItemCacheCollection = collection;
			lockedItemCacheConsumables = consumables;
			lockedItemCacheWhitelist = whitelist;
		}
		Boolean cached = lockedItemCache.get(itemId);
		if (cached != null)
		{
			return cached;
		}
		ItemComposition comp = itemManager.getItemComposition(itemId);
		String name = comp.getName();
		// Something you cannot wear is never "locked" — unstrung bows, unfinished potions and other
		// crafting intermediates share a name with equipable gear but are not gear themselves.
		// Food and potions only join in while the consumable lock is switched on.
		Optional<CardDefinition> card = Optional.empty();
		if (isEquipable(comp))
		{
			card = findCardForItemName(name);
		}
		else if (consumables && isConsumable(comp))
		{
			card = findCardForItemName(name).filter(CardDefinition::isConsumableCard);
		}
		boolean locked = card.isPresent() && !isWhitelisted(name) && !isCardOwned(card.get());
		lockedItemCache.put(itemId, locked);
		return locked;
	}

	/** True when the client offers an Eat/Drink option on the item itself. */
	public static boolean isConsumable(ItemComposition comp)
	{
		return hasAction(comp, CONSUME_VERBS);
	}

	/** True when the client offers a Wear/Wield/Equip option on the item itself. */
	public static boolean isEquipable(ItemComposition comp)
	{
		return hasAction(comp, EQUIP_VERBS);
	}

	private static boolean hasAction(ItemComposition comp, Set<String> verbs)
	{
		if (comp == null || comp.getInventoryActions() == null)
		{
			return false;
		}
		for (String action : comp.getInventoryActions())
		{
			if (action != null && verbs.contains(action.trim().toLowerCase(Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}
}

