import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

/**
 * Party card gifting: sender offers (no removal yet); recipient validates multiplier parity, matching Overview debug
 * mode, adds the card, then sends {@link BpvpCardGiftResponsePartyMessage}; sender removes one copy only when accepted.
 */
@Slf4j
@Singleton
public class CardPartyTransferService
{
	private static final long PENDING_TTL_MS = 90_000L;

	private static final int GIFT_REJECT_NONE = 0;
	private static final int GIFT_REJECT_TUNING_MISMATCH = 1;
	private static final int GIFT_REJECT_DEBUG_MISMATCH = 2;
	private static final int GIFT_REJECT_SENDER_TOO_OLD = 3;
	private static final int GIFT_REJECT_BAD_PAYLOAD = 4;

	private final PartyService partyService;
	private final TcgStateService stateService;
	private final ClientThread clientThread;
	private final ChatMessageManager chatMessageManager;
	private final PackRevealSoundService packRevealSoundService;
	private final CardDatabase cardDatabase;
	private final Provider<CollectionAlbumManager> collectionAlbumManagerProvider;

	private final java.util.Map<String, PendingOffer> pendingOffers = new java.util.concurrent.ConcurrentHashMap<>();
	private final java.util.Set<String> pendingInstanceIds = java.util.Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<>());
	/**
	 * Upper bound on remembered gift-transfer ids for replay protection. Set well above
	 * any realistic gift-to-redelivery gap; the exact value is not tuned.
	 */
	private static final int MAX_REMEMBERED_GIFT_IDS = 600;
	private final RecentIdSet processedGiftTransferIds = new RecentIdSet(MAX_REMEMBERED_GIFT_IDS);
	private int tickCounter;

	private static final class PendingOffer
	{
		private final String cardName;
		private final boolean foil;
		private final String cardInstanceId;
		private final long createdAtMs;

		private PendingOffer(String cardName, boolean foil, String cardInstanceId, long createdAtMs)
		{
			this.cardName = cardName;
			this.foil = foil;
			this.cardInstanceId = cardInstanceId;
			this.createdAtMs = createdAtMs;
		}
	}

	@Inject
	public CardPartyTransferService(
		PartyService partyService,
		TcgStateService stateService,
		ClientThread clientThread,
		ChatMessageManager chatMessageManager,
		PackRevealSoundService packRevealSoundService,
		CardDatabase cardDatabase,
		Provider<CollectionAlbumManager> collectionAlbumManagerProvider)
	{
		this.partyService = partyService;
		this.stateService = stateService;
		this.clientThread = clientThread;
		this.chatMessageManager = chatMessageManager;
		this.packRevealSoundService = packRevealSoundService;
		this.cardDatabase = cardDatabase;
		this.collectionAlbumManagerProvider = collectionAlbumManagerProvider;
	}

	public boolean isInstancePendingGift(String cardInstanceId)
	{
		if (cardInstanceId == null || cardInstanceId.isEmpty())
		{
			return false;
		}
		return pendingInstanceIds.contains(cardInstanceId);
	}

	/**
	 * @return null on success, or user-facing error
	 */
	public String sendGift(long recipientMemberId, String cardName, boolean foil)
	{
		String partyErr = validateGiftPartyRecipient(recipientMemberId);
		if (partyErr != null)
		{
			return partyErr;
		}
		if (cardName == null || cardName.trim().isEmpty())
		{
			return "Select a card to send.";
		}
		String name = cardName.trim();
		OwnedCardInstance inst;
		synchronized (stateService)
		{
			Optional<OwnedCardInstance> pick = firstUnlockedInstanceFifo(name, foil);
			if (pick.isEmpty())
			{
				if (ownsLockedVariantOnly(name, foil))
				{
					return AlbumInstanceTooltip.LOCKED_ACTION_HINT;
				}
				return "You do not own that card variant.";
			}
			inst = pick.get();
		}
		return beginGiftTransfer(recipientMemberId, inst);
	}

	/**
	 * Sends the specific collection row (any copy the player owns).
	 *
	 * @return null on success, or user-facing error
	 */
	public String sendGift(long recipientMemberId, String cardInstanceId)
	{
		String partyErr = validateGiftPartyRecipient(recipientMemberId);
		if (partyErr != null)
		{
			return partyErr;
		}
		if (cardInstanceId == null || cardInstanceId.trim().isEmpty())
		{
			return "Select a card copy to send.";
		}
		OwnedCardInstance inst;
		synchronized (stateService)
		{
			inst = stateService.getState().getCollectionState()
				.findInstanceById(cardInstanceId.trim())
				.orElse(null);
		}
		if (inst == null)
		{
			return "You do not own that card copy.";
		}
		return beginGiftTransfer(recipientMemberId, inst);
	}

	private String validateGiftPartyRecipient(long recipientMemberId)
	{
		if (!partyService.isInParty())
		{
			return "Join a RuneLite party first.";
		}
		PartyMember local = partyService.getLocalMember();
		if (local == null)
		{
			return "Party session not ready.";
		}
		if (recipientMemberId == local.getMemberId())
		{
			return "Choose a different party member.";
		}
		PartyMember recipient = partyService.getMemberById(recipientMemberId);
		if (recipient == null)
		{
			return "That player is not in your party.";
		}
		return null;
	}

	private Optional<OwnedCardInstance> firstUnlockedInstanceFifo(String cardName, boolean foil)
	{
		List<OwnedCardInstance> matches = new ArrayList<>();
		for (OwnedCardInstance i : stateService.getState().getCollectionState().getOwnedInstances())
		{
			if (cardName.equalsIgnoreCase(i.getCardName()) && foil == i.isFoil() && !i.isLocked())
			{
				matches.add(i);
			}
		}
		if (matches.isEmpty())
		{
			return Optional.empty();
		}
		matches.sort(Comparator.comparingLong(OwnedCardInstance::getPulledAtEpochMs));
		return Optional.of(matches.get(0));
	}

	private boolean ownsLockedVariantOnly(String cardName, boolean foil)
	{
		boolean hasVariant = false;
		for (OwnedCardInstance i : stateService.getState().getCollectionState().getOwnedInstances())
		{
			if (cardName.equalsIgnoreCase(i.getCardName()) && foil == i.isFoil())
			{
				hasVariant = true;
				if (!i.isLocked())
				{
					return false;
				}
			}
		}
		return hasVariant;
	}

	private String beginGiftTransfer(long recipientMemberId, OwnedCardInstance inst)
	{
		if (inst == null)
		{
			return "Select a card to send.";
		}
		String name = inst.getCardName() == null ? "" : inst.getCardName().trim();
		if (name.isEmpty())
		{
			return "Select a card to send.";
		}
		if (inst.isLocked())
		{
			return AlbumInstanceTooltip.LOCKED_ACTION_HINT;
		}
		boolean foil = inst.isFoil();
		String instanceId = inst.getInstanceId();
		RewardTuningState tuning;
		boolean senderDebugLogging;
		synchronized (stateService)
		{
			Optional<OwnedCardInstance> cur = stateService.getState().getCollectionState()
				.findInstanceById(instanceId);
			if (cur.isEmpty())
			{
				return "You do not own that card copy.";
			}
			inst = cur.get();
			if (inst.isLocked())
			{
				return AlbumInstanceTooltip.LOCKED_ACTION_HINT;
			}
			tuning = stateService.getState().getRewardTuning();
			senderDebugLogging = stateService.isDebugLogging();
		}

		if (!pendingInstanceIds.add(instanceId))
		{
			return "That card copy is already being sent.";
		}

		String transferId = java.util.UUID.randomUUID().toString();
		pendingOffers.put(transferId, new PendingOffer(name, foil, instanceId, System.currentTimeMillis()));

		try
		{
			BpvpCardGiftPartyMessage m = new BpvpCardGiftPartyMessage();
			m.setRecipientMemberId(recipientMemberId);
			m.setCardName(name);
			m.setFoil(foil);
			m.setCardInstanceId(inst.getInstanceId());
			m.setPulledByUsername(inst.getPulledByUsername());
			m.setPulledAtEpochMs(inst.getPulledAtEpochMs());
			m.setFoilChancePercent(tuning.getFoilChancePercent());
			m.setKillCreditMultiplier(tuning.getKillCreditMultiplier());
			m.setLevelUpCreditMultiplier(tuning.getLevelUpCreditMultiplier());
			m.setXpCreditMultiplier(tuning.getXpCreditMultiplier());
			m.setTransferId(transferId);
			m.setSenderDebugLogging(senderDebugLogging);
			partyService.send(m);
		}
		catch (Exception ex)
		{
			pendingOffers.remove(transferId);
			pendingInstanceIds.remove(instanceId);
			log.debug("Failed to send party card gift", ex);
			return "Could not send (party connection).";
		}
		return null;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (++tickCounter % 20 != 0)
		{
			return;
		}
		long now = System.currentTimeMillis();
		for (String tid : new java.util.ArrayList<>(pendingOffers.keySet()))
		{
			PendingOffer p = pendingOffers.get(tid);
			if (p != null && now - p.createdAtMs > PENDING_TTL_MS && pendingOffers.remove(tid, p))
			{
				pendingInstanceIds.remove(p.cardInstanceId);
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Card send timed out (no response from recipient).");
			}
		}
	}

	@Subscribe
	public void onBpvpCardGiftPartyMessage(BpvpCardGiftPartyMessage msg)
	{
		if (msg == null || msg.getTransferId() == null || msg.getTransferId().isEmpty())
		{
			return;
		}
		PartyMember local = partyService.getLocalMember();
		if (local == null || msg.getRecipientMemberId() != local.getMemberId())
		{
			return;
		}

		clientThread.invokeLater(() -> handleCardGiftPartyMessageOnClientThread(msg));
	}

	private void handleCardGiftPartyMessageOnClientThread(BpvpCardGiftPartyMessage msg)
	{
		if (processedGiftTransferIds.contains(msg.getTransferId()))
		{
			return;
		}

		RewardTuningState senderTuning = tuningFromGift(msg);
		RewardTuningState mine = stateService.getState().getRewardTuning();
		boolean tuningOk = mine.matchesPartnerTuning(senderTuning);
		long originalSender = msg.getMemberId();
		String card = msg.getCardName() == null ? "" : msg.getCardName().trim();
		boolean foil = msg.isFoil();
		String senderInstanceId = msg.getCardInstanceId() == null ? "" : msg.getCardInstanceId().trim();

		if (senderInstanceId.isEmpty())
		{
			sendResponse(msg.getTransferId(), originalSender, false, GIFT_REJECT_BAD_PAYLOAD);
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Incoming card ignored: incompatible gift message (missing instance id).");
			return;
		}

		Boolean senderDebug = msg.getSenderDebugLogging();
		if (senderDebug == null)
		{
			sendResponse(msg.getTransferId(), originalSender, false, GIFT_REJECT_SENDER_TOO_OLD);
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Incoming card ignored: sender's client did not report debug mode (update OSRS TCG on both sides).");
			return;
		}
		if (senderDebug.booleanValue() != stateService.isDebugLogging())
		{
			sendResponse(msg.getTransferId(), originalSender, false, GIFT_REJECT_DEBUG_MISMATCH);
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Incoming card ignored: Overview debug mode must match the sender's.");
			return;
		}

		if (!tuningOk)
		{
			sendResponse(msg.getTransferId(), originalSender, false, GIFT_REJECT_TUNING_MISMATCH);
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
				"Incoming card ignored: your foil / credit multipliers do not match the sender's.");
			return;
		}

		String by = msg.getPulledByUsername() == null ? "" : msg.getPulledByUsername().trim();
		long at = Math.max(0L, msg.getPulledAtEpochMs());
		stateService.addOwnedCardInstance(OwnedCardInstance.createNew(card, foil, by, at));
		processedGiftTransferIds.add(msg.getTransferId());
		sendResponse(msg.getTransferId(), originalSender, true, GIFT_REJECT_NONE);

		packRevealSoundService.playTransferSuccess();

		PartyMember from = partyService.getMemberById(originalSender);
		String who = from != null && from.getDisplayName() != null && !from.getDisplayName().trim().isEmpty()
			? from.getDisplayName().trim()
			: "Party member";
		Color rarity = cardDatabase.chatRarityColorForCardName(card);
		String formatted = TcgPluginGameMessages.formatPrefixedSomeoneSentYou(who, card, foil, rarity);
		String plain = TcgPluginGameMessages.plainPrefixedSomeoneSentYou(who, card, foil);
		TcgPluginGameMessages.queueFormattedGameMessage(chatMessageManager, formatted, plain);
		refreshAlbumIfOpen();
	}

	private void refreshAlbumIfOpen()
	{
		CollectionAlbumManager mgr = collectionAlbumManagerProvider.get();
		if (mgr != null)
		{
			mgr.refreshIfVisible();
		}
	}

	@Subscribe
	public void onBpvpCardGiftResponsePartyMessage(BpvpCardGiftResponsePartyMessage msg)
	{
		if (msg == null || msg.getTransferId() == null || msg.getTransferId().isEmpty())
		{
			return;
		}
		PartyMember local = partyService.getLocalMember();
		if (local == null || msg.getOriginalSenderMemberId() != local.getMemberId())
		{
			return;
		}
		clientThread.invokeLater(() -> handleCardGiftResponseOnClientThread(msg));
	}

	private void handleCardGiftResponseOnClientThread(BpvpCardGiftResponsePartyMessage msg)
	{
		PendingOffer pending = pendingOffers.remove(msg.getTransferId());
		if (pending == null)
		{
			return;
		}
		pendingInstanceIds.remove(pending.cardInstanceId);

		PartyMember responder = partyService.getMemberById(msg.getMemberId());
		String target = responder != null && responder.getDisplayName() != null && !responder.getDisplayName().trim().isEmpty()
			? responder.getDisplayName().trim()
			: "Party member";

		if (msg.isAccepted())
		{
			boolean removed = stateService.removeCardInstance(pending.cardInstanceId);
			if (!removed)
			{
				TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
					"Recipient accepted the card but you no longer had that copy; check your collection.");
			}
			else
			{
				packRevealSoundService.playTransferSuccess();
				Color rarity = cardDatabase.chatRarityColorForCardName(pending.cardName);
				String formatted = TcgPluginGameMessages.formatPrefixedYouSentCard(
					pending.cardName, pending.foil, target, rarity);
				String plain = TcgPluginGameMessages.plainPrefixedYouSentCard(
					pending.cardName, pending.foil, target);
				TcgPluginGameMessages.queueFormattedGameMessage(chatMessageManager, formatted, plain);
			}
		}
		else
		{
			int code = msg.getRejectCode();
			String detail;
			if (code == GIFT_REJECT_TUNING_MISMATCH)
			{
				detail = String.format(Locale.US,
					"%s could not accept the card: foil / credit multipliers do not match.", target);
			}
			else if (code == GIFT_REJECT_DEBUG_MISMATCH)
			{
				detail = String.format(Locale.US,
					"%s could not accept the card: Overview debug mode must match on both clients.", target);
			}
			else if (code == GIFT_REJECT_SENDER_TOO_OLD)
			{
				detail = String.format(Locale.US,
					"%s could not accept the card: update OSRS TCG to the same version on both clients.", target);
			}
			else if (code == GIFT_REJECT_BAD_PAYLOAD)
			{
				detail = String.format(Locale.US,
					"%s could not accept the card (invalid transfer payload).", target);
			}
			else
			{
				detail = String.format(Locale.US, "%s could not accept the card. You still have it.", target);
			}
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, detail);
		}
		refreshAlbumIfOpen();
	}

	private void sendResponse(String transferId, long originalSenderMemberId, boolean accepted, int rejectCode)
	{
		try
		{
			BpvpCardGiftResponsePartyMessage r = new BpvpCardGiftResponsePartyMessage();
			r.setTransferId(transferId);
			r.setOriginalSenderMemberId(originalSenderMemberId);
			r.setAccepted(accepted);
			r.setRejectCode(accepted ? GIFT_REJECT_NONE : rejectCode);
			partyService.send(r);
		}
		catch (Exception ex)
		{
			log.debug("Failed to send card gift response", ex);
		}
	}

	private static RewardTuningState tuningFromGift(BpvpCardGiftPartyMessage msg)
	{
		return RewardTuningState.mergeSerialized(
			msg.getFoilChancePercent(),
			msg.getKillCreditMultiplier(),
			msg.getLevelUpCreditMultiplier(),
			msg.getXpCreditMultiplier());
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.CardCollectionKey;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Detects when a primary-category "set" (all roll-pool cards sharing that album category) becomes fully collected.
 * Logic matches overview / album name collection (positive total quantity per card name, any foil mix).
 */
public final class CollectionSetCompletionUtil
{
	private CollectionSetCompletionUtil()
	{
	}

	/** Distinct card names with combined foil + non-foil quantity ≥ 1 (same rules as the sidebar overview). */
	public static Set<String> collectedNamesFromOwned(Map<CardCollectionKey, Integer> owned)
	{
		if (owned == null || owned.isEmpty())
		{
			return Collections.emptySet();
		}
		Map<String, Integer> ownedQtyByName = new HashMap<>();
		for (Map.Entry<CardCollectionKey, Integer> entry : owned.entrySet())
		{
			CardCollectionKey key = entry.getKey();
			if (key == null || key.getCardName() == null)
			{
				continue;
			}
			int qty = entry.getValue() == null ? 0 : entry.getValue();
			ownedQtyByName.merge(key.getCardName(), qty, Integer::sum);
		}
		Set<String> collectedNames = new HashSet<>();
		for (Map.Entry<String, Integer> entry : ownedQtyByName.entrySet())
		{
			if (entry.getValue() != null && entry.getValue() > 0)
			{
				collectedNames.add(entry.getKey());
			}
		}
		return collectedNames;
	}

	/**
	 * Primary category display labels for which every card in {@code rollPool} with that category is collected.
	 */
	public static Set<String> completedPrimaryCategoryNames(Map<CardCollectionKey, Integer> owned,
		List<CardDefinition> rollPool)
	{
		if (rollPool == null || rollPool.isEmpty())
		{
			return Collections.emptySet();
		}
		Set<String> collected = collectedNamesFromOwned(owned);
		Map<String, List<CardDefinition>> byCategory = new HashMap<>();
		for (CardDefinition c : rollPool)
		{
			if (c == null || c.getName() == null || c.getName().trim().isEmpty())
			{
				continue;
			}
			String cat = c.getPrimaryCategory();
			byCategory.computeIfAbsent(cat, k -> new ArrayList<>()).add(c);
		}
		Set<String> done = new HashSet<>();
		outer:
		for (Map.Entry<String, List<CardDefinition>> e : byCategory.entrySet())
		{
			for (CardDefinition c : e.getValue())
			{
				if (!collected.contains(c.getName()))
				{
					continue outer;
				}
			}
			done.add(e.getKey());
		}
		return done;
	}

	public static List<String> newlyCompletedPrimaryCategories(Map<CardCollectionKey, Integer> ownedBefore,
		Map<CardCollectionKey, Integer> ownedAfter, List<CardDefinition> rollPool)
	{
		Set<String> after = completedPrimaryCategoryNames(ownedAfter, rollPool);
		Set<String> before = completedPrimaryCategoryNames(ownedBefore, rollPool);
		after.removeAll(before);
		return new ArrayList<>(after);
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.model.SkillCreditBaseline;
import com.bronzemanpvptcg.util.NumberFormatting;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@Slf4j
public class CreditAwardService
{
	/** Ignore bogus fake XP drop payloads. */
	private static final int FAKE_XP_DROP_SANITY_CAP = 20_000_000;
	/** Suppress credit awards while stats settle after login or a world hop. */
	private static final int CREDIT_AWARD_COOLDOWN_TICKS = 3;
	private static final Set<Skill> COMBAT_SKILLS = EnumSet.of(
		Skill.ATTACK,
		Skill.DEFENCE,
		Skill.STRENGTH,
		Skill.HITPOINTS,
		Skill.MAGIC,
		Skill.RANGED
	);

	private final Client client;
	private final TcgStateService stateService;
	/** Last known skill level including virtual levels past 99 (1–126). */
	private final Map<Skill, Integer> lastKnownLevels = new EnumMap<>(Skill.class);
	private final int[] previousSkillXp = new int[Skill.values().length];
	private boolean skillLevelsInitialized;
	private boolean skillXpInitialized;
	private boolean creditAwardCooldownActive;
	private int creditAwardCooldownUntilTick;
	private boolean pendingStatsSettleAfterLoginOrHop;
	/** When true, restore uncredited XP from the persisted snapshot after settle (login / logout). */
	private boolean restoreUncreditedXpFromPersistedBaseline;
	private GameState lastObservedGameState;

	/** XP from skill drops not yet converted into credit chunks. */
	private long uncreditedXp;

	@Inject
	public CreditAwardService(Client client, TcgStateService stateService)
	{
		this.client = client;
		this.stateService = stateService;
	}

	/**
	 * Call when the RuneScape profile (or persisted plugin state) changes so we do not compare XP across characters.
	 * Keeps the persisted skill snapshot for post-settle retroactive awards; only resets live tracking.
	 */
	public void resetExperienceCreditBaseline()
	{
		skillXpInitialized = false;
		skillLevelsInitialized = false;
		lastKnownLevels.clear();
		Arrays.fill(previousSkillXp, 0);

		SkillCreditBaseline saved = stateService.getState().getSkillCreditBaseline();
		if (saved != null && saved.isPresent())
		{
			uncreditedXp = saved.getUncreditedXp();
		}
		else
		{
			clearUncreditedXpPool("profile change");
		}
		// Do not snapshot live client stats here — wait for the settle cooldown so retro awards can run first.
	}

	/**
	 * After a disk save restore: keep restored collection/economy, and set this profile's skill credit
	 * baselines to the character's current stats (no retro awards from the save's old XP snapshot).
	 */
	public void rebaseExperienceCreditBaselineToCurrentStats()
	{
		skillXpInitialized = false;
		skillLevelsInitialized = false;
		lastKnownLevels.clear();
		Arrays.fill(previousSkillXp, 0);
		clearUncreditedXpPool("disk save restore");
		stateService.replaceSkillCreditBaseline(SkillCreditBaseline.absent());

		snapshotSkillBaselinesIfLoggedIn();
		persistSkillBaselineToState(false);
		debugAward("Set skill credit baselines to current stats after disk save restore");
	}

	/** Flush live skill XP / uncredited pool into profile state before a checkpoint (logout, unload, etc.). */
	public void flushSkillBaselineForPersist()
	{
		snapshotSkillBaselinesIfLoggedIn();
		persistSkillBaselineToState(false);
	}

	/** PvP-only economy: PvM kills no longer award credits (see {@link PvpKillCreditTracker}). */
	public void awardNpcKillCredits(String npcName, int combatLevel)
	{
	}

	/** PvP-only economy: raid/boss completions no longer award credits (see {@link PvpKillCreditTracker}). */
	public void awardFlatCredits(String reason, long credits)
	{
	}

	/**
	 * PvP kills are the only external credit source: one kill pays for exactly one standard booster pack.
	 *
	 * @return true if the credits were awarded
	 */
	public boolean awardPvpKillCredits(String victimName, long packPrice)
	{
		if (packPrice <= 0L || isCreditAwardOnCooldown())
		{
			return false;
		}

		addCredits(packPrice);
		debugAward(String.format("PvP kill on %s -> +%s credits (total %s)",
			safeName(victimName), NumberFormatting.format(packPrice), NumberFormatting.format(stateService.getCredits())));
		return true;
	}

	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		if (skill == null)
		{
			return;
		}

		int currentXp = event.getXp();
		trackXpGainFromStatChanged(skill, currentXp);

		if (isCreditAwardOnCooldown())
		{
			return;
		}

		if (isOverallSkill(skill))
		{
			return;
		}

		int current = levelForXp(currentXp);
		if (!skillLevelsInitialized || !lastKnownLevels.containsKey(skill))
		{
			lastKnownLevels.put(skill, current);
			return;
		}

		int previous = lastKnownLevels.get(skill);

		// Skill levels cannot decrease; ignore transient drops (e.g. disconnect/reconnect).
		if (current <= previous)
		{
			return;
		}

		awardLevelUps(skill, previous, current);
		lastKnownLevels.put(skill, current);
	}

	public void onFakeXpDrop(FakeXpDrop event)
	{
		if (event == null || event.getSkill() == null || isCreditAwardOnCooldown())
		{
			return;
		}

		Skill skill = event.getSkill();
		if (isCombatSkill(skill))
		{
			int xp = event.getXp();
			if (xp > 0 && xp < FAKE_XP_DROP_SANITY_CAP)
			{
				debugAward(String.format(
					"Ignored fake XP drop for combat skill %s (+%s XP)",
					skill.getName(), NumberFormatting.format(xp)));
			}
			return;
		}

		if (!isGenuineMaxedSkillFakeXpDrop(skill))
		{
			debugAward(String.format(
				"Ignored fake XP drop for %s (skill below %s XP)",
				skill.getName(), NumberFormatting.format(Experience.MAX_SKILL_XP)));
			return;
		}

		int xp = event.getXp();
		if (xp <= 0 || xp >= FAKE_XP_DROP_SANITY_CAP)
		{
			return;
		}

		applyXpGain(xp, skill.getName() + " drop");
	}

	/** Call when the plugin is enabled mid-session so stats are not credited against empty baselines. */
	public void onPluginStarted()
	{
		if (client == null)
		{
			return;
		}

		lastObservedGameState = client.getGameState();
		GameState current = lastObservedGameState;
		if (current == GameState.LOGIN_SCREEN)
		{
			pendingStatsSettleAfterLoginOrHop = true;
			restoreUncreditedXpFromPersistedBaseline = true;
			suppressCreditAwardsUntilStatsSettle(true);
		}
		else if (current == GameState.HOPPING)
		{
			pendingStatsSettleAfterLoginOrHop = true;
			restoreUncreditedXpFromPersistedBaseline = false;
			suppressCreditAwardsUntilStatsSettle(false);
		}
		else if (current == GameState.LOGGED_IN)
		{
			pendingStatsSettleAfterLoginOrHop = true;
			restoreUncreditedXpFromPersistedBaseline = false;
			suppressCreditAwardsUntilStatsSettle(false);
		}
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		GameState next = event.getGameState();
		lastObservedGameState = next;

		if (next == GameState.LOGIN_SCREEN)
		{
			persistSkillBaselineToState(true);
			pendingStatsSettleAfterLoginOrHop = true;
			restoreUncreditedXpFromPersistedBaseline = true;
			suppressCreditAwardsUntilStatsSettle(true);
			return;
		}

		if (next == GameState.HOPPING)
		{
			persistSkillBaselineToState(true);
			pendingStatsSettleAfterLoginOrHop = true;
			restoreUncreditedXpFromPersistedBaseline = false;
			suppressCreditAwardsUntilStatsSettle(false);
			return;
		}

		if (next != GameState.LOGGED_IN)
		{
			return;
		}

		if (pendingStatsSettleAfterLoginOrHop)
		{
			// Tracking was already reset at login screen / hop; realign to post-login ticks only.
			beginCreditAwardCooldown();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (creditAwardCooldownActive)
		{
			if (isCreditAwardOnCooldown())
			{
				return;
			}

			creditAwardCooldownActive = false;
			pendingStatsSettleAfterLoginOrHop = false;
			applyRetroactiveCreditsFromPersistedBaseline();
			if (!skillXpInitialized || !skillLevelsInitialized)
			{
				snapshotSkillBaselinesIfLoggedIn();
			}
			persistSkillBaselineToState(true);
			debugAward("Credit award cooldown ended; resuming credit gains");
			return;
		}

		if (!skillXpInitialized || !skillLevelsInitialized)
		{
			snapshotSkillBaselinesIfLoggedIn();
			persistSkillBaselineToState(false);
		}
	}

	private void applyRetroactiveCreditsFromPersistedBaseline()
	{
		SkillCreditBaseline saved = stateService.getState().getSkillCreditBaseline();
		if (saved == null || !saved.isPresent())
		{
			restoreUncreditedXpFromPersistedBaseline = false;
			return;
		}

		if (restoreUncreditedXpFromPersistedBaseline)
		{
			uncreditedXp = saved.getUncreditedXp();
			restoreUncreditedXpFromPersistedBaseline = false;
		}

		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int[] liveXp = client.getSkillExperiences();
		if (liveXp == null)
		{
			return;
		}

		long pendingNonCombatXp = 0L;
		List<RetroLevelUp> pendingLevelUps = new ArrayList<>();

		for (Skill skill : Skill.values())
		{
			if (isOverallSkill(skill))
			{
				continue;
			}

			OptionalInt savedXpOpt = saved.xpFor(skill);
			if (savedXpOpt.isEmpty())
			{
				continue;
			}

			int skillIndex = skill.ordinal();
			if (skillIndex < 0 || skillIndex >= liveXp.length)
			{
				continue;
			}

			int previousXp = savedXpOpt.getAsInt();
			int currentXp = Math.max(0, liveXp[skillIndex]);
			if (currentXp < previousXp)
			{
				continue;
			}

			long gained = (long) currentXp - previousXp;
			if (gained > 0L)
			{
				if (isCombatSkill(skill))
				{
					debugAward(String.format(
						"Retro: ignored +%s combat skill XP (%s)",
						NumberFormatting.format(gained), skill.getName()));
				}
				else
				{
					pendingNonCombatXp += gained;
					debugAward(String.format(
						"Retro: +%s XP (%s) since last snapshot",
						NumberFormatting.format(gained), skill.getName()));
				}
			}

			int previousLevel = levelForXp(previousXp);
			int currentLevel = levelForXp(currentXp);
			if (currentLevel > previousLevel)
			{
				pendingLevelUps.add(new RetroLevelUp(skill, previousLevel, currentLevel));
			}
		}

		// Persist live skill XP before awarding so a crash cannot double-pay the same gap next login.
		snapshotSkillBaselinesIfLoggedIn();
		persistSkillBaselineToState(true);

		long levelCredits = 0L;
		for (RetroLevelUp levelUp : pendingLevelUps)
		{
			levelCredits += awardLevelUps(levelUp.skill, levelUp.previousLevel, levelUp.currentLevel);
		}
		if (pendingNonCombatXp > 0L)
		{
			applyXpGain(pendingNonCombatXp, "offline");
		}

		if (pendingNonCombatXp > 0L || levelCredits > 0L)
		{
			debugAward(String.format(
				"Retroactive skill credits after settle: +%s non-combat XP, +%s level-up credits (total %s)",
				NumberFormatting.format(pendingNonCombatXp),
				NumberFormatting.format(levelCredits),
				NumberFormatting.format(stateService.getCredits())));
		}
		else
		{
			debugAward("Retroactive skill check after settle: no XP or level gains since last snapshot");
		}
	}

	private static final class RetroLevelUp
	{
		private final Skill skill;
		private final int previousLevel;
		private final int currentLevel;

		private RetroLevelUp(Skill skill, int previousLevel, int currentLevel)
		{
			this.skill = skill;
			this.previousLevel = previousLevel;
			this.currentLevel = currentLevel;
		}
	}

	private long awardLevelUps(Skill skill, int previousLevel, int currentLevel)
	{
		long totalReward = awardLevelUps(previousLevel, currentLevel);
		if (totalReward > 0L && skill != null)
		{
			debugAward(String.format("Level up %s: %d -> %d -> +%s credits (total %s)",
				skill.getName(), previousLevel, currentLevel,
				NumberFormatting.format(totalReward), NumberFormatting.format(stateService.getCredits())));
		}
		return totalReward;
	}

	/** PvP-only economy: level-ups no longer award credits (see {@link PvpKillCreditTracker}). */
	private long awardLevelUps(int previousLevel, int currentLevel)
	{
		return 0L;
	}

	private void trackXpGainFromStatChanged(Skill skill, int currentXp)
	{
		if (isOverallSkill(skill))
		{
			return;
		}

		int skillIndex = skill.ordinal();
		if (skillIndex < 0 || skillIndex >= previousSkillXp.length)
		{
			return;
		}

		int previousXp = previousSkillXp[skillIndex];
		// Skill XP cannot decrease; never lower the baseline (avoids disconnect false awards).
		if (currentXp < previousXp)
		{
			debugAward(String.format(
				"Ignored skill XP drop for %s (%s -> %s); keeping baseline",
				skill.getName(), NumberFormatting.format(previousXp), NumberFormatting.format(currentXp)));
			return;
		}

		if (currentXp == previousXp)
		{
			return;
		}

		if (skillXpInitialized)
		{
			long xpGained = (long) currentXp - previousXp;
			if (isCombatSkill(skill))
			{
				debugAward(String.format(
					"Ignored +%s combat skill XP (%s)",
					NumberFormatting.format(xpGained), skill.getName()));
			}
			else if (!isCreditAwardOnCooldown())
			{
				applyXpGain(xpGained, skill.getName());
			}
		}
		previousSkillXp[skillIndex] = currentXp;
	}

	/** PvP-only economy: skilling XP no longer awards credits (see {@link PvpKillCreditTracker}). */
	private void applyXpGain(long xpGained, String source)
	{
	}

	private void addCredits(long credits)
	{
		if (credits <= 0L)
		{
			return;
		}

		persistSkillBaselineToState(false);
		stateService.addCredits(credits);
	}

	/**
	 * Writes the current in-memory skill baselines into profile state.
	 *
	 * @param save whether to flush to disk immediately
	 */
	private void persistSkillBaselineToState(boolean save)
	{
		if (!skillXpInitialized)
		{
			return;
		}

		SkillCreditBaseline baseline = SkillCreditBaseline.fromClientExperiences(
			Arrays.copyOf(previousSkillXp, previousSkillXp.length),
			uncreditedXp);
		stateService.replaceSkillCreditBaseline(baseline);
		if (save)
		{
			stateService.save();
		}
	}

	private void suppressCreditAwardsUntilStatsSettle(boolean clearUncreditedXpPool)
	{
		beginCreditAwardCooldown();
		resetSkillCreditTracking(clearUncreditedXpPool);
	}

	private void beginCreditAwardCooldown()
	{
		creditAwardCooldownActive = true;
		if (client == null)
		{
			creditAwardCooldownUntilTick = 0;
			return;
		}

		creditAwardCooldownUntilTick = client.getTickCount() + CREDIT_AWARD_COOLDOWN_TICKS;
	}

	private boolean isCreditAwardOnCooldown()
	{
		if (!creditAwardCooldownActive || client == null)
		{
			return false;
		}

		int tick = client.getTickCount();
		if (tick >= creditAwardCooldownUntilTick)
		{
			return false;
		}

		// Cooldown armed before the tick counter reset (e.g. at the login screen).
		if (creditAwardCooldownUntilTick - tick > CREDIT_AWARD_COOLDOWN_TICKS)
		{
			return false;
		}

		return true;
	}

	private void resetSkillCreditTracking(boolean clearUncreditedXpPool)
	{
		lastKnownLevels.clear();
		skillLevelsInitialized = false;
		skillXpInitialized = false;
		if (clearUncreditedXpPool)
		{
			clearUncreditedXpPool("login or logout");
		}
		Arrays.fill(previousSkillXp, 0);
	}

	private void clearUncreditedXpPool(String reason)
	{
		if (uncreditedXp <= 0L)
		{
			return;
		}

		debugAward(String.format(
			"Uncredited XP pool cleared (%s); lost %s XP toward next chunk",
			reason, NumberFormatting.format(uncreditedXp)));
		uncreditedXp = 0L;
	}

	private void snapshotSkillBaselinesIfLoggedIn()
	{
		snapshotSkillExperiencesIfLoggedIn();
		snapshotSkillLevelsIfLoggedIn();
	}

	private void snapshotSkillExperiencesIfLoggedIn()
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int[] experiences = client.getSkillExperiences();
		int n = Math.min(experiences.length, previousSkillXp.length);
		if (!skillXpInitialized)
		{
			System.arraycopy(experiences, 0, previousSkillXp, 0, n);
		}
		else
		{
			// Never lower an already-established baseline from a transient client snapshot.
			for (int i = 0; i < n; i++)
			{
				if (experiences[i] > previousSkillXp[i])
				{
					previousSkillXp[i] = experiences[i];
				}
			}
		}
		skillXpInitialized = true;
	}

	private void snapshotSkillLevelsIfLoggedIn()
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (!skillLevelsInitialized)
		{
			lastKnownLevels.clear();
		}
		for (Skill skill : Skill.values())
		{
			if (isOverallSkill(skill))
			{
				continue;
			}

			int level = levelForXp(client.getSkillExperience(skill));
			Integer previous = lastKnownLevels.get(skill);
			if (previous == null || level > previous)
			{
				lastKnownLevels.put(skill, level);
			}
		}
		skillLevelsInitialized = true;
	}

	/** Virtual-aware skill level from total XP (1–126). */
	private int levelForXp(int xp)
	{
		return clampLevel(Experience.getLevelForXp(Math.max(0, xp)));
	}

	private int clampLevel(int level)
	{
		if (level < 1)
		{
			return 1;
		}
		return Math.min(level, Experience.MAX_VIRT_LEVEL);
	}

	private String safeName(String name)
	{
		return name == null || name.isEmpty() ? "Unknown NPC" : name;
	}

	private void debugAward(String message)
	{
		boolean chat = stateService.isDebugChatEnabled();
		boolean trace = stateService.isDebugTracingActive();
		if (!chat && !trace)
		{
			return;
		}

		log.info("[Bronzeman PVP TCG] {}", message);
		if (chat)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[Bronzeman PVP TCG] " + message, null);
		}
	}

	private boolean isOverallSkill(Skill skill)
	{
		return skill != null && "Overall".equalsIgnoreCase(skill.getName());
	}

	private boolean isCombatSkill(Skill skill)
	{
		return skill != null && COMBAT_SKILLS.contains(skill);
	}


	private boolean isGenuineMaxedSkillFakeXpDrop(Skill skill)
	{
		if (client == null || isOverallSkill(skill))
		{
			return false;
		}

		return client.getSkillExperience(skill) >= Experience.MAX_SKILL_XP;
	}
}

package com.bronzemanpvptcg.service;

import java.util.ArrayDeque;
import javax.inject.Singleton;

/**
 * Sliding-window credits-per-hour from recent {@link TcgStateService#addCredits(long)} gains.
 * The displayed rate is only recomputed when a new credit drop is recorded.
 */
@Singleton
public class CreditsRateTracker
{
	private static final long WINDOW_MS = 15L * 60L * 1000L;
	private static final int MIN_DROPS_TO_SHOW = 3;

	private final ArrayDeque<CreditDrop> drops = new ArrayDeque<>();
	/** Last rate computed on a credit drop; {@code null} until {@value #MIN_DROPS_TO_SHOW} drops in-window. */
	private Long cachedCreditsPerHour;

	public synchronized void recordCreditGain(long amount)
	{
		if (amount <= 0L)
		{
			return;
		}

		long now = System.currentTimeMillis();
		drops.addLast(new CreditDrop(now, amount));
		prune(now);
		recomputeCachedRate(now);
	}

	/**
	 * @return last credits/h computed on a credit drop, or {@code null} until at least
	 * {@value #MIN_DROPS_TO_SHOW} drops are in the 15-minute window, or after 15 minutes
	 * with no new drops
	 */
	public synchronized Long creditsPerHourOrNull()
	{
		if (cachedCreditsPerHour == null || drops.isEmpty())
		{
			return null;
		}

		long now = System.currentTimeMillis();
		if (now - drops.peekLast().timeMs >= WINDOW_MS)
		{
			cachedCreditsPerHour = null;
			prune(now);
			return null;
		}

		return cachedCreditsPerHour;
	}

	public synchronized void clear()
	{
		drops.clear();
		cachedCreditsPerHour = null;
	}

	private void recomputeCachedRate(long nowMs)
	{
		if (drops.size() < MIN_DROPS_TO_SHOW)
		{
			cachedCreditsPerHour = null;
			return;
		}

		long total = 0L;
		long oldestMs = drops.peekFirst().timeMs;
		for (CreditDrop drop : drops)
		{
			total += drop.amount;
		}

		long elapsedMs = Math.max(1L, nowMs - oldestMs);
		cachedCreditsPerHour = Math.round(total * 3_600_000.0d / (double) elapsedMs);
	}

	private void prune(long nowMs)
	{
		long cutoff = nowMs - WINDOW_MS;
		while (!drops.isEmpty() && drops.peekFirst().timeMs < cutoff)
		{
			drops.removeFirst();
		}
	}

	private static final class CreditDrop
	{
		private final long timeMs;
		private final long amount;

		private CreditDrop(long timeMs, long amount)
		{
			this.timeMs = timeMs;
			this.amount = amount;
		}
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.util.PullNotificationMessages;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Sends pack-pull webhook requests to the <a href="https://github.com/pajlads/DinkPlugin">Dink</a> plugin.
 * Requires Dink's {@code External Plugin Requests > Enable External Plugin Notifications}.
 */
@Slf4j
@Singleton
public class DinkNotificationService
{
	static final class PackPull
	{
		private final String cardName;
		private final boolean newForCollection;
		private final boolean foil;
		private final RarityMath.Tier tier;
		private final boolean notificationEligible;

		PackPull(
			String cardName,
			boolean newForCollection,
			boolean foil,
			RarityMath.Tier tier,
			boolean notificationEligible)
		{
			this.cardName = cardName;
			this.newForCollection = newForCollection;
			this.foil = foil;
			this.tier = tier;
			this.notificationEligible = notificationEligible;
		}
	}

	private static final String DINK_NAMESPACE = "dink";
	private static final String DINK_NOTIFY = "notify";
	private static final String SOURCE_PLUGIN = "Bronzeman PVP TCG";
	private static final String EMBED_TITLE = "Bronzeman PVP TCG";

	private final EventBus eventBus;
	private final CardDatabase cardDatabase;
	private final WikiImageCacheService wikiImageCacheService;
	private final TcgPublicStatsCalculator tcgPublicStatsCalculator;
	private final TcgChatStatsShareService tcgChatStatsShareService;

	@Inject
	DinkNotificationService(
		EventBus eventBus,
		CardDatabase cardDatabase,
		WikiImageCacheService wikiImageCacheService,
		TcgPublicStatsCalculator tcgPublicStatsCalculator,
		TcgChatStatsShareService tcgChatStatsShareService)
	{
		this.eventBus = eventBus;
		this.cardDatabase = cardDatabase;
		this.wikiImageCacheService = wikiImageCacheService;
		this.tcgPublicStatsCalculator = tcgPublicStatsCalculator;
		this.tcgChatStatsShareService = tcgChatStatsShareService;
	}

	public void notifyPackPull(String cardName, boolean newForCollection, boolean foil, RarityMath.Tier tier)
	{
		if (cardName == null || cardName.trim().isEmpty())
		{
			return;
		}
		String trimmed = cardName.trim();
		String tierLabel = tier == null ? "" : tier.getLabel();
		String imageUrl = resolveCardImageUrl(trimmed);

		Map<String, Object> data = new HashMap<>();
		data.put("sourcePlugin", SOURCE_PLUGIN);
		data.put("text", messageWithStatsLine(
			PullNotificationMessages.dinkCollectionMessage(trimmed, newForCollection, foil)));
		data.put("title", EMBED_TITLE);
		data.put("imageRequested", true);
		if (!imageUrl.isEmpty())
		{
			data.put("thumbnail", imageUrl);
		}
		Map<String, Object> metadata = new HashMap<>();
		metadata.put("cardName", trimmed);
		metadata.put("foil", foil);
		metadata.put("newForCollection", newForCollection);
		metadata.put("rarityTier", tierLabel);
		if (!imageUrl.isEmpty())
		{
			metadata.put("imageUrl", imageUrl);
		}
		data.put("metadata", metadata);

		try
		{
			eventBus.post(new PluginMessage(DINK_NAMESPACE, DINK_NOTIFY, data));
		}
		catch (Exception ex)
		{
			log.debug("Failed to post Dink notification", ex);
		}
	}

	void notifyPackSummary(List<PackPull> pulls)
	{
		if (pulls == null || pulls.isEmpty())
		{
			return;
		}
		List<String> newCards = new ArrayList<>();
		List<String> duplicates = new ArrayList<>();
		List<PackPull> sortedPulls = new ArrayList<>(pulls);
		sortedPulls.sort(Comparator.comparingInt(DinkNotificationService::tierRank).reversed());
		for (PackPull pull : sortedPulls)
		{
			if (pull == null || pull.cardName == null || pull.cardName.trim().isEmpty())
			{
				continue;
			}
			String displayName = pull.cardName.trim() + (pull.foil ? " (foil)" : "");
			if (pull.notificationEligible)
			{
				displayName = "**" + displayName + "**";
			}
			(pull.newForCollection ? newCards : duplicates).add(displayName);
		}
		if (newCards.isEmpty() && duplicates.isEmpty())
		{
			return;
		}

		PackPull thumbnailPull = pulls.get(0);
		String imageUrl = thumbnailPull == null ? "" : resolveCardImageUrl(thumbnailPull.cardName);
		Map<String, Object> data = new HashMap<>();
		data.put("sourcePlugin", SOURCE_PLUGIN);
		data.put("text", messageWithStatsLine(PullNotificationMessages.dinkPackSummaryMessage(newCards, duplicates)));
		data.put("title", EMBED_TITLE);
		data.put("imageRequested", true);
		if (!imageUrl.isEmpty())
		{
			data.put("thumbnail", imageUrl);
		}
		Map<String, Object> metadata = new HashMap<>();
		metadata.put("notificationType", "packSummary");
		metadata.put("newCards", new ArrayList<>(newCards));
		metadata.put("duplicates", new ArrayList<>(duplicates));
		data.put("metadata", metadata);

		try
		{
			eventBus.post(new PluginMessage(DINK_NAMESPACE, DINK_NOTIFY, data));
		}
		catch (Exception ex)
		{
			log.debug("Failed to post Dink pack summary", ex);
		}
	}

	private static int tierRank(PackPull pull)
	{
		return pull == null || pull.tier == null ? -1 : pull.tier.ordinal();
	}

	private String messageWithStatsLine(String message)
	{
		return message + "\n\n" + tcgChatStatsShareService.buildPlainLine(tcgPublicStatsCalculator.computeLive());
	}

	private String resolveCardImageUrl(String cardName)
	{
		return cardDatabase.findByName(cardName)
			.map(CardDefinition::getImageUrl)
			.map(wikiImageCacheService::publicImageUrl)
			.orElse("");
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDefinition;

/** Credits awarded when selling duplicate or individually selected collection copies. */
public final class DuplicateSellCredits
{
	public static final long SCORE_DIVISOR = 200L;
	public static final long MIN_CREDITS = 10L;

	private DuplicateSellCredits()
	{
	}

	public static long creditsForRoundedScore(long score)
	{
		return Math.max(MIN_CREDITS, score / SCORE_DIVISOR);
	}

	public static long creditsForCard(CardDefinition card)
	{
		return creditsForCard(card, false);
	}

	public static long creditsForCard(CardDefinition card, boolean foil)
	{
		if (card == null)
		{
			return MIN_CREDITS;
		}
		long rounded = foil
			? RarityMath.foilAdjustedScoreRounded(card)
			: Math.round(RarityMath.score(card));
		return creditsForRoundedScore(rounded);
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.DuplicateKeepTier;
import com.bronzemanpvptcg.model.DuplicateKeepVersion;
import com.bronzemanpvptcg.model.OwnedCardInstance;
import com.bronzemanpvptcg.model.PullNotifyTier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/** Chooses which duplicate copies to sell, respecting per-instance locks. */
public final class DuplicateSellPlanner
{
	public static final class Result
	{
		private final List<OwnedCardInstance> kept;
		private final long creditsToAdd;
		private final int cardsSold;

		private Result(List<OwnedCardInstance> kept, long creditsToAdd, int cardsSold)
		{
			this.kept = kept;
			this.creditsToAdd = creditsToAdd;
			this.cardsSold = cardsSold;
		}

		public List<OwnedCardInstance> getKept()
		{
			return kept;
		}

		public long getCreditsToAdd()
		{
			return creditsToAdd;
		}

		public int getCardsSold()
		{
			return cardsSold;
		}
	}

	private DuplicateSellPlanner()
	{
	}

	public static boolean hasSellableDuplicates(List<OwnedCardInstance> all, DuplicateKeepVersion keepVersion,
		Function<String, RarityMath.Tier> tierForName, DuplicateKeepTier keepTier)
	{
		return plan(all, name -> null, keepVersion, tierForName, keepTier).getCardsSold() > 0;
	}

	public static Result plan(List<OwnedCardInstance> all, Function<String, CardDefinition> cardDefForName,
		DuplicateKeepVersion keepVersion, Function<String, RarityMath.Tier> tierForName, DuplicateKeepTier keepTier)
	{
		if (all == null || all.isEmpty())
		{
			return new Result(List.of(), 0L, 0);
		}

		Map<String, List<OwnedCardInstance>> byName = new HashMap<>();
		for (OwnedCardInstance i : all)
		{
			if (i == null || i.getCardName() == null)
			{
				continue;
			}
			byName.computeIfAbsent(i.getCardName(), k -> new ArrayList<>()).add(i);
		}

		List<OwnedCardInstance> kept = new ArrayList<>();
		long creditsToAdd = 0L;
		int cardsSold = 0;

		for (Map.Entry<String, List<OwnedCardInstance>> entry : byName.entrySet())
		{
			String name = entry.getKey();
			List<OwnedCardInstance> lst = entry.getValue();
			if (lst.size() <= 1)
			{
				kept.addAll(lst);
				continue;
			}

			RarityMath.Tier tier = tierForName == null ? null : tierForName.apply(name);
			if (keepTier != null && keepTier.toRarityTier() != null && (tier == null || tier.ordinal() >= keepTier.toRarityTier().ordinal()))
			{
				kept.addAll(lst);
				continue;
			}

			CardDefinition def = cardDefForName == null ? null : cardDefForName.apply(name);
			long normalCredits = DuplicateSellCredits.creditsForCard(def, false);
			long foilCredits = DuplicateSellCredits.creditsForCard(def, true);

			List<OwnedCardInstance> locked = new ArrayList<>();
			List<OwnedCardInstance> unlocked = new ArrayList<>();
			for (OwnedCardInstance inst : lst)
			{
				if (inst.isLocked())
				{
					locked.add(inst);
				}
				else
				{
					unlocked.add(inst);
				}
			}
			kept.addAll(locked);

			List<OwnedCardInstance> unlockedFoils = new ArrayList<>();
			List<OwnedCardInstance> unlockedNormals = new ArrayList<>();
			for (OwnedCardInstance inst : unlocked)
			{
				if (inst.isFoil())
				{
					unlockedFoils.add(inst);
				}
				else
				{
					unlockedNormals.add(inst);
				}
			}

			boolean anyFoilInCollection = lst.stream().anyMatch(OwnedCardInstance::isFoil);
			if (anyFoilInCollection)
			{
				if (!unlockedFoils.isEmpty())
				{
					OwnedCardInstance keeper = keeper(unlockedFoils, keepVersion);
					kept.add(keeper);
					for (OwnedCardInstance inst : unlockedFoils)
					{
						if (inst != keeper)
						{
							cardsSold++;
							creditsToAdd += foilCredits;
						}
					}
				}
				for (OwnedCardInstance inst : unlockedNormals)
				{
					cardsSold++;
					creditsToAdd += normalCredits;
				}
			}
			else if (!unlockedNormals.isEmpty())
			{
				OwnedCardInstance keeper = keeper(unlockedNormals, keepVersion);
				kept.add(keeper);
				for (OwnedCardInstance inst : unlockedNormals)
				{
					if (inst != keeper)
					{
						cardsSold++;
						creditsToAdd += normalCredits;
					}
				}
			}
		}

		return new Result(kept, creditsToAdd, cardsSold);
	}

	private static OwnedCardInstance keeper(List<OwnedCardInstance> list, DuplicateKeepVersion keepVersion)
	{
		return keepVersion == DuplicateKeepVersion.OLDEST ? oldest(list) : newest(list);
	}

	private static OwnedCardInstance newest(List<OwnedCardInstance> list)
	{
		return list.stream()
			.max(Comparator.comparingLong(OwnedCardInstance::getPulledAtEpochMs))
			.orElse(list.get(0));
	}

	private static OwnedCardInstance oldest(List<OwnedCardInstance> list)
	{
		return list.stream()
			.min(Comparator.comparingLong(OwnedCardInstance::getPulledAtEpochMs))
			.orElse(list.get(0));
	}
}

