	/**
	 * Boss NPC ids tracked via health ratio when {@link ActorDeath} does not fire (see monster-monitor).
	 */
	private static final class HealthTrackedNpcIds
	{
		/** Amoxliatl — Varlamore frost boss. */
		static final int AMOXLIATL = 13685;

		/** Duke Sucellus — DT2 boss. */
		static final int DUKE_SUCELLUS = 12166;

		/** Perilous Moons — Blood Moon. */
		static final int BLOOD_MOON = 13011;

		/** Perilous Moons — Eclipse Moon. */
		static final int ECLIPSE_MOON = 13012;

		/** Perilous Moons — Blue Moon. */
		static final int BLUE_MOON = 13013;

		static final Set<Integer> ALL = Set.of(
			AMOXLIATL,
			DUKE_SUCELLUS,
			BLOOD_MOON,
			ECLIPSE_MOON,
			BLUE_MOON);

		private HealthTrackedNpcIds()
		{
		}
	}

	private static final class NpcExclusionRule
	{
		private enum MatchMode
		{
			EXACT_NAME,
			NAME_CONTAINS,
			NPC_ID
		}

		private final MatchMode mode;
		private final String pattern;
		private final String exceptName;
		private final Set<Integer> npcIds;

		private NpcExclusionRule(MatchMode mode, String pattern, String exceptName, Set<Integer> npcIds)
		{
			this.mode = mode;
			this.pattern = pattern;
			this.exceptName = exceptName;
			this.npcIds = npcIds;
		}

		static NpcExclusionRule exactName(String name)
		{
			return new NpcExclusionRule(MatchMode.EXACT_NAME, name, null, Set.of());
		}

		static NpcExclusionRule nameContains(String fragment, String exceptName)
		{
			return new NpcExclusionRule(MatchMode.NAME_CONTAINS, fragment, exceptName, Set.of());
		}

		static NpcExclusionRule npcIds(Set<Integer> ids)
		{
			return new NpcExclusionRule(MatchMode.NPC_ID, null, null, ids);
		}

		boolean matches(String normalizedName, int npcId)
		{
			switch (mode)
			{
				case EXACT_NAME:
					return matchesExactName(normalizedName);
				case NAME_CONTAINS:
					return matchesNameContains(normalizedName);
				case NPC_ID:
					return npcIds.contains(npcId);
				default:
					return false;
			}
		}

		boolean matchesName(String normalizedName)
		{
			switch (mode)
			{
				case EXACT_NAME:
					return matchesExactName(normalizedName);
				case NAME_CONTAINS:
					return matchesNameContains(normalizedName);
				default:
					return false;
			}
		}

		private boolean matchesExactName(String normalizedName)
		{
			return pattern.equalsIgnoreCase(normalizedName);
		}

		private boolean matchesNameContains(String normalizedName)
		{
			return normalizedName.toLowerCase(Locale.ENGLISH).contains(pattern.toLowerCase(Locale.ENGLISH))
				&& !exceptName.equalsIgnoreCase(normalizedName);
		}
	}

	/**
	 * NPCs that may not fire {@link ActorDeath}; death inferred from health ratio (see monster-monitor).
	 */
	private static final class SpecialNpcCreditWatch
	{
		private final Map<Integer, NPC> trackedNpcs = new ConcurrentHashMap<>();
		private final Set<Integer> loggedNpcIndices = ConcurrentHashMap.newKeySet();
		private final ClientThread clientThread;
		private final CreditAwardService creditAwardService;
		private final TcgPanel tcgPanel;

		private SpecialNpcCreditWatch(ClientThread clientThread, CreditAwardService creditAwardService, TcgPanel tcgPanel)
		{
			this.clientThread = clientThread;
			this.creditAwardService = creditAwardService;
			this.tcgPanel = tcgPanel;
		}

		boolean isSpecialNpc(NPC npc)
		{
			return npc != null && HealthTrackedNpcIds.ALL.contains(npc.getId());
		}

		void trackNpc(NPC npc)
		{
			if (isSpecialNpc(npc))
			{
				trackedNpcs.put(npc.getIndex(), npc);
			}
		}

		void updateTrackedNpcs()
		{
			clientThread.invokeLater(() ->
			{
				for (NPC npc : Set.copyOf(trackedNpcs.values()))
				{
					if (npc == null)
					{
						continue;
					}
					int healthRatio = npc.getHealthRatio();
					int npcIndex = npc.getIndex();

					if (healthRatio <= 1 && !loggedNpcIndices.contains(npcIndex))
					{
						loggedNpcIndices.add(npcIndex);
						String name = normalizeName(npc.getName());
						if (isExcludedNpcName(name))
						{
							continue;
						}
						int combatLevel = npc.getCombatLevel();
						creditAwardService.awardNpcKillCredits(name, combatLevel);
						tcgPanel.refresh();
					}
					else if (healthRatio > 0 && loggedNpcIndices.contains(npcIndex))
					{
						loggedNpcIndices.remove(npcIndex);
						trackNpc(npc);
					}
				}
			});
		}

		void retrackAfterPlayerHit(NPC npc)
		{
			if (npc == null)
			{
				return;
			}
			int npcIndex = npc.getIndex();
			if (loggedNpcIndices.contains(npcIndex))
			{
				loggedNpcIndices.remove(npcIndex);
				trackNpc(npc);
			}
		}

		void shutdown()
		{
			trackedNpcs.clear();
			loggedNpcIndices.clear();
		}
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.model.CardCollectionKey;
import com.bronzemanpvptcg.model.CollectionState;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;

/**
 * Read-only {@link PluginMessage} API: distinct owned card names (foil and normal folded together).
 * Sibling plugins copy the string constants — they cannot import this class across Hub classloaders.
 * <p>
 * Query: post {@code new PluginMessage(NAMESPACE, QUERY)} → reply {@link #REPLY} with {@link #KEY_OWNED_NAMES}.
 * Push: {@link #CHANGED} with the same payload after collection mutations.
 */
@Slf4j
@Singleton
public class OwnedCardNamesApiService
{
	public static final String NAMESPACE = "bronzemanpvptcg";
	public static final String QUERY = "query-owned-names";
	public static final String REPLY = "owned-names";
	public static final String CHANGED = "owned-names-changed";
	public static final String KEY_OWNED_NAMES = "ownedNames";

	private final EventBus eventBus;
	private final TcgStateService stateService;
	private final AtomicBoolean started = new AtomicBoolean(false);
	private final Runnable onCollectionChanged = this::broadcastChanged;

	@Inject
	OwnedCardNamesApiService(EventBus eventBus, TcgStateService stateService)
	{
		this.eventBus = eventBus;
		this.stateService = stateService;
	}

	public void start()
	{
		if (!started.compareAndSet(false, true))
		{
			return;
		}
		eventBus.register(this);
		stateService.addCollectionChangeListener(onCollectionChanged);
	}

	public void stop()
	{
		if (!started.compareAndSet(true, false))
		{
			return;
		}
		stateService.removeCollectionChangeListener(onCollectionChanged);
		eventBus.unregister(this);
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event)
	{
		if (!started.get()
			|| event == null
			|| !NAMESPACE.equals(event.getNamespace())
			|| !QUERY.equals(event.getName()))
		{
			return;
		}
		post(REPLY, snapshotPayload());
	}

	private void broadcastChanged()
	{
		if (!started.get())
		{
			return;
		}
		post(CHANGED, snapshotPayload());
	}

	private Map<String, Object> snapshotPayload()
	{
		CollectionState collection;
		synchronized (stateService)
		{
			collection = stateService.getState().getCollectionState();
		}
		Map<String, Object> data = new HashMap<>();
		data.put(KEY_OWNED_NAMES, distinctOwnedNames(collection));
		return data;
	}

	static List<String> distinctOwnedNames(CollectionState collection)
	{
		if (collection == null)
		{
			return List.of();
		}
		Set<String> names = new LinkedHashSet<>();
		for (CardCollectionKey key : collection.getOwnedCards().keySet())
		{
			if (key == null)
			{
				continue;
			}
			String name = key.getCardName();
			if (name == null)
			{
				continue;
			}
			String trimmed = name.trim();
			if (!trimmed.isEmpty())
			{
				names.add(trimmed);
			}
		}
		List<String> sorted = new ArrayList<>(names);
		sorted.sort(String.CASE_INSENSITIVE_ORDER);
		return sorted;
	}

	private void post(String name, Map<String, Object> data)
	{
		try
		{
			eventBus.post(new PluginMessage(NAMESPACE, name, data));
		}
		catch (Exception ex)
		{
			log.debug("Failed to post {}", name, ex);
		}
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.BoosterPackDefinition;
import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.CardCollectionKey;
import com.bronzemanpvptcg.model.PackCardResult;
import com.bronzemanpvptcg.model.PackOpenResult;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.util.Text;

@Singleton
public class PackOpeningService
{
	private static final int DEFAULT_PACK_SIZE = 5;

	/**
	 * For Legendary / Mythic / Godly regional picks, weight by {@link RarityMath#score}: lowest score in the tier pool
	 * is {@code this}× as likely as the highest (linear between).
	 */
	private static final double TOP_TIER_SCORE_PULL_RARITY_RATIO = 3.0d;

	/** Normal packs: chance all five pulls are restricted to top three display tiers (Legendary / Mythic / Godly). */
	private static final int APEX_PACK_CHANCE_DENOMINATOR = 3000;

	/** Foil probability multiplier while opening an apex pack (capped at 100%). */
	private static final double APEX_PACK_FOIL_CHANCE_MULTIPLIER = 5.0d;

	private final CardDatabase cardDatabase;
	private final RollPoolFilter rollPoolFilter;
	private final TcgStateService stateService;
	private final Client client;
	private final TcgPartyAnnouncer partyAnnouncer;
	private final PackSafeModeService packSafeModeService;
	private final Random random;

	@Inject
	public PackOpeningService(CardDatabase cardDatabase, TcgStateService stateService, Client client,
		TcgPartyAnnouncer partyAnnouncer, PackSafeModeService packSafeModeService, RollPoolFilter rollPoolFilter)
	{
		this(cardDatabase, stateService, client, partyAnnouncer, packSafeModeService, rollPoolFilter, new Random());
	}

	PackOpeningService(CardDatabase cardDatabase, TcgStateService stateService, Client client,
		TcgPartyAnnouncer partyAnnouncer, PackSafeModeService packSafeModeService, RollPoolFilter rollPoolFilter,
		Random random)
	{
		this.rollPoolFilter = rollPoolFilter;
		this.cardDatabase = cardDatabase;
		this.stateService = stateService;
		this.client = client;
		this.partyAnnouncer = partyAnnouncer;
		this.packSafeModeService = packSafeModeService;
		this.random = random;
	}

	public static boolean isDebugOnlyRegionalPack(BoosterPackDefinition booster)
	{
		return booster != null && booster.isDebugOnly();
	}

	public PackOpenResult buyAndOpenPack(BoosterPackDefinition booster)
	{
		return buyAndOpenPackInternal(booster, false);
	}

	/**
	 * Opens {@code booster} using apex rules (top three display tiers only, 5× foil chance), charging the normal pack price.
	 * Intended for debug ({@code ::tcg-apex}); fails if this booster has no Legendary/Mythic/Godly cards in its pool.
	 */
	public PackOpenResult buyAndOpenApexPackForDebug(BoosterPackDefinition booster)
	{
		return buyAndOpenPackInternal(booster, true);
	}

	private PackOpenResult buyAndOpenPackInternal(BoosterPackDefinition booster, boolean forceApexPack)
	{
		cardDatabase.load();
		long creditsBefore = stateService.getCredits();
		if (booster == null)
		{
			return PackOpenResult.failed("No booster pack selected.", creditsBefore, 0);
		}

		if (packSafeModeService != null && packSafeModeService.isPackOpeningBlocked())
		{
			String blockMessage = packSafeModeService.packOpeningBlockMessage();
			return PackOpenResult.failed(
				blockMessage == null ? "Cannot open packs right now." : blockMessage,
				creditsBefore,
				booster.getPrice());
		}

		if (isDebugOnlyRegionalPack(booster) && !stateService.isDebugLogging())
		{
			return PackOpenResult.failed("Regional packs are only available in debug mode.", creditsBefore, 0);
		}

		int packPrice = booster.getPrice();
		if (packPrice <= 0)
		{
			return PackOpenResult.failed("Invalid pack price.", creditsBefore, packPrice);
		}

		if (creditsBefore < packPrice)
		{
			return PackOpenResult.failed("Not enough credits.", creditsBefore, packPrice);
		}

		List<CardDefinition> rollPool = rollPoolFilter.filterRollPool(cardDatabase.getCards());
		List<String> regionFilters = booster.getCategoryFilters();
		List<CardDefinition> pool = new ArrayList<>();
		for (CardDefinition card : rollPool)
		{
			if (BoosterPackDefinition.cardMatchesRegion(card, regionFilters))
			{
				pool.add(card);
			}
		}

		if (pool.isEmpty())
		{
			return PackOpenResult.failed("No cards in this booster pool.", creditsBefore, packPrice);
		}

		// Rare apex pack (1/3000), or debug forced apex: only Legendary / Mythic / Godly display-tier cards from this pool, 5× foil odds.
		List<CardDefinition> packRollPool = pool;
		boolean apexTopThreeTierOnly = false;
		double foilChanceMultiplier = 1.0d;
		boolean rollApex = forceApexPack || random.nextInt(APEX_PACK_CHANCE_DENOMINATOR) == 0;
		if (rollApex)
		{
			List<CardDefinition> apexPool = topThreeDisplayTierSubset(pool, rollPool);
			if (!apexPool.isEmpty())
			{
				packRollPool = apexPool;
				apexTopThreeTierOnly = true;
				foilChanceMultiplier = APEX_PACK_FOIL_CHANCE_MULTIPLIER;
			}
			else if (forceApexPack)
			{
				return PackOpenResult.failed(
					"No Legendary, Mythic, or Godly cards in this booster for an apex pack.", creditsBefore, packPrice);
			}
		}

		List<PackCardResult> pulls = rollPack(packRollPool, rollPool, DEFAULT_PACK_SIZE, apexTopThreeTierOnly, foilChanceMultiplier);
		// Charge now; collection + PluginMessage wait until the reveal overlay closes (see commitPackPulls).
		if (!stateService.chargePackOpenPurchase(packPrice, false))
		{
			return PackOpenResult.failed("Pack transaction failed.", creditsBefore, packPrice);
		}

		long creditsAfter = stateService.getCredits();
		String packId = booster.getId() == null ? "" : booster.getId().trim();
		return PackOpenResult.succeeded("Pack opened.", creditsBefore, creditsAfter, packPrice, pulls,
			booster.getName(), packId, apexTopThreeTierOnly);
	}

	/**
	 * Adds pulls from a finished pack reveal to the collection (notifies PluginMessage / share listeners) and
	 * announces any newly completed primary-category sets.
	 */
	public void commitPackPulls(List<PackCardResult> pulls)
	{
		if (pulls == null || pulls.isEmpty())
		{
			return;
		}

		Map<CardCollectionKey, Integer> ownedBefore;
		synchronized (stateService)
		{
			ownedBefore = new HashMap<>(stateService.getState().getCollectionState().getOwnedCards());
		}

		if (!stateService.commitPackPulls(pulls, localPullerDisplayName(), false))
		{
			return;
		}

		if (partyAnnouncer == null)
		{
			return;
		}

		cardDatabase.load();
		List<CardDefinition> rollPool = rollPoolFilter.filterRollPool(cardDatabase.getCards());
		Map<CardCollectionKey, Integer> ownedAfter;
		synchronized (stateService)
		{
			ownedAfter = new HashMap<>(stateService.getState().getCollectionState().getOwnedCards());
		}
		for (String category : CollectionSetCompletionUtil.newlyCompletedPrimaryCategories(ownedBefore, ownedAfter, rollPool))
		{
			partyAnnouncer.announceCollectionSetComplete(category);
		}
	}

	/**
	 * Tier rolls use {@link RarityMath#displayTierByCardName(List)} on the full loaded catalog (same as the collection album);
	 * pulls are only from {@code regionalPool}.
	 */
	private List<PackCardResult> rollPack(List<CardDefinition> regionalPool, List<CardDefinition> globalRollPool, int packSize,
		boolean apexTopThreeTierOnly, double foilChanceMultiplier)
	{
		List<PackCardResult> pulls = new ArrayList<>(packSize);
		int foilPercent = stateService.getState().getRewardTuning().getFoilChancePercent();
		double foilChance = Math.min(1.0d,
			Math.max(0.0d, Math.min(100, foilPercent)) / 100.0d * Math.max(0.0d, foilChanceMultiplier));
		Map<CardDefinition, RarityMath.Tier> globalTierByCard = buildGlobalTierByCard(globalRollPool);
		Map<RarityMath.Tier, List<CardDefinition>> regionalByGlobalTier = partitionRegionalByGlobalTier(regionalPool, globalTierByCard);

		for (int i = 0; i < packSize; i++)
		{
			CardDefinition selected = pickByTierChance(regionalPool, regionalByGlobalTier, apexTopThreeTierOnly);
			boolean foil = random.nextDouble() < foilChance;
			pulls.add(new PackCardResult(selected.getName(), foil));
		}
		if (apexTopThreeTierOnly)
		{
			ensureAtLeastOneFoil(pulls);
		}
		return pulls;
	}

	/** Apex packs always contain at least one foil copy (upgrade a random slot if the roll produced none). */
	private void ensureAtLeastOneFoil(List<PackCardResult> pulls)
	{
		if (pulls == null || pulls.isEmpty())
		{
			return;
		}
		for (PackCardResult p : pulls)
		{
			if (p != null && p.isFoil())
			{
				return;
			}
		}
		int idx = random.nextInt(pulls.size());
		PackCardResult old = pulls.get(idx);
		String name = old == null ? "" : old.getCardName();
		pulls.set(idx, new PackCardResult(name, true));
	}

	/**
	 * Cards in {@code regionalPool} whose display tier (full catalog) is Legendary, Mythic, or Godly.
	 */
	private List<CardDefinition> topThreeDisplayTierSubset(List<CardDefinition> regionalPool, List<CardDefinition> globalRollPool)
	{
		Map<CardDefinition, RarityMath.Tier> globalTierByCard = buildGlobalTierByCard(globalRollPool);
		List<CardDefinition> out = new ArrayList<>();
		for (CardDefinition card : regionalPool)
		{
			if (card == null)
			{
				continue;
			}
			RarityMath.Tier t = globalTierByCard.getOrDefault(card, RarityMath.Tier.COMMON);
			if (t == RarityMath.Tier.LEGENDARY || t == RarityMath.Tier.MYTHIC || t == RarityMath.Tier.GODLY)
			{
				out.add(card);
			}
		}
		return out;
	}

	private Map<CardDefinition, RarityMath.Tier> buildGlobalTierByCard(List<CardDefinition> globalRollPool)
	{
		Map<CardDefinition, RarityMath.Tier> map = new IdentityHashMap<>();
		if (globalRollPool == null || globalRollPool.isEmpty())
		{
			return map;
		}

		Map<String, RarityMath.Tier> tierByName = RarityMath.displayTierByCardName(cardDatabase.getCards());
		for (CardDefinition card : globalRollPool)
		{
			if (card == null || card.getName() == null || card.getName().trim().isEmpty())
			{
				continue;
			}
			map.put(card, tierByName.getOrDefault(card.getName(), RarityMath.Tier.COMMON));
		}
		return map;
	}

	private static Map<RarityMath.Tier, List<CardDefinition>> partitionRegionalByGlobalTier(
		List<CardDefinition> regionalPool,
		Map<CardDefinition, RarityMath.Tier> globalTierByCard)
	{
		Map<RarityMath.Tier, List<CardDefinition>> out = new EnumMap<>(RarityMath.Tier.class);
		for (RarityMath.Tier tier : RarityMath.Tier.values())
		{
			out.put(tier, new ArrayList<>());
		}
		for (CardDefinition card : regionalPool)
		{
			RarityMath.Tier tier = globalTierByCard.getOrDefault(card, RarityMath.Tier.COMMON);
			out.get(tier).add(card);
		}
		return out;
	}

	private CardDefinition pickByTierChance(List<CardDefinition> fallbackPool,
		Map<RarityMath.Tier, List<CardDefinition>> regionalByGlobalTier, boolean apexTopThreeTierOnly)
	{
		if (fallbackPool.isEmpty())
		{
			return null;
		}

		for (int attempts = 0; attempts < 8; attempts++)
		{
			RarityMath.Tier tier = apexTopThreeTierOnly ? rollTierApexPackOnly() : rollTier();
			List<CardDefinition> tierCards = regionalByGlobalTier.get(tier);
			if (tierCards != null && !tierCards.isEmpty())
			{
				return pickFromTierList(tierCards, tier);
			}
		}

		return fallbackPool.get(random.nextInt(fallbackPool.size()));
	}

	private static boolean tierUsesScoreWeightedPull(RarityMath.Tier tier)
	{
		return tier == RarityMath.Tier.LEGENDARY
			|| tier == RarityMath.Tier.GODLY
			|| tier == RarityMath.Tier.MYTHIC;
	}

	private CardDefinition pickFromTierList(List<CardDefinition> tierCards, RarityMath.Tier tier)
	{
		if (tierCards.size() == 1)
		{
			return tierCards.get(0);
		}
		if (!tierUsesScoreWeightedPull(tier))
		{
			return tierCards.get(random.nextInt(tierCards.size()));
		}

		double minScore = Double.POSITIVE_INFINITY;
		double maxScore = Double.NEGATIVE_INFINITY;
		for (CardDefinition c : tierCards)
		{
			if (c == null)
			{
				continue;
			}
			double s = RarityMath.score(c);
			if (s < minScore)
			{
				minScore = s;
			}
			if (s > maxScore)
			{
				maxScore = s;
			}
		}
		if (minScore == Double.POSITIVE_INFINITY)
		{
			return tierCards.get(random.nextInt(tierCards.size()));
		}

		double totalW = 0.0d;
		double[] weights = new double[tierCards.size()];
		for (int i = 0; i < tierCards.size(); i++)
		{
			CardDefinition c = tierCards.get(i);
			double s = c == null ? minScore : RarityMath.score(c);
			double w = RarityMath.linearTierPullWeightByScore(s, minScore, maxScore, TOP_TIER_SCORE_PULL_RARITY_RATIO);
			weights[i] = w;
			totalW += w;
		}
		if (totalW <= 0.0d)
		{
			return tierCards.get(random.nextInt(tierCards.size()));
		}

		double r = random.nextDouble() * totalW;
		double acc = 0.0d;
		for (int i = 0; i < weights.length; i++)
		{
			acc += weights[i];
			if (r < acc)
			{
				return tierCards.get(i);
			}
		}
		return tierCards.get(tierCards.size() - 1);
	}

	/**
	 * Low roll = rarer: Godly &lt; 0.66%, Mythic &lt; 2.66%, …, Common &lt; 100% of {@code [0, 100)}.
	 */
	private RarityMath.Tier rollTier()
	{
		double roll = random.nextDouble() * 100.0d;
		if (roll < 0.66d)
		{
			return RarityMath.Tier.GODLY;
		}
		if (roll < 2.66d)
		{
			return RarityMath.Tier.MYTHIC;
		}
		if (roll < 6.66d)
		{
			return RarityMath.Tier.LEGENDARY;
		}
		if (roll < 14.66d)
		{
			return RarityMath.Tier.EPIC;
		}
		if (roll < 30.66d)
		{
			return RarityMath.Tier.RARE;
		}
		if (roll < 62.66d)
		{
			return RarityMath.Tier.UNCOMMON;
		}
		return RarityMath.Tier.COMMON;
	}

	/**
	 * Tier roll restricted to Legendary / Mythic / Godly, preserving the same relative odds as the top segment of
	 * {@link #rollTier()} (0.66% / 2% / 4% of the full bar).
	 */
	private RarityMath.Tier rollTierApexPackOnly()
	{
		double roll = random.nextDouble() * 6.66d;
		if (roll < 0.66d)
		{
			return RarityMath.Tier.GODLY;
		}
		if (roll < 2.66d)
		{
			return RarityMath.Tier.MYTHIC;
		}
		return RarityMath.Tier.LEGENDARY;
	}

	private String localPullerDisplayName()
	{
		if (client == null || client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			return "";
		}
		return Text.sanitize(client.getLocalPlayer().getName());
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.CardCollectionKey;
import com.bronzemanpvptcg.model.PackCardResult;
import java.awt.Color;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.Value;

@Singleton
public class PackRevealService
{
	public enum Phase
	{
		IDLE,
		PACK_READY,
		PACK_FADING,
		/** Cards fly from a central pile into the 2+3 grid. */
		CARD_DEAL,
		CARD_REVEAL,
		WAIT_CLOSE
	}

	@Value
	public static class RevealCard
	{
		PackCardResult pull;
		CardDefinition definition;
		RarityMath.Tier tier;
		Color rarityColor;
		long basePullDenominator;
		boolean isNew;
	}

	/**
	 * Immutable snapshot of reveal state for one overlay paint. The overlay must not mix a captured card list with
	 * live {@link #isCardRevealed(int)} calls across threads: after {@link #reset()}, the old list can still be
	 * referenced while reveal flags are cleared, which briefly paints every slot face-down.
	 */
	public static final class RevealPaintSnapshot
	{
		private final Phase phase;
		private final List<RevealCard> cards;
		private final boolean[] revealedByIndex;
		private final long phaseElapsedMs;
		private final double packFadeProgress;
		private final String boosterPackId;
		private final boolean showScrollWheelOverlayHint;
		private final boolean apexPackOpen;

		private RevealPaintSnapshot(Phase phase, List<RevealCard> cards, boolean[] revealedByIndex, long phaseElapsedMs,
			double packFadeProgress, String boosterPackId, boolean showScrollWheelOverlayHint, boolean apexPackOpen)
		{
			this.phase = phase;
			this.cards = cards;
			this.revealedByIndex = revealedByIndex;
			this.phaseElapsedMs = phaseElapsedMs;
			this.packFadeProgress = packFadeProgress;
			this.boosterPackId = boosterPackId == null ? "" : boosterPackId;
			this.showScrollWheelOverlayHint = showScrollWheelOverlayHint;
			this.apexPackOpen = apexPackOpen;
		}

		public Phase getPhase()
		{
			return phase;
		}

		public List<RevealCard> getCards()
		{
			return cards;
		}

		public long getPhaseElapsedMs()
		{
			return phaseElapsedMs;
		}

		public double getPackFadeProgress()
		{
			return packFadeProgress;
		}

		public String getBoosterPackId()
		{
			return boosterPackId;
		}

		/** Whether the first-pack scroll/zoom hint should be drawn this frame (10 seconds from reveal start). */
		public boolean isShowScrollWheelOverlayHint()
		{
			return showScrollWheelOverlayHint;
		}

		public boolean isApexPackOpen()
		{
			return apexPackOpen;
		}

		public boolean isCardRevealed(int index)
		{
			return index >= 0 && index < revealedByIndex.length && revealedByIndex[index];
		}

		/**
		 * True while any face-down card still qualifies for premium reveal audio (hum / reveal chime).
		 * @see PackRevealService#isPremiumRevealAudioPull(RevealCard)
		 */
		public boolean hasUnrevealedMythic()
		{
			for (int i = 0; i < cards.size(); i++)
			{
				boolean revealed = i < revealedByIndex.length && revealedByIndex[i];
				if (revealed)
				{
					continue;
				}
				RevealCard card = cards.get(i);
				if (isPremiumRevealAudioPull(card))
				{
					return true;
				}
			}
			return false;
		}
	}

	private static final long PACK_FADE_MS = 500L;
	private static final long SCROLL_WHEEL_HINT_DURATION_MS = 10_000L;

	/** Milliseconds between each card starting its flight from the pile. */
	public static final long PACK_DEAL_STAGGER_MS = 115L;
	/** Duration of each card's flight from pile to slot. */
	public static final long PACK_DEAL_FLIGHT_MS = 260L;

	private final CardDatabase cardDatabase;
	private final RollPoolFilter rollPoolFilter;
	private final WikiImageCacheService imageCacheService;
	private final PackRevealSoundService packRevealSoundService;
	private final PullNotificationService pullNotificationService;
	/** Provider avoids a Guice cycle: PackOpening → PackSafeMode → PackReveal → PackOpening. */
	private final Provider<PackOpeningService> packOpeningService;

	private Phase phase = Phase.IDLE;
	private List<RevealCard> cards = List.of();
	private int revealedCount;
	private boolean[] revealedByIndex = new boolean[0];
	private boolean dinkEndNotificationsSent;
	private long phaseStartedAt;
	private int cardPoolSize;
	private final Map<String, RarityMath.Tier> rarityTierByCardName = new HashMap<>();
	private final Map<RarityMath.Tier, Integer> tierPopulation = new EnumMap<>(RarityMath.Tier.class);
	private String boosterDisplayName = "";
	private String boosterPackId = "";
	/** When true, sealed-pack overlay uses apex hover sound and Godly-tier glow. */
	private boolean apexPackOpen;
	/** Wall-clock ms until which the first-pack scroll hint is shown; {@code 0} = off. */
	private long scrollWheelHintUntilMs;
	/**
	 * Pulls charged at pack buy but not yet written to the collection. Committed when the overlay closes
	 * ({@link #reset()}); cleared without commit on {@link #discardActiveReveal()}.
	 */
	private List<PackCardResult> pendingCollectionPulls = List.of();

	@Inject
	public PackRevealService(CardDatabase cardDatabase, WikiImageCacheService imageCacheService,
		PackRevealSoundService packRevealSoundService, PullNotificationService pullNotificationService,
		Provider<PackOpeningService> packOpeningService, RollPoolFilter rollPoolFilter)
	{
		this.rollPoolFilter = rollPoolFilter;
		this.cardDatabase = cardDatabase;
		this.imageCacheService = imageCacheService;
		this.packRevealSoundService = packRevealSoundService;
		this.pullNotificationService = pullNotificationService;
		this.packOpeningService = packOpeningService;
	}

	public synchronized void startReveal(List<PackCardResult> pulls)
	{
		startReveal(pulls, Set.of(), null, null, false, false);
	}

	public synchronized void startReveal(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards)
	{
		startReveal(pulls, preOwnedCards, null, null, false, false);
	}

	/**
	 * Rarity tiers match the collection album ({@link RarityMath#displayTierByCardName(List)} on the full loaded catalog).
	 * {@link RollPoolFilter} only affects the reported roll-pool size, not tier labels.
	 * Quest-only wiki items are omitted from {@code Card.json} at catalog build time.
	 */
	public synchronized void startReveal(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards, String boosterTitle)
	{
		startReveal(pulls, preOwnedCards, boosterTitle, null, false, false);
	}

	public synchronized void startReveal(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards,
		String boosterTitle, String boosterPackId)
	{
		startReveal(pulls, preOwnedCards, boosterTitle, boosterPackId, false, false);
	}

	public synchronized void startReveal(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards,
		String boosterTitle, String boosterPackId, boolean showScrollWheelOverlayHint)
	{
		startReveal(pulls, preOwnedCards, boosterTitle, boosterPackId, showScrollWheelOverlayHint, false);
	}

	public synchronized void startReveal(List<PackCardResult> pulls, Set<CardCollectionKey> preOwnedCards,
		String boosterTitle, String boosterPackId, boolean showScrollWheelOverlayHint, boolean apexPackOpen)
	{
		// Finish any prior deferred collection write before starting a new reveal session.
		commitPendingCollectionLocked();

		if (pulls == null || pulls.isEmpty())
		{
			clearRevealStateLocked();
			return;
		}

		packRevealSoundService.hardStop();

		cardDatabase.load();
		this.scrollWheelHintUntilMs = showScrollWheelOverlayHint
			? System.currentTimeMillis() + SCROLL_WHEEL_HINT_DURATION_MS
			: 0L;
		this.boosterDisplayName = boosterTitle == null ? "" : boosterTitle.trim();
		this.boosterPackId = boosterPackId == null ? "" : boosterPackId.trim();
		this.apexPackOpen = apexPackOpen;
		rebuildRarityTierIndex();

		List<RevealCard> resolved = new ArrayList<>();
		List<PackCardResult> pendingPulls = new ArrayList<>();
		Set<String> preOwnedKeys = preOwnedCards == null ? Set.of() : preOwnedCards.stream()
			.filter(Objects::nonNull)
			.map(k -> normalizeKey(k.getCardName(), k.isFoil()))
			.collect(Collectors.toSet());
		for (PackCardResult pull : pulls)
		{
			if (pull == null || pull.getCardName() == null)
			{
				continue;
			}

			CardDefinition definition = findCard(pull.getCardName()).orElseGet(() ->
			{
				CardDefinition fallback = new CardDefinition();
				fallback.setName(pull.getCardName());
				fallback.setCategory(new ArrayList<>());
				fallback.setExamine("No examine text.");
				return fallback;
			});
			RarityMath.Tier tier = tierForCard(definition == null ? null : definition.getName());
			Color rarityColor = tier.getColor();
			long denominator = RarityMath.denominatorForTierCard(tier, tierPopulation.getOrDefault(tier, 1));
			boolean isNew = !preOwnedKeys.contains(normalizeKey(pull.getCardName(), pull.isFoil()));
			resolved.add(new RevealCard(pull, definition, tier, rarityColor, denominator, isNew));
			pendingPulls.add(pull);
		}

		Collections.shuffle(resolved, ThreadLocalRandom.current());
		this.cards = List.copyOf(resolved);
		this.pendingCollectionPulls = List.copyOf(pendingPulls);
		imageCacheService.preload(this.cards.stream()
			.map(c -> c.getDefinition() == null ? null : c.getDefinition().getImageUrl())
			.collect(Collectors.toList()));
		this.revealedCount = 0;
		this.revealedByIndex = new boolean[this.cards.size()];
		this.dinkEndNotificationsSent = false;
		this.phaseStartedAt = 0L;
		this.phase = cards.isEmpty() ? Phase.IDLE : Phase.PACK_READY;
		if (cards.isEmpty())
		{
			// Buy already charged; still try to commit whatever valid pulls we were given.
			commitPendingCollectionLocked();
		}
	}

	public synchronized void handleClick(Point click, Rectangle packBounds, List<Rectangle> cardBounds)
	{
		if (phase == Phase.IDLE)
		{
			return;
		}

		if (phase == Phase.PACK_READY)
		{
			if (packBounds != null && click != null && packBounds.contains(click))
			{
				phase = Phase.PACK_FADING;
				phaseStartedAt = System.currentTimeMillis();
			}
			return;
		}

		if (phase == Phase.CARD_DEAL)
		{
			return;
		}

		// Fully revealed grid (or count says we're done): any click closes (WAIT_CLOSE, desync, stuck CARD_REVEAL).
		if (click != null && !cards.isEmpty() && (allRevealSlotsFaceUp() || revealedCount >= cards.size()))
		{
			reset();
			return;
		}

		if (phase == Phase.CARD_REVEAL && revealedCount < cards.size())
		{
			int clickedIndex = clickedCardIndex(cardBounds, click);
			if (clickedIndex >= 0 && clickedIndex < revealedByIndex.length && !revealedByIndex[clickedIndex])
			{
				RevealCard clicked = cards.get(clickedIndex);
				revealedByIndex[clickedIndex] = true;
				revealedCount++;
				packRevealSoundService.playCardFlip();
				if (isPremiumRevealAudioPull(clicked))
				{
					packRevealSoundService.playMythicReveal();
				}
				pullNotificationService.notifyPull(
					cardNameForParty(clicked), clicked.isNew(), isFoilPull(clicked), clicked.getTier());
				if (revealedCount >= cards.size())
				{
					notifyDinkAtEndOnce();
					phase = Phase.WAIT_CLOSE;
					phaseStartedAt = System.currentTimeMillis();
				}
			}
		}
	}

	/**
	 * Right-click shortcut: skip to all cards face-up and wait-for-close. Only runs after the deal animation has
	 * finished ({@link Phase#CARD_REVEAL} or later). Does nothing during sealed pack, fade, or while cards are still
	 * flying into the grid ({@link Phase#PACK_READY}, {@link Phase#PACK_FADING}, {@link Phase#CARD_DEAL}), or when
	 * already waiting to close ({@link Phase#WAIT_CLOSE}).
	 *
	 * @return {@code true} if reveal-all was applied (caller may refresh UI / consume the click)
	 */
	public synchronized boolean revealAllCards()
	{
		if (phase == Phase.IDLE || cards.isEmpty())
		{
			return false;
		}
		if (phase == Phase.PACK_READY || phase == Phase.PACK_FADING || phase == Phase.CARD_DEAL || phase == Phase.WAIT_CLOSE)
		{
			return false;
		}
		forceRevealAllAndWaitClose();
		return true;
	}

	/**
	 * Escape / Space progression: open sealed pack, reveal all cards, then close.
	 *
	 * @return {@code true} if the reveal session ended ({@link #reset()})
	 */
	public synchronized boolean advanceFromKeyboard()
	{
		if (phase == Phase.IDLE || cards.isEmpty())
		{
			return false;
		}

		if (phase == Phase.PACK_READY)
		{
			phase = Phase.PACK_FADING;
			phaseStartedAt = System.currentTimeMillis();
			return false;
		}

		if (phase == Phase.PACK_FADING || phase == Phase.CARD_DEAL
			|| (phase == Phase.CARD_REVEAL && revealedCount < cards.size()))
		{
			forceRevealAllAndWaitClose();
			return false;
		}

		reset();
		return true;
	}

	public synchronized void skip()
	{
		advanceFromKeyboard();
	}

	private void forceRevealAllAndWaitClose()
	{
		if (phase == Phase.CARD_REVEAL && revealedCount < cards.size())
		{
			packRevealSoundService.playCardFlip();
		}
		announcePartyMythicPullsForPreviouslyUnrevealedSlots();
		playMythicRevealIfAnyUnrevealedMythic();
		revealedCount = cards.size();
		for (int i = 0; i < revealedByIndex.length; i++)
		{
			revealedByIndex[i] = true;
		}
		notifyDinkAtEndOnce();
		phase = Phase.WAIT_CLOSE;
		phaseStartedAt = System.currentTimeMillis();
	}

	public synchronized void tick()
	{
		if (phase == Phase.PACK_FADING && phaseStartedAt > 0L && (System.currentTimeMillis() - phaseStartedAt) >= PACK_FADE_MS)
		{
			phase = Phase.CARD_DEAL;
			phaseStartedAt = System.currentTimeMillis();
		}
		else if (phase == Phase.CARD_DEAL && phaseStartedAt > 0L
			&& (System.currentTimeMillis() - phaseStartedAt) >= packDealPhaseTotalMs(cards.size()))
		{
			phase = Phase.CARD_REVEAL;
			phaseStartedAt = System.currentTimeMillis();
		}
		else if (phase == Phase.CARD_REVEAL && allRevealSlotsFaceUp())
		{
			notifyDinkAtEndOnce();
			phase = Phase.WAIT_CLOSE;
			phaseStartedAt = System.currentTimeMillis();
		}
	}

	/** Total time the overlay stays in {@link Phase#CARD_DEAL} before click-to-reveal begins. */
	public static long packDealPhaseTotalMs(int cardCount)
	{
		if (cardCount <= 0)
		{
			return 0L;
		}
		return (long) (cardCount - 1) * PACK_DEAL_STAGGER_MS + PACK_DEAL_FLIGHT_MS;
	}

	public synchronized boolean isActive()
	{
		return phase != Phase.IDLE && !cards.isEmpty();
	}

	/**
	 * Advances time-based transitions ({@link #tick()}), then returns immutable state for this paint frame.
	 */
	public synchronized Optional<RevealPaintSnapshot> capturePaintFrame()
	{
		tick();
		if (phase == Phase.IDLE || cards.isEmpty())
		{
			return Optional.empty();
		}
		long phaseElapsedMs = computePhaseElapsedMsLocked();
		double packFadeProgress = computePackFadeProgressLocked();
		boolean[] revCopy = Arrays.copyOf(revealedByIndex, revealedByIndex.length);
		boolean scrollHintVisible = System.currentTimeMillis() < scrollWheelHintUntilMs;
		return Optional.of(new RevealPaintSnapshot(
			phase,
			List.copyOf(cards),
			revCopy,
			phaseElapsedMs,
			packFadeProgress,
			boosterPackId,
			scrollHintVisible,
			apexPackOpen));
	}

	private long computePhaseElapsedMsLocked()
	{
		if (phaseStartedAt <= 0L)
		{
			return 0L;
		}
		return Math.max(0L, System.currentTimeMillis() - phaseStartedAt);
	}

	private double computePackFadeProgressLocked()
	{
		if (phase != Phase.PACK_FADING || phaseStartedAt <= 0L)
		{
			return phase == Phase.CARD_DEAL || phase == Phase.CARD_REVEAL || phase == Phase.WAIT_CLOSE ? 1.0d : 0.0d;
		}
		double elapsed = (double) (System.currentTimeMillis() - phaseStartedAt);
		return clamp01(elapsed / (double) PACK_FADE_MS);
	}

	public synchronized Phase getPhase()
	{
		return phase;
	}

	public synchronized List<RevealCard> getCards()
	{
		return cards;
	}

	public synchronized int getRevealedCount()
	{
		return revealedCount;
	}

	public synchronized boolean isCardRevealed(int index)
	{
		return index >= 0 && index < revealedByIndex.length && revealedByIndex[index];
	}

	/**
	 * True while any card that qualifies for premium reveal audio (hum / reveal chime) is still face-down
	 * (deal, click-to-reveal, or wait-to-close).
	 * @see #isPremiumRevealAudioPull(RevealCard)
	 */
	public synchronized boolean hasUnrevealedMythic()
	{
		for (int i = 0; i < cards.size(); i++)
		{
			boolean revealed = i < revealedByIndex.length && revealedByIndex[i];
			if (revealed)
			{
				continue;
			}
			RevealCard card = cards.get(i);
			if (isPremiumRevealAudioPull(card))
			{
				return true;
			}
		}
		return false;
	}

	public synchronized double getPackFadeProgress()
	{
		return computePackFadeProgressLocked();
	}

	public synchronized long getPhaseElapsedMs()
	{
		return computePhaseElapsedMsLocked();
	}

	public synchronized int getCardPoolSize()
	{
		return cardPoolSize;
	}

	public synchronized String getBoosterDisplayName()
	{
		return boosterDisplayName;
	}

	public synchronized String getBoosterPackId()
	{
		return boosterPackId;
	}

	/**
	 * Ends the reveal overlay and commits any deferred pack pulls to the collection (fires collection listeners /
	 * PluginMessage). Use {@link #discardActiveReveal()} when the collection is being wiped or replaced instead.
	 */
	public synchronized void reset()
	{
		commitPendingCollectionLocked();
		clearRevealStateLocked();
	}

	/**
	 * Ends the reveal overlay without adding pending pulls (collection wipe, save load, debug profile reset).
	 * Does not refund the pack charge.
	 */
	public synchronized void discardActiveReveal()
	{
		pendingCollectionPulls = List.of();
		packRevealSoundService.hardStop();
		clearRevealStateLocked();
	}

	/**
	 * Stops an active reveal (e.g. Safe-mode combat interrupt). Announces party highlights for unrevealed slots,
	 * commits pulls to the collection, then returns the pulled cards for chat.
	 */
	public synchronized List<RevealCard> abortActiveReveal()
	{
		if (!isActive())
		{
			return List.of();
		}
		announcePartyMythicPullsForPreviouslyUnrevealedSlots();
		List<RevealCard> snapshot = List.copyOf(cards);
		packRevealSoundService.hardStop();
		reset();
		return snapshot;
	}

	private void commitPendingCollectionLocked()
	{
		List<PackCardResult> pending = pendingCollectionPulls;
		pendingCollectionPulls = List.of();
		if (pending.isEmpty() || packOpeningService == null)
		{
			return;
		}
		PackOpeningService opening = packOpeningService.get();
		if (opening == null)
		{
			return;
		}
		opening.commitPackPulls(pending);
	}

	private void clearRevealStateLocked()
	{
		phase = Phase.IDLE;
		cards = List.of();
		revealedCount = 0;
		revealedByIndex = new boolean[0];
		dinkEndNotificationsSent = false;
		phaseStartedAt = 0L;
		cardPoolSize = 0;
		boosterDisplayName = "";
		boosterPackId = "";
		apexPackOpen = false;
		scrollWheelHintUntilMs = 0L;
	}

	private double clamp01(double value)
	{
		if (value < 0.0d)
		{
			return 0.0d;
		}
		if (value > 1.0d)
		{
			return 1.0d;
		}
		return value;
	}

	private Optional<CardDefinition> findCard(String name)
	{
		return cardDatabase.getCards().stream()
			.filter(Objects::nonNull)
			.filter(c -> c.getName() != null && c.getName().equalsIgnoreCase(name))
			.findFirst();
	}

	private int clickedCardIndex(List<Rectangle> bounds, Point click)
	{
		if (bounds == null || click == null)
		{
			return -1;
		}
		for (int i = 0; i < bounds.size(); i++)
		{
			Rectangle boundsAtIndex = bounds.get(i);
			if (boundsAtIndex != null && boundsAtIndex.contains(click))
			{
				return i;
			}
		}
		return -1;
	}

	private void rebuildRarityTierIndex()
	{
		rarityTierByCardName.clear();
		tierPopulation.clear();
		for (RarityMath.Tier tier : RarityMath.Tier.values())
		{
			tierPopulation.put(tier, 0);
		}

		List<CardDefinition> universe = cardDatabase.getCards();
		Map<String, RarityMath.Tier> tierByName = RarityMath.displayTierByCardName(universe);
		List<CardDefinition> rollPool = rollPoolFilter.filterRollPool(universe);
		cardPoolSize = (int) rollPool.stream()
			.filter(card -> card != null && card.getName() != null && !card.getName().trim().isEmpty())
			.count();

		for (Map.Entry<String, RarityMath.Tier> entry : tierByName.entrySet())
		{
			String name = entry.getKey();
			if (name != null)
			{
				rarityTierByCardName.put(name.toLowerCase(), entry.getValue());
			}
		}

		for (CardDefinition card : universe)
		{
			if (card == null || card.getName() == null || card.getName().trim().isEmpty())
			{
				continue;
			}
			RarityMath.Tier tier = tierByName.getOrDefault(card.getName(), RarityMath.Tier.COMMON);
			tierPopulation.put(tier, tierPopulation.get(tier) + 1);
		}
	}

	private RarityMath.Tier tierForCard(String cardName)
	{
		if (cardName == null)
		{
			return RarityMath.Tier.COMMON;
		}
		return rarityTierByCardName.getOrDefault(cardName.toLowerCase(), RarityMath.Tier.COMMON);
	}

	private String normalizeKey(String cardName, boolean foil)
	{
		return (cardName == null ? "" : cardName.trim().toLowerCase()) + "|" + (foil ? "1" : "0");
	}

	private void playMythicRevealIfAnyUnrevealedMythic()
	{
		if (hasUnrevealedMythic())
		{
			packRevealSoundService.playMythicReveal();
		}
	}

	private void announcePartyMythicPullsForPreviouslyUnrevealedSlots()
	{
		for (int i = 0; i < cards.size(); i++)
		{
			if (i >= revealedByIndex.length || revealedByIndex[i])
			{
				continue;
			}
			RevealCard card = cards.get(i);
			pullNotificationService.notifyPull(
				cardNameForParty(card), card.isNew(), isFoilPull(card), card.getTier());
		}
	}

	private void notifyDinkAtEndOnce()
	{
		if (dinkEndNotificationsSent)
		{
			return;
		}
		dinkEndNotificationsSent = true;
		pullNotificationService.notifyDinkAtEnd(cards);
	}

	/**
	 * Hum loop + {@code reveal.wav}: any Godly-tier card, or a foil whose display tier is one of the three highest
	 * ({@link RarityMath.Tier#LEGENDARY}, {@link RarityMath.Tier#MYTHIC}, {@link RarityMath.Tier#GODLY}).
	 */
	private static boolean isPremiumRevealAudioPull(RevealCard card)
	{
		if (card == null)
		{
			return false;
		}
		if (card.getTier() == RarityMath.Tier.GODLY)
		{
			return true;
		}
		if (!isFoilPull(card))
		{
			return false;
		}
		return card.getTier().ordinal() >= RarityMath.Tier.LEGENDARY.ordinal();
	}

	private static boolean isFoilPull(RevealCard card)
	{
		return card != null && card.getPull() != null && card.getPull().isFoil();
	}

	private static String cardNameForParty(RevealCard card)
	{
		if (card.getDefinition() != null && card.getDefinition().getName() != null
			&& !card.getDefinition().getName().trim().isEmpty())
		{
			return card.getDefinition().getName().trim();
		}
		if (card.getPull() != null && card.getPull().getCardName() != null)
		{
			return card.getPull().getCardName().trim();
		}
		return "";
	}

	private boolean allRevealSlotsFaceUp()
	{
		if (cards.isEmpty() || revealedByIndex.length != cards.size())
		{
			return false;
		}
		for (int i = 0; i < revealedByIndex.length; i++)
		{
			if (!revealedByIndex[i])
			{
				return false;
			}
		}
		return true;
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Pack reveal audio via {@link AudioPlayer}: one-shot premium {@code /hum.wav} per reveal when a qualifying
 * card is still face-down after the pack opens, plus reveal chime, deal motion, flip, apex hover, and transfer sounds.
 */
@Slf4j
@Singleton
public class PackRevealSoundService
{
	private static final String HUM_RESOURCE = "/hum.wav";

	private static final String REVEAL_RESOURCE = "/reveal.wav";
	private static final String CARD_DEAL_RESOURCE = "/card.wav";
	private static final String FLIP_RESOURCE = "/flip.wav";
	private static final String TRANSFER_SUCCESS_RESOURCE = "/transfer.wav";
	private static final String APEX_PACK_HOVER_RESOURCE = "/apex.wav";

	private static final float GAIN_TRANSFER_DB = linearGainToDb(0.5f);
	private static final float GAIN_APEX_HOVER_DB = linearGainToDb(0.425f);

	private final OsrsTcgConfig config;
	private final AudioPlayer audioPlayer;

	private boolean humOpenFailed;
	private boolean humPlayedThisReveal;

	private boolean revealOpenFailed;
	private boolean flipOpenFailed;
	private boolean cardDealOpenFailed;
	private boolean transferSuccessOpenFailed;
	private boolean apexHoverOneShotOpenFailed;

	/** Greatest card index whose deal-start sound has been played this deal phase ({@code -1} = none). */
	private int dealMotionSoundUpToIndex = -1;

	@Inject
	public PackRevealSoundService(OsrsTcgConfig config, AudioPlayer audioPlayer)
	{
		this.config = config;
		this.audioPlayer = audioPlayer;
	}

	/**
	 * Plays {@code hum.wav} at most once per reveal while {@code humWanted} is true.
	 */
	public synchronized void tryPlayMythicHum(boolean humWanted)
	{
		if (!config.enableSounds() || humOpenFailed || humPlayedThisReveal || !humWanted)
		{
			return;
		}

		if (!playResource(HUM_RESOURCE, "hum.wav", 0f))
		{
			humOpenFailed = true;
			return;
		}

		humPlayedThisReveal = true;
	}

	/** One-shot {@code reveal.wav} when a qualifying premium card is flipped (after {@link #playCardFlip()}). */
	public synchronized void playMythicReveal()
	{
		if (!config.enableSounds() || revealOpenFailed)
		{
			return;
		}
		if (!playResource(REVEAL_RESOURCE, "reveal.wav", 0f))
		{
			revealOpenFailed = true;
		}
	}

	/** One-shot {@code flip.wav} when any face-down card is clicked to flip during click-to-reveal. */
	public synchronized void playCardFlip()
	{
		if (!config.enableSounds() || flipOpenFailed)
		{
			return;
		}
		if (!playResource(FLIP_RESOURCE, "flip.wav", 0f))
		{
			flipOpenFailed = true;
		}
	}

	/** One-shot {@code transfer.wav} when a party card transfer completes (sender and recipient); half default gain. */
	public synchronized void playTransferSuccess()
	{
		if (!config.enableTransferSound() || transferSuccessOpenFailed)
		{
			return;
		}
		if (!playResource(TRANSFER_SUCCESS_RESOURCE, "transfer.wav", GAIN_TRANSFER_DB))
		{
			transferSuccessOpenFailed = true;
		}
	}

	/** One-shot {@code apex.wav} when the pointer enters the sealed apex pack (overlapping plays allowed). */
	public synchronized void playApexPackHoverOneShot()
	{
		if (!config.enableSounds() || apexHoverOneShotOpenFailed)
		{
			return;
		}
		if (!playResource(APEX_PACK_HOVER_RESOURCE, "apex.wav", GAIN_APEX_HOVER_DB))
		{
			apexHoverOneShotOpenFailed = true;
		}
	}

	/**
	 * While {@code dealPhaseActive}, plays {@code /card.wav} once per card when its deal flight starts
	 * (same timing as {@link com.bronzemanpvptcg.overlay.PackRevealOverlay}: {@code elapsed >= index * staggerMs}).
	 */
	public synchronized void tickDealMotionSounds(boolean dealPhaseActive, long elapsedMs, int cardCount, long staggerMs)
	{
		if (!dealPhaseActive || !config.enableSounds())
		{
			dealMotionSoundUpToIndex = -1;
			return;
		}

		if (cardCount <= 0 || staggerMs <= 0L || cardDealOpenFailed)
		{
			return;
		}

		while (dealMotionSoundUpToIndex + 1 < cardCount)
		{
			int next = dealMotionSoundUpToIndex + 1;
			if (elapsedMs < next * staggerMs)
			{
				break;
			}
			if (!playResource(CARD_DEAL_RESOURCE, "card.wav", 0f))
			{
				cardDealOpenFailed = true;
				break;
			}
			dealMotionSoundUpToIndex = next;
		}
	}

	/** Resets per-reveal sound state when the overlay closes or the plugin shuts down. */
	public synchronized void hardStop()
	{
		humPlayedThisReveal = false;
		dealMotionSoundUpToIndex = -1;
	}

	private boolean playResource(String resourcePath, String logName, float gainDb)
	{
		if (PackRevealSoundService.class.getResource(resourcePath) == null)
		{
			log.warn("Missing resource {}", resourcePath);
			return false;
		}

		try
		{
			audioPlayer.play(PackRevealSoundService.class, resourcePath, gainDb);
			return true;
		}
		catch (Exception ex)
		{
			log.warn("Could not play {} ({})", logName, resourcePath, ex);
			return false;
		}
	}

	private static float linearGainToDb(float linear01)
	{
		float v = Math.max(0f, Math.min(1f, linear01));
		if (v < 0.0005f)
		{
			return -80f;
		}
		return (float) (20.0 * Math.log10(v));
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.model.PackCardResult;
import com.bronzemanpvptcg.service.PackRevealService.RevealCard;
import com.bronzemanpvptcg.ui.TcgPanel;
import com.bronzemanpvptcg.util.GameWidgetUtil;
import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import java.awt.Color;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.Subscribe;

/**
 * When Safe-mode is enabled, blocks pack purchases during combat and closes an active pack reveal if combat starts.
 */
@Singleton
public final class PackSafeModeService
{
	private final OsrsTcgConfig config;
	private final Client client;
	private final PlayerCombatMonitor combatMonitor;
	private final PackRevealService packRevealService;
	private final CardDatabase cardDatabase;
	private final ChatMessageManager chatMessageManager;
	private final Provider<TcgPanel> tcgPanelProvider;

	private boolean combatStateLastTick;
	private boolean welcomeScreenVisibleLastTick;
	private volatile boolean welcomeScreenVisible;

	@Inject
	public PackSafeModeService(
		OsrsTcgConfig config,
		Client client,
		PlayerCombatMonitor combatMonitor,
		PackRevealService packRevealService,
		CardDatabase cardDatabase,
		ChatMessageManager chatMessageManager,
		Provider<TcgPanel> tcgPanelProvider)
	{
		this.config = config;
		this.client = client;
		this.combatMonitor = combatMonitor;
		this.packRevealService = packRevealService;
		this.cardDatabase = cardDatabase;
		this.chatMessageManager = chatMessageManager;
		this.tcgPanelProvider = tcgPanelProvider;
	}

	public boolean isSafeModeEnabled()
	{
		return config.safeMode();
	}

	public boolean isPackOpeningBlocked()
	{
		return isPackOpeningBlockedByWelcomeScreen() || isPackOpeningBlockedByCombat();
	}

	public boolean isPackOpeningBlockedByCombat()
	{
		return config.safeMode() && combatMonitor.isLocalPlayerInCombat();
	}

	public boolean isPackOpeningBlockedByWelcomeScreen()
	{
		return welcomeScreenVisible;
	}

	public String packOpeningBlockMessage()
	{
		if (isPackOpeningBlockedByWelcomeScreen())
		{
			return "Cannot open packs on the welcome screen.";
		}
		if (isPackOpeningBlockedByCombat())
		{
			return "Cannot open packs while in combat (Safe-mode).";
		}
		return null;
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (!config.safeMode() || !combatMonitor.isLocalPlayerInCombat())
		{
			return;
		}
		maybeCloseRevealForCombat(true);
		tcgPanelProvider.get().refresh();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!config.safeMode() || !combatMonitor.isLocalPlayerInCombat())
		{
			return;
		}
		maybeCloseRevealForCombat(true);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean welcomeScreenVisibleNow = GameWidgetUtil.isWelcomeScreenVisible(client);
		welcomeScreenVisible = welcomeScreenVisibleNow;
		if (welcomeScreenVisibleNow != welcomeScreenVisibleLastTick)
		{
			welcomeScreenVisibleLastTick = welcomeScreenVisibleNow;
			tcgPanelProvider.get().refresh();
		}

		if (!config.safeMode())
		{
			if (combatStateLastTick)
			{
				combatStateLastTick = false;
				tcgPanelProvider.get().refresh();
			}
			return;
		}

		boolean inCombat = combatMonitor.isLocalPlayerInCombat();
		maybeCloseRevealForCombat(inCombat);

		if (inCombat != combatStateLastTick)
		{
			combatStateLastTick = inCombat;
			tcgPanelProvider.get().refresh();
		}
	}

	private void maybeCloseRevealForCombat(boolean inCombat)
	{
		if (inCombat && packRevealService.isActive())
		{
			closeRevealForCombat();
		}
	}

	private void closeRevealForCombat()
	{
		List<RevealCard> cards = packRevealService.abortActiveReveal();
		if (cards.isEmpty())
		{
			return;
		}

		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager,
			"Combat interrupted pack reveal — your cards are in your collection.");

		for (RevealCard card : cards)
		{
			if (card == null || card.getPull() == null)
			{
				continue;
			}
			PackCardResult pull = card.getPull();
			String name = pull.getCardName();
			if (name == null || name.trim().isEmpty())
			{
				continue;
			}
			Color rarity = cardDatabase.chatRarityColorForCardName(name);
			String formatted = TcgPluginGameMessages.formatPrefixedYouAddedCollection(
				name, card.isNew(), pull.isFoil(), rarity);
			String plain = TcgPluginGameMessages.plainPrefixedYouAddedCollection(
				name, card.isNew(), pull.isFoil());
			TcgPluginGameMessages.queueFormattedGameMessage(chatMessageManager, formatted, plain);
		}

		tcgPanelProvider.get().refreshAfterPackRevealClose();
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.util.PlayerCombatUtil;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks whether the local player is in combat for Safe-mode pack restrictions.
 */
@Singleton
public final class PlayerCombatMonitor
{
	private static final int INCOMING_DAMAGE_GRACE_TICKS = 3;

	private final Client client;
	private volatile boolean localPlayerInCombat;
	private int incomingDamageGraceUntilTick = -1;

	@Inject
	public PlayerCombatMonitor(Client client)
	{
		this.client = client;
	}

	public boolean isLocalPlayerInCombat()
	{
		return localPlayerInCombat;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client == null)
		{
			localPlayerInCombat = false;
			incomingDamageGraceUntilTick = -1;
			return;
		}
		int tick = client.getTickCount();
		boolean grace = incomingDamageGraceUntilTick >= tick;
		localPlayerInCombat = grace || PlayerCombatUtil.isLocalPlayerInCombat(client);
		if (!localPlayerInCombat)
		{
			incomingDamageGraceUntilTick = -1;
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return;
		}
		if (event.getSource() == client.getLocalPlayer() && PlayerCombatUtil.isCombatTarget(event.getTarget()))
		{
			localPlayerInCombat = true;
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return;
		}
		if (event.getActor() != client.getLocalPlayer() || event.getHitsplat() == null)
		{
			return;
		}
		if (event.getHitsplat().isMine())
		{
			return;
		}
		incomingDamageGraceUntilTick = client.getTickCount() + INCOMING_DAMAGE_GRACE_TICKS;
		localPlayerInCombat = true;
	}

	public void reset()
	{
		localPlayerInCombat = false;
		incomingDamageGraceUntilTick = -1;
	}

}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.model.DinkNotificationTrigger;
import com.bronzemanpvptcg.model.PullNotifyTier;
import com.bronzemanpvptcg.party.BpvpPullPartyMessage;
import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.party.PartyService;

/**
 * In-game chat (and optional Dink / party) notifications for notable pack pulls.
 */
@Slf4j
@Singleton
public class PullNotificationService
{
	private final OsrsTcgConfig config;
	private final ChatMessageManager chatMessageManager;
	private final CardDatabase cardDatabase;
	private final PartyService partyService;
	private final DinkNotificationService dinkNotificationService;
	private final PullWebhookNotificationService pullWebhookNotificationService;

	@Inject
	PullNotificationService(
		OsrsTcgConfig config,
		ChatMessageManager chatMessageManager,
		CardDatabase cardDatabase,
		PartyService partyService,
		DinkNotificationService dinkNotificationService,
		PullWebhookNotificationService pullWebhookNotificationService)
	{
		this.config = config;
		this.chatMessageManager = chatMessageManager;
		this.cardDatabase = cardDatabase;
		this.partyService = partyService;
		this.dinkNotificationService = dinkNotificationService;
		this.pullWebhookNotificationService = pullWebhookNotificationService;
	}

	public boolean shouldNotify(RarityMath.Tier tier, boolean foil, boolean newForCollection)
	{
		if (config.notifyNewCardsOnly() && !newForCollection && !(foil && config.notifyFoils()))
		{
			return false;
		}
		if (foil)
		{
			if (tier == null)
			{
				return config.notifyFoils();
			}
			PullNotifyTier minimum = config.notifyTier();
			RarityMath.Tier floor = minimum == null ? RarityMath.Tier.MYTHIC : minimum.toRarityTier();
			boolean tierOk = tier.ordinal() >= floor.ordinal();
			return tierOk || config.notifyFoils();
		}
		if (tier == null || !config.notifyNonFoils())
		{
			return false;
		}
		PullNotifyTier minimum = config.notifyTier();
		RarityMath.Tier floor = minimum == null ? RarityMath.Tier.MYTHIC : minimum.toRarityTier();
		return tier.ordinal() >= floor.ordinal();
	}

	public void notifyPull(String cardName, boolean newForCollection, boolean foil, RarityMath.Tier tier)
	{
		if (cardName == null || cardName.trim().isEmpty())
		{
			return;
		}
		String trimmed = cardName.trim();
		boolean standardNotification = shouldNotify(tier, foil, newForCollection);
		if (standardNotification)
		{
			Color rarity = cardDatabase.chatRarityColorForCardName(trimmed);
			String formatted = TcgPluginGameMessages.formatPrefixedYouAddedCollection(trimmed, newForCollection, foil, rarity);
			String plain = TcgPluginGameMessages.plainPrefixedYouAddedCollection(trimmed, newForCollection, foil);
			TcgPluginGameMessages.queueFormattedGameMessage(chatMessageManager, formatted, plain);
		}

		if (config.dinkNotifications() && dinkTrigger() == DinkNotificationTrigger.EVERY_CARD
			&& shouldNotifyDink(tier, foil, newForCollection))
		{
			dinkNotificationService.notifyPackPull(trimmed, newForCollection, foil, tier);
		}

		if (standardNotification)
		{
			pullWebhookNotificationService.notifyPackPull(trimmed, newForCollection, foil, tier);
			notifyParty(trimmed, newForCollection, foil);
		}
		log.debug(
			"Pull notification dispatched for '{}' (foil={}, new={}, tier={}, dink={}, webhookConfigured={})",
			trimmed,
			foil,
			newForCollection,
			tier == null ? "unknown" : tier.getLabel(),
			config.dinkNotifications(),
			isWebhookConfigured());

	}

	private void notifyParty(String cardName, boolean newForCollection, boolean foil)
	{
		if (config.partyAnnounceMythicPulls() && partyService.isInParty())
		{
			try
			{
				BpvpPullPartyMessage message = new BpvpPullPartyMessage();
				message.setCardName(cardName);
				message.setNewForCollection(newForCollection);
				message.setFoil(foil);
				partyService.send(message);
			}
			catch (Exception ex)
			{
				log.debug("Could not send party pull message", ex);
			}
		}
	}

	public void notifyDinkAtEnd(List<PackRevealService.RevealCard> cards)
	{
		if (!config.dinkNotifications() || dinkTrigger() != DinkNotificationTrigger.AT_END
			|| cards == null || cards.isEmpty())
		{
			return;
		}
		List<DinkNotificationService.PackPull> pulls = new ArrayList<>();
		for (PackRevealService.RevealCard card : cards)
		{
			if (card == null || card.getPull() == null || card.getPull().getCardName() == null)
			{
				continue;
			}
			pulls.add(new DinkNotificationService.PackPull(
				card.getPull().getCardName().trim(),
				card.isNew(),
				card.getPull().isFoil(),
				card.getTier(),
				shouldNotifyDink(card.getTier(), card.getPull().isFoil(), card.isNew())));
		}
		dinkNotificationService.notifyPackSummary(pulls);
	}

	private boolean shouldNotifyDink(RarityMath.Tier tier, boolean foil, boolean newForCollection)
	{
		if (!newForCollection && config.dinkOnlyNotifyNew())
		{
			return false;
		}
		if (foil && config.dinkAlwaysNotifyFoils())
		{
			return true;
		}
		if (tier == null)
		{
			return false;
		}
		PullNotifyTier minimum = newForCollection
			? config.dinkNewCardNotifyTier()
			: config.dinkDuplicateNotifyTier();
		RarityMath.Tier floor = minimum == null ? RarityMath.Tier.MYTHIC : minimum.toRarityTier();
		return tier.ordinal() >= floor.ordinal();
	}

	private DinkNotificationTrigger dinkTrigger()
	{
		DinkNotificationTrigger trigger = config.dinkNotificationTrigger();
		return trigger == null ? DinkNotificationTrigger.EVERY_CARD : trigger;
	}

	private boolean isWebhookConfigured()
	{
		String url = config.pullWebhookUrl();
		return url != null && !url.trim().isEmpty();
	}
}

package com.bronzemanpvptcg.service;

import com.google.gson.Gson;
import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.util.PullNotificationMessages;
import java.awt.Color;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Sends rarity-coloured Discord embeds to optional user-configured webhook URL(s).
 */
@Slf4j
@Singleton
public class PullWebhookNotificationService
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String EMBED_TITLE = "Bronzeman PVP TCG";

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final Client client;
	private final OsrsTcgConfig config;
	private final CardDatabase cardDatabase;
	private final WikiImageCacheService wikiImageCacheService;
	private final TcgPublicStatsCalculator tcgPublicStatsCalculator;
	private final TcgChatStatsShareService tcgChatStatsShareService;

	@Inject
	PullWebhookNotificationService(
		OkHttpClient okHttpClient,
		Gson gson,
		Client client,
		OsrsTcgConfig config,
		CardDatabase cardDatabase,
		WikiImageCacheService wikiImageCacheService,
		TcgPublicStatsCalculator tcgPublicStatsCalculator,
		TcgChatStatsShareService tcgChatStatsShareService)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.client = client;
		this.config = config;
		this.cardDatabase = cardDatabase;
		this.wikiImageCacheService = wikiImageCacheService;
		this.tcgPublicStatsCalculator = tcgPublicStatsCalculator;
		this.tcgChatStatsShareService = tcgChatStatsShareService;
	}

	public void notifyPackPull(String cardName, boolean newForCollection, boolean foil, RarityMath.Tier tier)
	{
		String webhookUrl = config.pullWebhookUrl();
		if (webhookUrl == null || webhookUrl.trim().isEmpty())
		{
			log.debug("Pull webhook skipped: no URL configured");
			return;
		}
		if (cardName == null || cardName.trim().isEmpty())
		{
			log.warn("Pull webhook skipped: empty card name");
			return;
		}

		List<HttpUrl> webhookUrls = parseWebhookUrls(webhookUrl);
		if (webhookUrls.isEmpty())
		{
			log.warn("Pull webhook skipped: no valid URLs in config");
			return;
		}

		try
		{
			String card = cardName.trim();
			String imageUrl = resolveCardImageUrl(card);
			String playerName = resolvePlayerName();
			String description = PullNotificationMessages.collectionMessage(playerName, card, newForCollection, foil);
			String statsLine = tcgChatStatsShareService.buildPlainLine(tcgPublicStatsCalculator.computeLive());
			String payload = gson.toJson(buildPayload(description, statsLine, tier, imageUrl));

			log.info(
				"Sending pull webhook for '{}' (foil={}, new={}, tier={}) to {} URL(s) (payload {} bytes, footer {} chars)",
				card,
				foil,
				newForCollection,
				tier == null ? "unknown" : tier.getLabel(),
				webhookUrls.size(),
				payload.length(),
				statsLine.length());

			for (HttpUrl parsedUrl : webhookUrls)
			{
				enqueueWebhook(card, parsedUrl, payload);
			}
		}
		catch (Exception ex)
		{
			log.warn("Pull webhook failed before send for '{}'", cardName.trim(), ex);
		}
	}

	private void enqueueWebhook(String card, HttpUrl parsedUrl, String payload)
	{
		Request request = new Request.Builder()
			.url(parsedUrl)
			.post(RequestBody.create(JSON, payload))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Pull webhook request failed for '{}' ({}): {}", card, maskWebhookUrl(parsedUrl), e.toString());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (response.isSuccessful())
					{
						log.info("Pull webhook sent for '{}' to {} (HTTP {})",
							card, maskWebhookUrl(parsedUrl), response.code());
						return;
					}
					String responseBody = body == null ? "" : body.string();
					log.warn(
						"Pull webhook rejected for '{}' at {} (HTTP {}): {}",
						card,
						maskWebhookUrl(parsedUrl),
						response.code(),
						truncateForLog(responseBody));
				}
				catch (IOException ex)
				{
					log.warn("Pull webhook response read failed for '{}' ({}): {}",
						card, maskWebhookUrl(parsedUrl), ex.toString());
				}
			}
		});
	}

	private static List<HttpUrl> parseWebhookUrls(String raw)
	{
		List<HttpUrl> urls = new ArrayList<>();
		for (String line : raw.split("\\R"))
		{
			String trimmed = line.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}
			HttpUrl parsed = HttpUrl.parse(trimmed);
			if (parsed == null)
			{
				log.warn("Pull webhook skipped invalid URL line: {}", maskWebhookUrl(trimmed));
				continue;
			}
			urls.add(parsed);
		}
		return urls;
	}

	private static String maskWebhookUrl(HttpUrl url)
	{
		if (url == null)
		{
			return "<invalid>";
		}
		return url.scheme() + "://" + url.host() + url.encodedPath();
	}

	private static Map<String, Object> buildPayload(
		String description, String footerText, RarityMath.Tier tier, String imageUrl)
	{
		Map<String, Object> embed = new LinkedHashMap<>();
		embed.put("title", EMBED_TITLE);
		embed.put("description", description);
		embed.put("color", discordColor(tier));
		if (footerText != null && !footerText.isEmpty())
		{
			embed.put("footer", Map.of("text", footerText));
		}
		if (imageUrl != null && !imageUrl.isEmpty())
		{
			embed.put("image", Map.of("url", imageUrl));
		}

		List<Map<String, Object>> embeds = new ArrayList<>();
		embeds.add(embed);
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("embeds", embeds);
		return payload;
	}

	private static int discordColor(RarityMath.Tier tier)
	{
		Color color = tier == null ? Color.WHITE : tier.getColor();
		return (color.getRed() << 16) | (color.getGreen() << 8) | color.getBlue();
	}

	private String resolvePlayerName()
	{
		if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			return "Unknown player";
		}
		return Text.sanitize(client.getLocalPlayer().getName());
	}

	private String resolveCardImageUrl(String cardName)
	{
		return cardDatabase.findByName(cardName)
			.map(CardDefinition::getImageUrl)
			.map(wikiImageCacheService::publicImageUrl)
			.orElse("");
	}

	private static String maskWebhookUrl(String url)
	{
		if (url == null || url.isEmpty())
		{
			return "<empty>";
		}
		return maskWebhookUrl(HttpUrl.parse(url.trim()));
	}

	private static String truncateForLog(String value)
	{
		if (value == null || value.isEmpty())
		{
			return "<empty body>";
		}
		String normalized = value.replace('\n', ' ').trim();
		return normalized.length() <= 300 ? normalized : normalized.substring(0, 300) + "...";
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.BoosterPackDefinition;
import com.bronzemanpvptcg.data.PackCatalog;
import com.bronzemanpvptcg.model.HardModeRate;
import com.bronzemanpvptcg.ui.TcgPanel;
import com.bronzemanpvptcg.util.NumberFormatting;
import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Player;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/**
 * Awards credits for PvP kills — the only external credit source. Normally one kill pays for exactly
 * one standard booster pack; in hard mode the kill pays by loot value instead
 * ({@value #HARD_MODE_CREDITS_PER_CHUNK} credits per {@value #HARD_MODE_LOOT_CHUNK} GP).
 * {@link PlayerLootReceived} fires once when the local player's kill drops a loot pile (wilderness,
 * PvP/Bounty Hunter worlds, LMS); safe activities without loot piles (Clan Wars, duels) award nothing.
 */
@Singleton
public final class PvpKillCreditTracker
{
	private static final long FALLBACK_PACK_PRICE = 2_500L;
	/** Kills worth less than this in loot pay nothing, so scraps are not farmable. */
	private static final long HARD_MODE_MIN_LOOT = 10_000L;

	private final PackCatalog packCatalog;
	private final CreditAwardService creditAwardService;
	private final ChatMessageManager chatMessageManager;
	private final ItemManager itemManager;
	private final TcgStateService stateService;
	private final OsrsTcgConfig config;
	private final TcgPanel tcgPanel;

	@Inject
	public PvpKillCreditTracker(
		PackCatalog packCatalog,
		CreditAwardService creditAwardService,
		ChatMessageManager chatMessageManager,
		ItemManager itemManager,
		TcgStateService stateService,
		OsrsTcgConfig config,
		TcgPanel tcgPanel)
	{
		this.packCatalog = packCatalog;
		this.creditAwardService = creditAwardService;
		this.chatMessageManager = chatMessageManager;
		this.itemManager = itemManager;
		this.stateService = stateService;
		this.config = config;
		this.tcgPanel = tcgPanel;
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		if (event == null || event.getPlayer() == null)
		{
			return;
		}

		Player victim = event.getPlayer();
		String victimName = victim.getName() == null || victim.getName().trim().isEmpty()
			? "another player"
			: victim.getName().trim();

		if (config.hardMode())
		{
			awardHardMode(event, victimName);
			return;
		}

		long packPrice = standardPackPrice();
		if (!creditAwardService.awardPvpKillCredits(victimName, packPrice))
		{
			return;
		}

		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
			"PvP kill on %s: +%s credits — enough for a booster pack!",
			victimName, NumberFormatting.format(packPrice)));
		tcgPanel.refresh();
	}

	/**
	 * Always reports the kill, even when the loot prices out at nothing — an untradeable-only pile
	 * would otherwise look identical to the award never firing at all.
	 */
	private void awardHardMode(PlayerLootReceived event, String victimName)
	{
		long lootValue = lootValue(event);
		long credits = hardModeCredits(lootValue);
		boolean awarded = credits > 0L && creditAwardService.awardPvpKillCredits(victimName, credits);

		if (awarded)
		{
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
				"PvP kill on %s: %s loot -> +%s credits (%s / %s toward a pack).",
				victimName,
				NumberFormatting.format(lootValue),
				NumberFormatting.format(credits),
				NumberFormatting.format(stateService.getCredits()),
				NumberFormatting.format(standardPackPrice())));
			tcgPanel.refresh();
			return;
		}

		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
			lootValue < HARD_MODE_MIN_LOOT
				? "PvP kill on %s: %s loot -> no credits (hard mode needs at least %s in tradeable loot)."
				: "PvP kill on %s: %s loot -> no credits (hard mode pays 1 credit per %s gp).",
			victimName,
			NumberFormatting.format(lootValue),
			NumberFormatting.format(lootValue < HARD_MODE_MIN_LOOT ? HARD_MODE_MIN_LOOT : gpPerPoint())));
	}

	/** Loot value that buys one credit: the default rate, or the player's own when set to Custom. */
	private long gpPerPoint()
	{
		if (config.hardModeRate() != HardModeRate.CUSTOM)
		{
			return HardModeRate.DEFAULT_GP_PER_POINT;
		}
		return Math.max(1L, config.hardModeGpPerPoint());
	}

	/** @return credits for a kill, or 0 when the loot is under the hard-mode minimum. */
	private long hardModeCredits(long lootValue)
	{
		if (lootValue < HARD_MODE_MIN_LOOT)
		{
			return 0L;
		}
		return lootValue / gpPerPoint();
	}

	/** Debug hook ({@code ::btcg-pvp}): runs the real award path against a made-up loot value. */
	public void simulateKill(long lootValue)
	{
		if (!config.hardMode())
		{
			long packPrice = standardPackPrice();
			boolean ok = creditAwardService.awardPvpKillCredits("a test target", packPrice);
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, ok
				? String.format("Test kill: +%s credits (normal mode pays one pack per kill).",
					NumberFormatting.format(packPrice))
				: "Test kill: award blocked (credit cooldown active — try again in a few ticks).");
			tcgPanel.refresh();
			return;
		}

		long credits = hardModeCredits(Math.max(0L, lootValue));
		boolean ok = credits > 0L && creditAwardService.awardPvpKillCredits("a test target", credits);
		TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, String.format(
			"Test kill: %s loot -> %s%s credits. Total %s / %s for a pack.",
			NumberFormatting.format(Math.max(0L, lootValue)),
			ok ? "+" : "",
			NumberFormatting.format(ok ? credits : 0L),
			NumberFormatting.format(stateService.getCredits()),
			NumberFormatting.format(standardPackPrice())));
		tcgPanel.refresh();
	}

	/** Grand Exchange value of the loot pile the kill dropped. */
	private long lootValue(PlayerLootReceived event)
	{
		if (event.getItems() == null)
		{
			return 0L;
		}

		long total = 0L;
		for (ItemStack item : event.getItems())
		{
			if (item == null || item.getQuantity() <= 0)
			{
				continue;
			}
			total += (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
		}
		return total;
	}

	private long standardPackPrice()
	{
		for (BoosterPackDefinition booster : packCatalog.getBoosters())
		{
			if (booster != null && !booster.isDebugOnly() && booster.getPrice() > 0)
			{
				return booster.getPrice();
			}
		}
		return FALLBACK_PACK_PRICE;
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.data.CardDefinition;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;

public final class RarityMath
{
	public enum Tier
	{
		/** Marginal pack tier-roll probability; sums to 100%. Used for approximate "1 in N" on reveal. */
		COMMON("Common", new Color(0xFFFFFF), 37.34d),
		UNCOMMON("Uncommon", new Color(0x2ECC71), 32.0d),
		RARE("Rare", new Color(0x3498DB), 16.0d),
		EPIC("Epic", new Color(0x9B59B6), 8.0d),
		LEGENDARY("Legendary", new Color(0xE74C3C), 4.0d),
		MYTHIC("Mythic", new Color(0xFF6EC7), 2.0d),
		GODLY("Godly", new Color(0xF2C94C), 0.66d);

		private final String label;
		private final Color color;
		private final double chancePercent;

		Tier(String label, Color color, double chancePercent)
		{
			this.label = label;
			this.color = color;
			this.chancePercent = chancePercent;
		}

		public String getLabel()
		{
			return label;
		}

		public Color getColor()
		{
			return color;
		}

		public double getChancePercent()
		{
			return chancePercent;
		}
	}

	private RarityMath()
	{
	}

	private static final double MONSTER_LEVEL_SCORE_MULT = 1.5d;

	private static boolean isMonsterCard(CardDefinition card)
	{
		for (String t : card.getCategoryTags())
		{
			if (t != null && "monster".equals(t.toLowerCase(Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Level contribution to {@link #score} when {@link CardDefinition#getOverrideScore()} is null:
	 * {@code level²} for non-monsters; {@code (level²)×1.5} for Monster category tags.
	 */
	public static double levelBasedScore(CardDefinition card)
	{
		if (card == null || card.getLevel() == null)
		{
			return 0.0d;
		}
		double sq = Math.pow(card.getLevel(), 2);
		return isMonsterCard(card) ? sq * MONSTER_LEVEL_SCORE_MULT : sq;
	}

	/**
	 * {@code max(value, levelPart)} where {@code levelPart} is {@link CardDefinition#getOverrideScore()} when set,
	 * otherwise {@link #levelBasedScore}.
	 */
	public static double score(CardDefinition card)
	{
		if (card == null)
		{
			return 0.0d;
		}
		double valueScore = card.getValue() == null ? 0.0d : card.getValue();
		Long override = card.getOverrideScore();
		if (override != null)
		{
			return Math.max(valueScore, Math.max(0.0d, override.doubleValue()));
		}
		return Math.max(valueScore, levelBasedScore(card));
	}

	/**
	 * Foil contribution for collection score / card face: {@code round(score^1.1)} from {@link #score}.
	 */
	public static long foilAdjustedScoreRounded(CardDefinition card)
	{
		double s = score(card);
		if (s <= 0.0d)
		{
			return 0L;
		}
		return Math.round(Math.pow(s, 1.1d));
	}

	/**
	 * Relative pull weight within a tier pool when scores span a range: lowest score gets weight {@code 1}, highest
	 * gets {@code 1/rarityRatio} ({@code rarityRatio}× rarer), linear in score between. When {@code maxScore <= minScore},
	 * returns {@code 1} so all cards in the pool are equivalent for weighting.
	 *
	 * @param rarityRatio must be {@code >= 1} (e.g. {@code 3} for “top score is 3× rarer than bottom”).
	 */
	public static double linearTierPullWeightByScore(double score, double minScore, double maxScore, double rarityRatio)
	{
		if (rarityRatio < 1.0d)
		{
			rarityRatio = 1.0d;
		}
		if (!(maxScore > minScore))
		{
			return 1.0d;
		}
		double invR = 1.0d / rarityRatio;
		double t = (score - minScore) / (maxScore - minScore);
		if (t < 0.0d)
		{
			t = 0.0d;
		}
		else if (t > 1.0d)
		{
			t = 1.0d;
		}
		return 1.0d - (1.0d - invR) * t;
	}

	/**
	 * Cards with GE {@linkplain CardDefinition#getValue() value} {@code 0} or {@code 1} are always {@link Tier#COMMON}
	 * for display/pack tiering and are omitted from the per-category percentile ordering so other cards keep the same
	 * relative tier cutoffs among themselves.
	 */
	public static boolean isLowValueTierExempt(Long value)
	{
		return value != null && (value == 0L || value == 1L);
	}

	public static Tier tierForPercentile(double percentile)
	{
		if (percentile >= 0.98d)
		{
			return Tier.GODLY;
		}
		if (percentile >= 0.95d)
		{
			return Tier.MYTHIC;
		}
		if (percentile >= 0.90d)
		{
			return Tier.LEGENDARY;
		}
		if (percentile >= 0.75d)
		{
			return Tier.EPIC;
		}
		if (percentile >= 0.50d)
		{
			return Tier.RARE;
		}
		if (percentile >= 0.25d)
		{
			return Tier.UNCOMMON;
		}
		return Tier.COMMON;
	}

	/**
	 * After percentile tiers are assigned on a list sorted by {@link #score} ascending:
	 * <ul>
	 *   <li>All cards with the same non-null {@link CardDefinition#getValue()} get the best tier among that value.</li>
	 *   <li>All cards with the same rounded score get the best tier in that score run (covers null {@code value}).</li>
	 * </ul>
	 */
	public static void unifyTiersForValueAndScoreTies(List<CardDefinition> sortedByScoreAscending, Map<CardDefinition, Tier> tierByCard)
	{
		if (sortedByScoreAscending == null || sortedByScoreAscending.isEmpty() || tierByCard == null)
		{
			return;
		}

		Map<Long, Tier> bestByExactValue = new HashMap<>();
		for (CardDefinition c : sortedByScoreAscending)
		{
			Long v = c == null ? null : c.getValue();
			if (v == null)
			{
				continue;
			}
			Tier t = tierByCard.get(c);
			if (t == null)
			{
				continue;
			}
			bestByExactValue.merge(v, t, RarityMath::maxTier);
		}
		for (CardDefinition c : sortedByScoreAscending)
		{
			if (c == null)
			{
				continue;
			}
			Long v = c.getValue();
			if (v != null)
			{
				Tier best = bestByExactValue.get(v);
				if (best != null)
				{
					tierByCard.put(c, best);
				}
			}
		}

		int i = 0;
		while (i < sortedByScoreAscending.size())
		{
			CardDefinition first = sortedByScoreAscending.get(i);
			int j = i + 1;
			long scoreKey = Math.round(score(first));
			while (j < sortedByScoreAscending.size()
				&& Math.round(score(sortedByScoreAscending.get(j))) == scoreKey)
			{
				j++;
			}
			Tier maxInRun = Tier.COMMON;
			for (int k = i; k < j; k++)
			{
				CardDefinition c = sortedByScoreAscending.get(k);
				Tier t = tierByCard.get(c);
				if (t != null)
				{
					maxInRun = maxTier(maxInRun, t);
				}
			}
			for (int k = i; k < j; k++)
			{
				CardDefinition c = sortedByScoreAscending.get(k);
				if (c != null)
				{
					tierByCard.put(c, maxInRun);
				}
			}
			i = j;
		}
	}

	/**
	 * Display rarity used by the collection album: score percentiles within each {@linkplain CardDefinition#getPrimaryCategory()
	 * primary category} on cards that are not {@linkplain #isLowValueTierExempt(Long) low-GE-value exempt} (value {@code 0}
	 * or {@code 1} are forced to {@link Tier#COMMON} and left out of that percentile pool), then
	 * {@linkplain #unifyTiersForValueAndScoreTies(List, Map) tie unification} inside that tiering subset, then
	 * {@linkplain #unifyTiersGloballyByExactCardValue(List, Map) global lift} by exact GE value. Pack reveal and pack rolls use
	 * the same mapping when built from the same card universe (typically the full loaded catalog).
	 */
	public static Map<String, Tier> displayTierByCardName(List<CardDefinition> allCards)
	{
		Map<String, Tier> tierByName = new HashMap<>();
		if (allCards == null || allCards.isEmpty())
		{
			return tierByName;
		}

		Map<String, List<CardDefinition>> byCategory = allCards.stream()
			.filter(card -> card != null && card.getName() != null && !card.getName().trim().isEmpty())
			.collect(Collectors.groupingBy(CardDefinition::getPrimaryCategory));

		for (List<CardDefinition> pool : byCategory.values())
		{
			if (pool.isEmpty())
			{
				continue;
			}
			List<CardDefinition> tiering = new ArrayList<>();
			for (CardDefinition card : pool)
			{
				if (card == null)
				{
					continue;
				}
				if (isLowValueTierExempt(card.getValue()))
				{
					String name = card.getName();
					if (name != null && !name.trim().isEmpty())
					{
						tierByName.put(name, Tier.COMMON);
					}
					continue;
				}
				tiering.add(card);
			}
			if (tiering.isEmpty())
			{
				continue;
			}
			List<CardDefinition> sorted = new ArrayList<>(tiering);
			sorted.sort((a, b) -> Double.compare(score(a), score(b)));
			int size = sorted.size();
			Map<CardDefinition, Tier> tierByCard = new HashMap<>();
			for (int i = 0; i < size; i++)
			{
				CardDefinition card = sorted.get(i);
				double percentile = size == 1 ? 1.0d : ((double) i / (double) (size - 1));
				tierByCard.put(card, tierForPercentile(percentile));
			}
			unifyTiersForValueAndScoreTies(sorted, tierByCard);
			for (int i = 0; i < size; i++)
			{
				CardDefinition card = sorted.get(i);
				Tier tier = tierByCard.getOrDefault(card, Tier.COMMON);
				tierByName.put(card.getName(), tier);
			}
		}

		unifyTiersGloballyByExactCardValue(allCards, tierByName);

		for (CardDefinition c : allCards)
		{
			if (c == null || c.getName() == null || c.getName().trim().isEmpty())
			{
				continue;
			}
			if (isLowValueTierExempt(c.getValue()))
			{
				tierByName.put(c.getName(), Tier.COMMON);
			}
		}

		return tierByName;
	}

	/**
	 * After per-card tiers are known (e.g. per-category percentiles), lift every card that shares the same
	 * non-null {@link CardDefinition#getValue()} to the best tier seen for that value anywhere in the list.
	 */
	public static void unifyTiersGloballyByExactCardValue(List<CardDefinition> allCards, Map<String, Tier> tierByName)
	{
		if (allCards == null || allCards.isEmpty() || tierByName == null)
		{
			return;
		}
		Map<Long, Tier> bestByValue = new HashMap<>();
		for (CardDefinition c : allCards)
		{
			if (c == null || c.getName() == null || c.getName().trim().isEmpty())
			{
				continue;
			}
			Long v = c.getValue();
			if (v == null)
			{
				continue;
			}
			Tier t = tierByName.get(c.getName());
			if (t == null)
			{
				continue;
			}
			bestByValue.merge(v, t, RarityMath::maxTier);
		}
		for (CardDefinition c : allCards)
		{
			if (c == null || c.getName() == null || c.getName().trim().isEmpty())
			{
				continue;
			}
			Long v = c.getValue();
			if (v == null)
			{
				continue;
			}
			Tier best = bestByValue.get(v);
			if (best != null)
			{
				tierByName.put(c.getName(), best);
			}
		}
	}

	public static Tier maxTier(Tier a, Tier b)
	{
		if (a == null)
		{
			return b == null ? Tier.COMMON : b;
		}
		if (b == null)
		{
			return a;
		}
		return a.ordinal() >= b.ordinal() ? a : b;
	}

	static long denominatorForTierCard(Tier tier, int cardsInTier)
	{
		int safeCards = Math.max(1, cardsInTier);
		double tierChance = Math.max(0.0001d, tier.getChancePercent() / 100.0d);
		return Math.max(1L, Math.round((double) safeCards / tierChance));
	}
}

package com.bronzemanpvptcg.service;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Remembers recently processed party-message ids for replay protection, evicting the
 * oldest id once over capacity. A wholesale clear would also forget the newest ids,
 * reopening the replay window this set exists to close.
 */
final class RecentIdSet
{
	private final Set<String> ids;

	RecentIdSet(int capacity)
	{
		ids = Collections.newSetFromMap(new LinkedHashMap<String, Boolean>()
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest)
			{
				return size() > capacity;
			}
		});
	}

	/** @return false if the id was already present, i.e. a replayed message. */
	synchronized boolean add(String id)
	{
		return ids.add(id);
	}

	/** True if the id was already recorded, without inserting it. */
	synchronized boolean contains(String id)
	{
		return ids.contains(id);
	}

	/** Forget an id whose message failed, so a retried message is not treated as a replay. */
	synchronized void remove(String id)
	{
		ids.remove(id);
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.model.DefenceLevel;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Roll pool is the loaded catalog minus anything the configured {@link DefenceLevel} cannot equip;
 * quest-only item rows are omitted at {@code Card.json} build time.
 */
@Singleton
public final class RollPoolFilter
{
	private final OsrsTcgConfig config;

	@Inject
	public RollPoolFilter(OsrsTcgConfig config)
	{
		this.config = config;
	}

	public List<CardDefinition> filterRollPool(List<CardDefinition> cards)
	{
		if (cards == null || cards.isEmpty())
		{
			return List.of();
		}

		DefenceLevel level = config.defenceLevel();
		boolean consumables = config.consumableCards();
		boolean unrestricted = level == null || level.isUnrestricted();
		if (unrestricted && consumables)
		{
			return cards;
		}

		int cap = unrestricted ? Integer.MAX_VALUE : level.getMaxRequirement();
		List<CardDefinition> allowed = new ArrayList<>(cards.size());
		for (CardDefinition card : cards)
		{
			if (card == null || card.defenceRequirementLevel() > cap)
			{
				continue;
			}
			// A consumable card is dead weight unless its lock is switched on.
			if (card.isConsumableCard() && !consumables)
			{
				continue;
			}
			allowed.add(card);
		}
		return List.copyOf(allowed);
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.OsrsTcgConfig;
import com.bronzemanpvptcg.data.BoosterPackDefinition;
import com.bronzemanpvptcg.data.PackCatalog;
import com.bronzemanpvptcg.util.TcgPluginGameMessages;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;

/**
 * Game-chat notifications when credit gains cross a booster pack purchase threshold.
 */
@Singleton
public class ShopNotificationService
{
	private final OsrsTcgConfig config;
	private final PackCatalog packCatalog;
	private final TcgStateService stateService;
	private final ChatMessageManager chatMessageManager;
	private final Notifier notifier;

	@Inject
	ShopNotificationService(
		OsrsTcgConfig config,
		PackCatalog packCatalog,
		TcgStateService stateService,
		ChatMessageManager chatMessageManager,
		Notifier notifier)
	{
		this.config = config;
		this.packCatalog = packCatalog;
		this.stateService = stateService;
		this.chatMessageManager = chatMessageManager;
		this.notifier = notifier;
	}

	public void onCreditsIncreased(long creditsBefore, long creditsAfter)
	{
		if (!config.shopNotifications() || creditsAfter <= creditsBefore)
		{
			return;
		}

		List<BoosterPackDefinition> boosters = new ArrayList<>(
			packCatalog.getVisibleBoosters(stateService.isDebugLogging()));
		boosters.sort(Comparator
			.comparingInt((BoosterPackDefinition b) -> b == null ? Integer.MAX_VALUE : b.getPrice())
			.thenComparing(b -> b == null || b.getName() == null ? "" : b.getName(),
				String.CASE_INSENSITIVE_ORDER));

		for (BoosterPackDefinition booster : boosters)
		{
			if (booster == null)
			{
				continue;
			}

			int price = booster.getPrice();
			if (price <= 0 || creditsBefore >= price || creditsAfter < price)
			{
				continue;
			}

			String message = "You have enough credits to purchase " + packDisplayName(booster) + "!";
			TcgPluginGameMessages.queuePrefixedGameMessage(chatMessageManager, message);

			if (config.runeliteNotifications())
			{
				notifier.notify(message);
			}
		}
	}

	private static String packDisplayName(BoosterPackDefinition booster)
	{
		if (booster.getName() != null && !booster.getName().trim().isEmpty())
		{
			return booster.getName().trim();
		}
		if (booster.getId() != null && !booster.getId().trim().isEmpty())
		{
			return booster.getId().trim();
		}
		return "a pack";
	}
}

package com.bronzemanpvptcg.service;

import com.bronzemanpvptcg.model.TcgPublicStats;
import com.bronzemanpvptcg.party.BpvpChatStatsPartyMessage;
import com.bronzemanpvptcg.util.NumberFormatting;
import java.util.Locale;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.Text;

/**
 * Caches recent {@link TcgPublicStats} per sanitized RSN (from {@code !tcg} submit + party payloads) so chat
 * substitution works like stock {@code !layout} without a dedicated RuneLite HTTP chat API.
 */
@Singleton
public class TcgChatStatsShareService
{
	private static final long CACHE_TTL_MS = 15L * 60L * 1000L;

	private static final class CacheEntry
	{
		private final TcgPublicStats stats;
		private final long storedAtMs;

		private CacheEntry(TcgPublicStats stats, long storedAtMs)
		{
			this.stats = stats;
			this.storedAtMs = storedAtMs;
		}
	}

	private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();

	@Inject
	public TcgChatStatsShareService()
	{
	}

	public void putSanitizedPlayerName(String sanitizedRsn, TcgPublicStats stats)
	{
		if (sanitizedRsn == null || sanitizedRsn.isEmpty() || stats == null)
		{
			return;
		}
		String key = normalizeKey(sanitizedRsn);
		cache.put(key, new CacheEntry(stats, System.currentTimeMillis()));
	}

	public TcgPublicStats getBySanitizedPlayerName(String sanitizedRsn)
	{
		if (sanitizedRsn == null || sanitizedRsn.isEmpty())
		{
			return null;
		}
		String key = normalizeKey(sanitizedRsn);
		CacheEntry e = cache.get(key);
		if (e == null)
		{
			return null;
		}
		if (System.currentTimeMillis() - e.storedAtMs > CACHE_TTL_MS)
		{
			cache.remove(key, e);
			return null;
		}
		return e.stats;
	}

	public void ingestPartyMessage(BpvpChatStatsPartyMessage message, PartyService partyService)
	{
		if (message == null || partyService == null)
		{
			return;
		}
		PartyMember author = partyService.getMemberById(message.getMemberId());
		if (author == null)
		{
			return;
		}
		String dn = author.getDisplayName();
		if (dn == null || dn.trim().isEmpty())
		{
			return;
		}
		TcgPublicStats stats = new TcgPublicStats(
			message.getCollectionScore(),
			message.getCompletionPct(),
			message.getUniqueOwned(),
			message.getUniqueFoilOwned(),
			message.getFoilCompletionPct(),
			message.getTotalCardPool(),
			message.getOpenedPacks(),
			message.getTotalCardsOwned(),
			message.isCustomRates());
		putSanitizedPlayerName(Text.sanitize(dn), stats);
	}

	public String buildColoredLine(TcgPublicStats s)
	{
		return buildFormattedLine(s, true);
	}

	public String buildPlainLine(TcgPublicStats s)
	{
		return buildFormattedLine(s, false);
	}

	private static String buildFormattedLine(TcgPublicStats s, boolean colored)
	{
		String pct = String.format(Locale.US, "%.1f%%", s.getCompletionPct());
		String foilPct = String.format(Locale.US, "%.1f%%", s.getFoilCompletionPct());
		if (colored)
		{
			ChatMessageBuilder builder = new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append("Collection score: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getCollectionScore()))
				.append(ChatColorType.NORMAL)
				.append(" (")
				.append(ChatColorType.HIGHLIGHT)
				.append(pct)
				.append(ChatColorType.NORMAL)
				.append("), Unique cards: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getUniqueOwned()))
				.append(ChatColorType.NORMAL)
				.append(" / ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getTotalCardPool()))
				.append(ChatColorType.NORMAL)
				.append(" (")
				.append(ChatColorType.HIGHLIGHT)
				.append(pct)
				.append(ChatColorType.NORMAL)
				.append("), Unique foil cards: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getUniqueFoilOwned()))
				.append(ChatColorType.NORMAL)
				.append(" / ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getTotalCardPool()))
				.append(ChatColorType.NORMAL)
				.append(" (")
				.append(ChatColorType.HIGHLIGHT)
				.append(foilPct)
				.append(ChatColorType.NORMAL)
				.append("), Opened packs: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getOpenedPacks()))
				.append(ChatColorType.NORMAL)
				.append(", Total cards: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(NumberFormatting.format(s.getTotalCardsOwned()));
			if (s.isCustomRates())
			{
				builder.append(ChatColorType.NORMAL)
					.append(" (custom rates)");
			}
			return builder.build();
		}

		StringBuilder plain = new StringBuilder()
			.append("Collection score: ")
			.append(NumberFormatting.format(s.getCollectionScore()))
			.append(" (")
			.append(pct)
			.append("), Unique cards: ")
			.append(NumberFormatting.format(s.getUniqueOwned()))
			.append(" / ")
			.append(NumberFormatting.format(s.getTotalCardPool()))
			.append(" (")
			.append(pct)
			.append("), Unique foil cards: ")
			.append(NumberFormatting.format(s.getUniqueFoilOwned()))
			.append(" / ")
			.append(NumberFormatting.format(s.getTotalCardPool()))
			.append(" (")
			.append(foilPct)
			.append("), Opened packs: ")
			.append(NumberFormatting.format(s.getOpenedPacks()))
			.append(", Total cards: ")
			.append(NumberFormatting.format(s.getTotalCardsOwned()));
		if (s.isCustomRates())
		{
			plain.append(" (custom rates)");
		}
		return plain.toString();
	}

	private static String normalizeKey(String sanitizedRsn)
	{
		return sanitizedRsn.trim().toLowerCase(Locale.ROOT);
	}
}

