	private void saveWhitelist(String raw)
	{
		String cleaned = raw == null ? "" : raw.replaceAll("\\s*,\\s*", ", ").trim();
		if (cleaned.equals(config.itemWhitelist()))
		{
			return;
		}
		configManager.setConfiguration(OsrsTcgConfig.GROUP, "itemWhitelist", cleaned);
	}


