	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setOpaque(false);
		String shortLabel = labelText.length() > 36 ? labelText.substring(0, 33) + "..." : labelText;
