	public static String format(String pulledByUsername, long pulledAtEpochMs, boolean locked)
	{
		String displayBy = OwnedCardInstance.formatPulledByForUi(pulledByUsername);
		long at = Math.max(0L, pulledAtEpochMs);
		StringBuilder sb = new StringBuilder();
		if (!displayBy.isEmpty())
		{
			sb.append("Pulled by: ").append(displayBy);
		}
		if (at > 0L)
		{
			if (sb.length() > 0)
			{
				sb.append('\n');
			}
			String when = DateTimeFormatter.ofLocalizedDateTime(FormatStyle.SHORT)
				.format(Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()));
			sb.append(when);
		}
		if (locked)
		{
			if (sb.length() > 0)
			{
				sb.append('\n');
			}
			sb.append("Locked");
		}
		return sb.length() == 0 ? null : sb.toString();
	}
}

package com.bronzemanpvptcg.ui.collectionalbum;

import com.bronzemanpvptcg.data.CardDefinition;
import com.bronzemanpvptcg.service.RarityMath;
import com.bronzemanpvptcg.ui.SharedCardRenderer;
import java.awt.Color;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Rarity colors for the collection album; tiers come from {@link RarityMath#displayTierByCardName(List)} (same as pack reveal).
 * Prefer {@link #fromColorByCardName(Map)} when colours were already computed at catalog load.
 */
public final class AlbumRarityTable
{
	private final Map<String, Color> colorByCardName;

	private AlbumRarityTable(Map<String, Color> colorByCardName)
	{
		this.colorByCardName = colorByCardName;
	}

	/**
	 * Wraps a precomputed colour map (exact card-name keys) without copying. Prefer this over
	 * {@link #build(List)} when colours were already produced at catalog load. Caller must not mutate
	 * the map afterward (e.g. {@link com.bronzemanpvptcg.data.CardDatabase#displayRarityColorsByCardName()}).
	 */
	public static AlbumRarityTable fromColorByCardName(Map<String, Color> colorByCardName)
	{
		if (colorByCardName == null || colorByCardName.isEmpty())
		{
			return new AlbumRarityTable(Map.of());
		}
		return new AlbumRarityTable(colorByCardName);
	}

	public static AlbumRarityTable build(List<CardDefinition> allCards)
	{
		Map<String, Color> map = new HashMap<>();
		if (allCards == null || allCards.isEmpty())
		{
			return new AlbumRarityTable(map);
		}

		Map<String, RarityMath.Tier> tierByName = RarityMath.displayTierByCardName(allCards);
		for (CardDefinition card : allCards)
		{
			if (card == null || card.getName() == null || card.getName().trim().isEmpty())
			{
				continue;
			}
			RarityMath.Tier tier = tierByName.getOrDefault(card.getName(), RarityMath.Tier.COMMON);
			map.put(card.getName(), tier.getColor());
		}
		return new AlbumRarityTable(map);
	}

	public Color colorForCardName(String cardName)
	{
		if (cardName == null)
		{
			return Color.WHITE;
		}
		return colorByCardName.getOrDefault(cardName, Color.WHITE);
	}

	public String tierLabelForCard(CardDefinition card)
	{
		if (card == null || card.getName() == null)
		{
			return "Common";
		}
		return SharedCardRenderer.tierLabelForRarityColor(colorForCardName(card.getName()));
	}
}

package com.bronzemanpvptcg.ui.collectionalbum;

import com.bronzemanpvptcg.data.CardDefinition;
import java.awt.Color;

public final class AlbumSlot
{
	private final CardDefinition card;
	private final Color rarityColor;
	private final boolean ownedAny;
	private final boolean displayFoil;
	private final int nonFoilQty;
	private final int foilQty;
	/** Non-null only when exactly one copy is owned; shown as album hover text. */
	private final String singleCopyHoverTooltip;
	private final boolean lockBadge;
	/** Set when exactly one owned copy exists; used for right-click lock toggle on the album grid. */
	private final String soleInstanceId;
	/** True when at least one owned copy of this card is offered in the active party trade. */
	private final boolean offeredInTrade;

	public AlbumSlot(CardDefinition card, Color rarityColor, boolean ownedAny, boolean displayFoil,
		int nonFoilQty, int foilQty, String singleCopyHoverTooltip, boolean lockBadge, String soleInstanceId)
	{
		this(card, rarityColor, ownedAny, displayFoil, nonFoilQty, foilQty, singleCopyHoverTooltip, lockBadge,
			soleInstanceId, false);
	}

	public AlbumSlot(CardDefinition card, Color rarityColor, boolean ownedAny, boolean displayFoil,
		int nonFoilQty, int foilQty, String singleCopyHoverTooltip, boolean lockBadge, String soleInstanceId,
		boolean offeredInTrade)
	{
		this.card = card;
		this.rarityColor = rarityColor;
		this.ownedAny = ownedAny;
		this.displayFoil = displayFoil;
		this.nonFoilQty = Math.max(0, nonFoilQty);
		this.foilQty = Math.max(0, foilQty);
		this.singleCopyHoverTooltip = singleCopyHoverTooltip == null || singleCopyHoverTooltip.isEmpty()
			? null
			: singleCopyHoverTooltip;
		this.lockBadge = lockBadge;
		this.soleInstanceId = soleInstanceId == null || soleInstanceId.isEmpty() ? null : soleInstanceId;
		this.offeredInTrade = offeredInTrade;
	}

	public CardDefinition card()
	{
		return card;
	}

	public Color rarityColor()
	{
		return rarityColor;
	}

	public boolean ownedAny()
	{
		return ownedAny;
	}

	public boolean displayFoil()
	{
		return displayFoil;
	}

	public int nonFoilQty()
	{
		return nonFoilQty;
	}

	public int foilQty()
	{
		return foilQty;
	}

	public int totalOwnedQty()
	{
		return nonFoilQty + foilQty;
	}

	public String singleCopyHoverTooltip()
	{
		return singleCopyHoverTooltip;
	}

	public boolean lockBadge()
	{
		return lockBadge;
	}

	public String soleInstanceId()
	{
		return soleInstanceId;
	}

	public boolean offeredInTrade()
	{
		return offeredInTrade;
	}
}

