	private final class OfferPanel extends JPanel
	{
		private final boolean localSide;
		private List<TradeOfferView> offers = List.of();
		private List<Rectangle> cardBounds = List.of();

		OfferPanel(boolean localSide)
		{
			this.localSide = localSide;
			setOpaque(true);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(new EmptyBorder(0, 0, 0, 0));
			setToolTipText("");
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (!localSide || !javax.swing.SwingUtilities.isLeftMouseButton(e))
					{
						return;
					}
					int idx = hitIndex(e.getX(), e.getY());
					if (idx < 0 || idx >= offers.size())
					{
						return;
					}
					TradeOfferView o = offers.get(idx);
					String err = tradeService.removeOfferedCard(o.getCardInstanceId());
					if (err != null)
					{
						statusLabel.setText(err);
					}
					refreshFromService();
				}
			});
		}

		void setOffers(List<TradeOfferView> next)
		{
			this.offers = next == null ? List.of() : List.copyOf(next);
			revalidate();
			repaint();
		}

		@Override
		public String getToolTipText(MouseEvent event)
		{
			if (event == null)
			{
				return null;
			}
			int idx = hitIndex(event.getX(), event.getY());
			if (idx < 0 || idx >= offers.size())
			{
				return null;
			}
			TradeOfferView o = offers.get(idx);
			return AlbumInstanceTooltip.format(o.getPulledByUsername(), o.getPulledAtEpochMs(), false);
		}

		@Override
		public Dimension getPreferredSize()
		{
			int cW = cardWidth();
			int cH = cardHeight();
			int rows = offers.isEmpty() ? VISIBLE_ROWS : (offers.size() + COLS - 1) / COLS;
			int width = GAP + COLS * (cW + GAP);
			int height = GAP + Math.max(VISIBLE_ROWS, rows) * (cH + GAP);
			return new Dimension(width, height);
		}

		private int hitIndex(int x, int y)
		{
			for (int i = 0; i < cardBounds.size(); i++)
			{
				if (cardBounds.get(i).contains(x, y))
				{
					return i;
				}
			}
			return -1;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			Graphics2D g2 = (Graphics2D) g.create();
			List<Rectangle> painted = new ArrayList<>();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.clipRect(0, 0, getWidth(), getHeight());
				Insets ins = getInsets();
				if (offers.isEmpty())
				{
					g2.setColor(new Color(0xAAAAAA));
					g2.setFont(FontManager.getRunescapeSmallFont());
					String empty = localSide ? "No cards offered" : "Waiting for offers…";
					g2.drawString(empty, ins.left + 12, ins.top + 20);
					cardBounds = Collections.emptyList();
					return;
				}

				int cW = cardWidth();
				int cH = cardHeight();
				int colW = cW + GAP;
				int rowH = cH + GAP;

				for (int i = 0; i < offers.size(); i++)
				{
					int col = i % COLS;
					int row = i / COLS;
					int x = ins.left + GAP + col * colW;
					int y = ins.top + GAP + row * rowH;
					Rectangle bounds = new Rectangle(x, y, cW, cH);
					painted.add(bounds);

					TradeOfferView offer = offers.get(i);
					CardDefinition card = cardDatabase.findByName(offer.getCardName()).orElse(null);
					Color rarity = cardDatabase.chatRarityColorForCardName(offer.getCardName());
					BufferedImage art = imageCacheService.getCached(card == null ? null : card.getImageUrl());
					SharedCardRenderer.drawCardFace(g2, bounds, card, offer.isFoil(), rarity, art, 0L, offer.isFoil());
				}
			}
			finally
			{
				g2.dispose();
				cardBounds = painted;
			}
		}
	}
}

package com.bronzemanpvptcg.ui.trade;

import com.bronzemanpvptcg.data.CardDatabase;
import com.bronzemanpvptcg.service.CardPartyTradeService;
import com.bronzemanpvptcg.service.WikiImageCacheService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;

@Singleton
public final class TradeWindowManager
{
	private final CardDatabase cardDatabase;
	private final WikiImageCacheService imageCacheService;
	private final CardPartyTradeService tradeService;

	private volatile TradeWindow window;

	@Inject
	public TradeWindowManager(
		CardDatabase cardDatabase,
		WikiImageCacheService imageCacheService,
		CardPartyTradeService tradeService)
	{
		this.cardDatabase = cardDatabase;
		this.imageCacheService = imageCacheService;
		this.tradeService = tradeService;
	}

	public void showOrBringToFront()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window == null || !window.isDisplayable())
			{
				window = new TradeWindow(cardDatabase, imageCacheService, tradeService);
			}
			window.prepareToShow();
			window.setVisible(true);
			window.toFront();
		});
	}

	public void refreshIfVisible()
	{
		SwingUtilities.invokeLater(() ->
		{
			TradeWindow w = window;
			if (tradeService.isTradeActive())
			{
				if (w != null && w.isShowing())
				{
					w.refreshFromService();
				}
				return;
			}
			if (w != null && w.isShowing())
			{
				w.hideWithoutCancel();
			}
		});
	}

	public void hide()
	{
		SwingUtilities.invokeLater(() ->
		{
			TradeWindow w = window;
			if (w != null)
			{
				w.hideWithoutCancel();
			}
		});
	}

	public void dispose()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window != null)
			{
				window.disposeInternal();
				window = null;
			}
		});
	}
}

package com.bronzemanpvptcg.util;

import java.awt.Dimension;
import java.awt.GraphicsEnvironment;
import java.awt.Rectangle;

/** Bounds for the collection album frame; persisted size is clamped to these limits. */
public final class CollectionAlbumWindowSizeUtil
{
	public static final int MIN_WIDTH = 1300;
	public static final int MIN_HEIGHT = 810;

	private CollectionAlbumWindowSizeUtil()
	{
	}

	public static boolean isStoredSize(int width, int height)
	{
		return width > 0 && height > 0;
	}

	public static Dimension resolve(int storedWidth, int storedHeight)
	{
		if (!isStoredSize(storedWidth, storedHeight))
		{
			return new Dimension(MIN_WIDTH, MIN_HEIGHT);
		}
		return clamp(storedWidth, storedHeight);
	}

	public static Dimension clamp(int width, int height)
	{
		int w = Math.max(MIN_WIDTH, width);
		int h = Math.max(MIN_HEIGHT, height);
		Rectangle max = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
		if (max != null)
		{
			w = Math.min(w, max.width);
			h = Math.min(h, max.height);
		}
		return new Dimension(w, h);
	}
}

