package com.bronzemanpvptcg.util;

/**
 * Consistent display: group thousands with a space (e.g. {@code 1 234 567}).
 */
public final class NumberFormatting
{
	private NumberFormatting()
	{
	}

	public static String format(long value)
	{
		return formatWithSpaces(value);
	}

	public static String format(Long value)
	{
		return value == null ? "-" : formatWithSpaces(value);
	}

	public static String format(int value)
	{
		return formatWithSpaces((long) value);
	}

	private static String formatWithSpaces(long value)
	{
		String sign = value < 0 ? "-" : "";
		String digits = Long.toString(Math.abs(value));
		StringBuilder out = new StringBuilder();
		for (int i = 0; i < digits.length(); i++)
		{
			if (i > 0 && ((digits.length() - i) % 3 == 0))
			{
				out.append(' ');
			}
			out.append(digits.charAt(i));
		}
		return sign + out;
	}
}

package com.bronzemanpvptcg.util;

public final class PackRevealZoomUtil
{
	public static final double MIN = 0.35d;
	public static final double MAX = 2.5d;

	private PackRevealZoomUtil()
	{
	}

	public static double clamp(double value)
	{
		if (Double.isNaN(value) || Double.isInfinite(value))
		{
			return 1.0d;
		}
		return Math.max(MIN, Math.min(MAX, value));
	}
}

package com.bronzemanpvptcg.util;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;

/**
 * Detects whether the local player is in active combat: attacking a player/NPC or being targeted by one.
 */
public final class PlayerCombatUtil
{
	private PlayerCombatUtil()
	{
	}

	public static boolean isLocalPlayerInCombat(Client client)
	{
		if (client == null)
		{
			return false;
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		Actor target = local.getInteracting();
		if (target != null && isCombatTarget(target))
		{
			return true;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView != null)
		{
			for (NPC npc : worldView.npcs())
			{
				if (npc != null && !NpcExclusions.isExcludedNpc(npc) && npc.getInteracting() == local)
				{
					return true;
				}
			}

			for (Player other : worldView.players())
			{
				if (other != null && other != local && other.getInteracting() == local)
				{
					return true;
				}
			}
		}

		return false;
	}

	public static boolean isCombatTarget(Actor actor)
	{
		if (actor instanceof Player)
		{
			return true;
		}
		if (actor instanceof NPC)
		{			
			return !NpcExclusions.isExcludedNpc((NPC) actor);
		}
		return false;
	}
}

package com.bronzemanpvptcg.util;

import java.util.List;

public final class PullNotificationMessages
{
	private PullNotificationMessages()
	{
	}

	public static String collectionMessage(String playerName, String cardName, boolean newForCollection, boolean foil)
	{
		String who = playerName == null || playerName.trim().isEmpty() ? "Unknown player" : playerName.trim();
		String card = cardName == null ? "" : cardName.trim();
		String duplicatePrefix = newForCollection ? "" : "duplicate ";
		String foilSuffix = foil ? " (foil)" : "";
		return who + " just added " + duplicatePrefix + card + foilSuffix + " to their collection!";
	}

	public static String dinkCollectionMessage(String cardName, boolean newForCollection, boolean foil)
	{
		return collectionMessage("%USERNAME%", cardName, newForCollection, foil);
	}

	public static String dinkPackSummaryMessage(List<String> newCards, List<String> duplicates)
	{
		StringBuilder message = new StringBuilder("%USERNAME% opened a booster pack!");
		appendCardSection(message, "New cards", newCards);
		appendCardSection(message, "Duplicates", duplicates);
		return message.toString();
	}

	private static void appendCardSection(StringBuilder message, String heading, List<String> cards)
	{
		if (cards == null || cards.isEmpty())
		{
			return;
		}
		message.append("\n\n**").append(heading).append("**");
		for (String card : cards)
		{
			if (card == null || card.trim().isEmpty())
			{
				continue;
			}
			message.append("\n- ").append(card);
		}
	}
}

